  EKC6.fen = (EKC6.fen || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir öğrenci gezegenleri bir özelliğe göre iki gruba ayırıyor:\n\n1. grup: Merkür, Venüs\n2. grup: Dünya, Mars, Jüpiter, Satürn, Uranüs, Neptün\n\nÖğrenci gezegenleri hangi özelliğe göre gruplandırmıştır?", o:["Halkası olup olmamasına","Karasal ya da gazsal yapıda olmasına","Uydusu olup olmamasına","Hacim bakımından büyüklüğüne"], a:2,
     w:"Kitaba göre Merkür ve Venüs'ün uydusu yoktur, diğer altı gezegenin uydusu vardır. Halkaya ya da yapıya göre ayrılsaydı Dünya ve Mars da 1. grupta olurdu."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir gece gökyüzünü izleyen Zeynep, dolunay evresindeki Ay'ın bir süre karardığını ve parlak görünmediğini fark ediyor.\n\nZeynep'in gözlemlediği olayla ilgili hangisi doğrudur?", o:["Ay, Dünya'nın gölgesinde kalmıştır","Ay, Güneş ile Dünya'nın arasına girmiştir","Ay'ın gölgesi Dünya'nın üzerine düşmüştür","Olay Dünya'nın her yerinden gündüz izlenir"], a:0,
     w:"Ay tutulmasında Dünya, Güneş ile Ay'ın arasına girer. Ay, Dünya'nın gölgesinde kaldığı için bir süre parlak görünmez. Bu olay dolunayda ve gece gözlenir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir kutuya aynı doğrultuda üç kuvvet uygulanıyor: doğu yönünde 25 N ve 15 N, batı yönünde 30 N.\n\nKutuya etki eden bileşke kuvvet hangisidir?", o:["70 N, doğu yönünde","10 N, batı yönünde","20 N, batı yönünde","10 N, doğu yönünde"], a:3,
     w:"Aynı yöndeki kuvvetler toplanır: 25 + 15 = 40 N (doğu). Zıt yöndeki kuvvet çıkarılır: 40 − 30 = 10 N. Bileşke, büyük olan kuvvetin yönünde yani doğuya doğrudur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Evinden çıkan Elif, 300 m doğudaki kırtasiyeye yürüyor ve aynı yoldan evine geri dönüyor. Gidiş ve dönüş toplam 10 dakika sürüyor.\n\nElif'in bu hareketteki sürati ve hızı için hangisi doğrudur?", o:["Sürati 1 m/s, hızı sıfırdır","Sürati sıfır, hızı 1 m/s'dir","Sürati ve hızı 1 m/s'dir","Sürati 0,5 m/s, hızı sıfırdır"], a:0,
     w:"Alınan yol 300 + 300 = 600 m, süre 10 dakika = 600 s. Sürat = 600 ÷ 600 = 1 m/s. Elif başladığı yere döndüğü için yer değiştirmesi sıfırdır, bu yüzden hızı da sıfırdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir bahçıvan, çok beğendiği kırmızı çiçekli gülün aynı özellikte yeni güllerini elde etmek istiyor.\n\nBahçıvan hangi yolu seçmelidir?", o:["Tohum ekmeli, eşeyli üremede yavru ana bitkinin aynısıdır","Dal dikmeli, eşeysiz üremede yavru ana bitkinin aynısıdır","Dal dikmeli, eşeysiz üremede yavrunun özellikleri değişir","Tohum ekmeli, eşeyli üremede tek ata canlı yeterlidir"], a:1,
     w:"Daldan yeni gül elde etmek vejetatif üremedir. Eşeysiz üremede yavrular ana bitkiyle aynı kalıtsal yapıda olduğu için çiçek rengi gibi özellikler korunur. Tohumla oluşan yavrular ana bitkiden farklı olabilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki canlı – eşeysiz üreme çeşidi eşleştirmelerinden hangisi YANLIŞTIR?", o:["Amip – bölünme","Maya mantarı – tomurcuklanma","Paramesyum – vejetatif üreme","Denizyıldızı – rejenerasyon"], a:2,
     w:"Paramesyum tek hücreli bir canlıdır ve bölünerek ürer. Vejetatif üreme bitkilerde görülen bir eşeysiz üreme çeşididir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir arı çiçeğe konduğunda tüylerine polenler yapışıyor. Arı başka bir çiçeğe geçince polenler o çiçeğin nemli ve yapışkan kısmına bulaşıyor.\n\nPolenlerin üretildiği kısım ve polenlerin ulaştığı kısım hangisinde doğru verilmiştir?", o:["Dişicik tepesi – başçık","Başçık – dişicik tepesi","Yumurtalık – dişicik borusu","Sapçık – yumurtalık"], a:1,
     w:"Polenler erkek organın başçığında üretilir. Tozlaşmada polen, dişi organın nemli ve yapışkan kısmı olan dişicik tepesine ulaşır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Çiçekli bir bitkinin yaşam döngüsündeki olaylar hangi seçenekte doğru sırayla verilmiştir?", o:["Döllenme → tozlaşma → tohum oluşumu → çimlenme","Tozlaşma → tohum oluşumu → döllenme → çimlenme","Çimlenme → döllenme → tozlaşma → tohum oluşumu","Tozlaşma → döllenme → tohum oluşumu → çimlenme"], a:3,
     w:"Bitkide eşeyli üreme tozlaşmayla başlar, ardından döllenme olur ve tohum oluşur. Tohum uygun koşullarda çimlenerek yeni bitkiyi oluşturur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Can, “Tohumun çimlenmesi için su gereklidir.” hipotezini test edecek. Elinde özdeş fasulye tohumlarıyla kurulmuş dört düzenek var:\n\nK: ıslak pamuk, aydınlık ortam, 22 °C\nL: ıslak pamuk, karanlık ortam, 22 °C\nM: kuru pamuk, aydınlık ortam, 22 °C\nN: ıslak pamuk, aydınlık ortam, 4 °C\n\nCan hangi iki düzeneği karşılaştırmalıdır?", o:["K ve M","K ve L","K ve N","L ve M"], a:0,
     w:"Hipotez suyun etkisini sınadığı için yalnız suyun farklı, ışık ve sıcaklığın aynı olduğu iki düzenek seçilmelidir. K'de pamuk ıslak, M'de kurudur, diğer koşullar aynıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Zeynep, sıcaklığın çimlenmeye etkisini araştırmak için özdeş iki kaba ıslak pamuk ve onar buğday tohumu koyuyor. Kaplardan birini 25 °C'lik odaya, diğerini 5 °C'lik bir ortama bırakıyor ve bir hafta boyunca gözlem yapıyor.\n\nBu deneyde bağımlı değişken hangisidir?", o:["Ortamın sıcaklığı","Pamuktaki su miktarı","Kullanılan tohumun cinsi","Çimlenen tohum sayısı"], a:3,
     w:"Bağımlı değişken, bağımsız değişkene (sıcaklık) bağlı olarak değişen ve gözlenen sonuçtur. Su miktarı ve tohum cinsi iki kapta aynı tutulan kontrol değişkenleridir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Tohumun çimlenmesiyle ilgili deney hazırlayan bir öğrenci defterine aşağıdaki cümleleri yazıyor.\n\nBu cümlelerden hangisi bir hipotezdir?", o:["Fasulye, baklagiller grubunda yer alan bir bitkidir.","Sıcaklık düşerse fasulye tohumu daha geç çimlenir.","Bu deney sınıfta bir hafta boyunca sürecektir.","Tohumlar pamuğun üzerine aralıklı dizilmelidir."], a:1,
     w:"Hipotez, bir faktörün sonuca etkisi hakkında yapılan ve deneyle sınanabilen tahmindir. Sıcaklığın çimlenme süresine etkisi deneyle test edilebilir, diğer cümleler bilgi ya da yönergedir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Leylekler her yıl aynı yuvaya döner. Dişi leylek yuvaya yumurtalarını bırakır, anne ve baba yumurtaları sırayla ısıtır. Yumurtadan çıkan yavruları birlikte besler, yavrular birkaç ay içinde uçmayı öğrenir.\n\nBu bilgilere göre leylek için hangisi SÖYLENEMEZ?", o:["Eşeyli ürer","Yumurtayla çoğalır","Başkalaşım geçirir","Yavru bakımı yapar"], a:2,
     w:"Leylek eşeyli üreyen, yumurtayla çoğalan ve yavrularını besleyen bir kuştur. Metinde yavruların yapısal bir değişim geçirdiğine dair bilgi yoktur, başkalaşım kurbağa ve kelebek gibi hayvanlarda görülür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İnsanda üremeyi sağlayan yapı ve organlarla ilgili aşağıdaki eşleştirmelerden hangisi doğrudur?", o:["Yumurta kanalı – yumurtaların üretildiği yer","Sperm kanalı – spermlerin üretildiği yer","Döl yatağı – bebeğin geliştiği yer","Vajina – döllenmenin gerçekleştiği yer"], a:2,
     w:"Bebek doğuma kadar döl yatağında büyüyüp gelişir. Yumurtalar yumurtalıkta, spermler testiste üretilir, döllenme ise yumurta kanalında gerçekleşir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir öğrenci, insanın anne vücudundaki gelişimiyle ilgili kavramları oluş sırasına göre dizecek.\n\nDoğru dizilim hangisidir?", o:["Döllenme → zigot → embriyo → fetüs","Zigot → döllenme → embriyo → fetüs","Döllenme → embriyo → zigot → fetüs","Döllenme → zigot → fetüs → embriyo"], a:0,
     w:"Sperm ve yumurta çekirdeklerinin birleşmesine döllenme, oluşan hücreye zigot denir. Zigot gelişerek embriyoya, embriyo da gelişerek fetüse dönüşür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Cimnastikçi Elif, denge aletinin üzerinde düşmeden yürüyüp hareketlerini uyum içinde yapabiliyor.\n\nElif'in bu becerisinde en çok görev alan yapı hangisidir?", o:["Beyincik","Omurilik","Omurilik soğanı","Böbrek üstü bezi"], a:0,
     w:"Beyincik vücudun denge ve hareket merkezidir, bilinçli yapılan kas hareketlerinin uyum içinde olmasını sağlar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi sonradan kazanılan bir reflekse örnektir?", o:["Diz kapağına vurulunca bacağın sıçraması","Bebeğin ağzına değen şeyi emmesi","Kütüphanede okumak için bir kitap seçmek","Limon görünce ağzın sulanması"], a:3,
     w:"Limon görünce ağzın sulanması sonradan kazanılan bir reflekstir. Diz kapağı ve emme refleksleri doğuştandır; kitap seçmek ise düşünerek yapılan istemli bir harekettir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sinir sistemiyle ilgili aşağıdaki bilgilerden hangisi YANLIŞTIR?", o:["Beyincik ve omurilik soğanı beynin bölümlerindendir","Omurilik, çevresel sinir sisteminin bir bölümüdür","Çevresel sinir sistemi tüm vücuda dağılan bir sinir ağıdır","Sinir sisteminde görev yapan hücrelere nöron denir"], a:1,
     w:"Omurilik, beyinle birlikte merkezî sinir sistemini oluşturur. Çevresel sinir sistemi ise merkezî sinir sistemiyle organlar arasındaki iletişimi sağlayan sinir ağıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Gece karanlık bir sokakta yürürken birden havlayan bir köpek gören Ali korkuyor. Kalbi hızla atmaya, nefesi sıklaşmaya başlıyor.\n\nAli'de bu değişimlere yol açan hormon ve iç salgı bezi hangisidir?", o:["Adrenalin – böbrek üstü bezi","Tiroksin – tiroit bezi","İnsülin – pankreas","Büyüme hormonu – hipofiz bezi"], a:0,
     w:"Korku, öfke, coşku ve stres anlarında böbrek üstü bezi adrenalin salgılar. Adrenalin kalp atışını, solunumu ve kan dolaşımını hızlandırır, kan basıncını artırır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir hastanın kan şekeri sürekli yüksek çıkıyor. Doktor, hastanın bir iç salgı bezinin yeterince hormon üretmediğini düşünüyor.\n\nBu durumda yeterince üretilmeyen hormon ve onu salgılayan bez hangisidir?", o:["Glukagon – pankreas","Tiroksin – tiroit bezi","İnsülin – pankreas","Adrenalin – böbrek üstü bezi"], a:2,
     w:"İnsülin kandaki şeker oranını azaltır. Pankreas yeterince insülin üretmezse kan şekeri yükselir. Glukagon ise kan şekerini artıran hormondur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aynı sınıfta okuyan 11 yaşındaki Zeynep'in boyu son bir yılda hızla uzarken aynı yaştaki Can'da henüz belirgin bir değişim görülmüyor.\n\nBu durumun en uygun açıklaması hangisidir?", o:["Can'ın vücudu hiç büyüme hormonu üretmemektedir","Ergenlik yalnızca kızlarda görülen bir dönemdir","Kızlar genellikle erkeklerden önce ergenliğe girer","Boy uzaması yalnızca kızlarda görülen bir değişimdir"], a:2,
     w:"Ergenliğe geçiş yaşı kişiden kişiye değişir. Belirtiler genellikle kızlarda 10–12, erkeklerde 12–14 yaşında başlar, bu yüzden kızlar bir süre daha gelişmiş görünebilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ayşe, durgun bir gölün yüzeyinde karşı kıyıdaki ağaçların net görüntüsünü görüyor. Rüzgâr çıkıp su dalgalanınca görüntü bulanıklaşıyor.\n\nBu gözlemle ilgili hangisi doğrudur?", o:["Durgun suda dağınık, dalgalı suda düzgün yansıma olur","Dalgalı suda ışık yansımaz, tamamen soğurulur","Durgun suda düzgün, dalgalı suda dağınık yansıma olur","İki durumda da düzgün yansıma olur, yalnız ışık azalır"], a:2,
     w:"Durgun suyun yüzeyi düzgündür, düzgün yansımayla net görüntü verir. Dalgalanan su pürüzlü bir yüzey gibi davranır, ışınlar farklı doğrultularda yansır ve görüntü bulanıklaşır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Dağınık yansımayla ilgili aşağıdakilerden hangisi doğrudur?", o:["Yansıyan ışınlar birbirine paralel ilerler","Her ışında gelme açısı yansıma açısına eşittir","Yansıma kanunları bu yansımada geçerli değildir","Bu yansımada net bir görüntü oluşur"], a:1,
     w:"Yansıma kanunları hem düzgün hem dağınık yansımada geçerlidir. Dağınık yansımada yüzey pürüzlü olduğu için ışınlar farklı doğrultularda gider ve net görüntü oluşmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir ışın, düz aynanın yüzeyiyle 30° açı yapacak şekilde gönderiliyor.\n\nGelen ışın ile yansıyan ışın arasındaki açı kaç derecedir?", o:["60°","30°","150°","120°"], a:3,
     w:"Açılar normalden ölçülür. Gelme açısı 90° − 30° = 60° olur, yansıma açısı da 60° olur. İki ışın arasındaki açı 60° + 60° = 120° olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir lazer ışığı düz aynaya dik olarak gönderiliyor.\n\nBu ışının gelme açısı ve yansıdıktan sonraki yolu için hangisi doğrudur?", o:["Gelme açısı 90°, aynaya paralel ilerler","Gelme açısı 0°, kendi üzerinden geri döner","Gelme açısı 90°, kendi üzerinden geri döner","Gelme açısı 0°, aynaya paralel ilerler"], a:1,
     w:"Aynaya dik gelen ışın yüzey normali üzerinden gelir, bu yüzden gelme açısı 0° olur. Yansıma kanununa göre ışın kendi üzerinden geri yansır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir öğrenci üç aynaya yaklaşıp uzaklaşarak görüntüsünü inceliyor:\n\nK aynası: Görüntü her zaman düz ve küçük\nL aynası: Uzaklığa göre bazen düz ve büyük, bazen ters görüntü\nM aynası: Görüntü düz ve öğrenciyle aynı boyda\n\nK, L ve M aynalarının çeşitleri hangisinde doğru verilmiştir?", o:["K çukur, L tümsek, M düz","K tümsek, L düz, M çukur","K düz, L çukur, M tümsek","K tümsek, L çukur, M düz"], a:3,
     w:"Görüntüsü her zaman düz ve küçük olan ayna tümsek, uzaklığa göre düz ya da ters, büyük ya da küçük görüntü veren ayna çukur, cisimle aynı boyda ve düz görüntü veren ayna düz aynadır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki araç – ayna çeşidi eşleştirmelerinden hangisi YANLIŞTIR?", o:["Makyaj aynası – çukur ayna","Viraj aynası – çukur ayna","Araba yan aynası – tümsek ayna","Teleskop – çukur ayna"], a:1,
     w:"Viraj aynası geniş bir alanı göstermesi için tümsek aynadır. Makyaj aynası ve teleskopta çukur, araba yan aynasında tümsek ayna kullanılır."}
  ]);

  /* ---------- 6. sınıf · İngilizce ---------- */
  Q6.ing = (Q6.ing || []).concat([
    {u:"TEMA 3 · Personal Life & Well-Being", q:"When you eat too much, your ____ hurts.", o:["stomach","ankle","neck","knee"], a:0,
     w:"stomach = mide, karın. Çok yemek yiyince mide ağrır."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"Footballers wear the same ____: a shirt, shorts and socks in their team colours.", o:["purse","chain","kit","pocket"], a:2,
     w:"kit = (spor) takım. Aynı renkteki forma, şort ve çoraptan oluşan settir."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"Which one is a piece of jewellery?", o:["a wallet","a swimsuit","a pocket","a necklace"], a:3,
     w:"necklace (kolye) bir takıdır (jewellery). wallet cüzdan, swimsuit mayo, pocket cep demektir."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"Deniz never says “please” or “thank you”, and he shouts at people. He is ____.", o:["rude","patient","caring","polite"], a:0,
     w:"Teşekkür etmeyen ve insanlara bağıran biri rude (kaba) diye anlatılır."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"“Odaklanmış” sözcüğünün İngilizcesi hangisidir?", o:["serious","focused","independent","organised"], a:1,
     w:"focused = odaklanmış, yani dikkatini işine vermiş."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"My cousin Ece is ten. She has got short straight hair and green eyes. She is very polite, and she always helps her friends.\n\nWhat does Ece look like?", o:["She is ten, and she is very polite.","She has got long straight hair and blue eyes.","She is very polite, and she helps her friends.","She has got short straight hair and green eyes."], a:3,
     w:"What does she look like? dış görünüşü sorar. Metne göre Ece'nin saçı kısa ve düz, gözleri yeşil. Kibar olması ise kişiliğiyle ilgilidir."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"A: ____ the boy with the blue school bag?\nB: He's my brother, Can.", o:["Whose","Who's","Who","Where's"], a:1,
     w:"Kişinin kim olduğunu sormak için Who's (Who is) kullanılır. Whose ise bir şeyin kime ait olduğunu sorar."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"My brother is 1.70 m. I am 1.55 m. My brother is ____ than me.", o:["the tallest","more tall","taller","tall"], a:2,
     w:"İki kişi karşılaştırılıyor ve ardından than geliyor. Kısa sıfat -er alır: taller than."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"Elif plans her week and keeps her desk in order. She is ____ than her brother.", o:["more organised","organiseder","the most organised","most organised"], a:0,
     w:"organised uzun bir sıfattır, -er almaz. İki kişi karşılaştırılırken more organised than kullanılır."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"Ali: 1.60 m · Can: 1.52 m · Mert: 1.45 m\n\nMert is ____ boy of the three.", o:["shorter","the shortest","the most short","shortest"], a:1,
     w:"Üç çocuk içinde boyu en kısa olan Mert. Üç ya da daha çok kişi karşılaştırılınca the + -est kullanılır: the shortest."}
  ]);
  H6.ing = (H6.ing || []).concat([
    {u:"TEMA 3 · Personal Life & Well-Being", q:"A: Have you got a wallet?\nB: No, I ____. I use my mum's old purse.", o:["hasn't","don't","haven't","aren't"], a:2,
     w:"Have you got …? sorusunun kısa olumsuz cevabı No, I haven't olur. Kısa cevapta got tekrarlanmaz."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"“Ayak bileği” sözcüğünün İngilizcesi hangisidir?", o:["knee","wrist","back","ankle"], a:3,
     w:"Ayak bileği = ankle. wrist el bileği, knee diz, back sırt demektir."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"Can's room is always in order. He puts everything in the right place. He is very ____.", o:["tidy","rude","lazy","weak"], a:0,
     w:"Odasını hep düzenli tutan, her şeyi yerine koyan biri tidy (derli toplu) diye anlatılır."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"This year my English marks are ____ than last year. I am very happy!", o:["worse","better","the best","gooder"], a:1,
     w:"good düzensiz bir sıfattır: good → better → the best. Mutlu olduğuna göre notlar geçen yıldan daha iyi."},
    {u:"TEMA 3 · Personal Life & Well-Being", q:"LOST AND FOUND · OWNERS\nred purse – Ece\nblack trainers – Burak\nsilver necklace – Selin\nbrown wallet – Kerem\n\nWhose is the silver necklace?", o:["It's Ece's.","It's Burak's.","It's Selin's.","It's Kerem's."], a:2,
     w:"Listede silver necklace satırının karşısında Selin yazıyor. Whose sorusuna It's Selin's diye cevap verilir."}
  ]);
  EKC6.ing = (EKC6.ing || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"CLASS 6-A · WEEKLY DUTIES\nMonday – Elif: cleans the board\nTuesday – Can and Ali: water the plants\nWednesday – Zeynep: helps in the library\nThursday – Deniz: greets the visitors at the door\nFriday – Mert: collects the homework\n\nWho greets the visitors?", o:["Zeynep","Mert","Elif","Deniz"], a:3,
     w:"Çizelgede “greets the visitors at the door” görevi Thursday satırında, Deniz'in adının yanında yazıyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Every year on 29th October, our school has a big celebration. In the morning, all the students stand in the school garden. We sing the national anthem, and the head teacher gives a speech. My friend Defne reads a poem because she is the best reader in our class. After the ceremony, we watch a show in the assembly hall. I always feel proud on this day.\n\nWhy does Defne read a poem at the ceremony?", o:["Because she is the class leader.","Because she reads very well.","Because she sings in the school choir.","Because she gives a speech every year."], a:1,
     w:"Metinde nedeni “because she is the best reader in our class” diye veriliyor, yani Defne çok iyi okuyor. Konuşmayı yapan kişi okul müdürüdür (head teacher)."},
    {u:"EK · 2. Yazılı Hazırlık", q:"In the science lab, students always __________ the teacher's instructions carefully, so they work safely.", o:["follow","pack","enter","fail"], a:0,
     w:"follow the instructions = talimatlara uymak. Laboratuvarda güvenli çalışmak için öğretmenin talimatlarına uyulur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Our music teacher always supports __________ before the ceremony, so we feel ready.", o:["we","our","ours","us"], a:3,
     w:"support fiilinden sonra nesne zamiri gelir: we → us (bizi). our ise iyelik sıfatıdır, ardından isim ister."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read Can's paragraph.\n“Hi, I'm Can. My favourite school routine is the morning ceremony. __________ I always sing the national anthem with my friends. It makes me feel proud.”\n\nWhich sentence completes the paragraph?", o:["We has it every Monday morning.","We have it every Friday evening.","We have it every Monday morning.","We having it every Monday morning."], a:2,
     w:"Rutin Present Simple ile anlatılır (we + have). Tören sabah yapıldığı için “every Monday morning” uyar, akşam saati sabah töreniyle çelişir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"SCIENCE CENTRE TRIP\nDate: 4th December\nStudents: 135\nBuses: 3\nMeeting place: the school garden, 8:15\nLunch: in the café on the 2nd floor\n\nHow many students are joining the trip?", o:["one hundred and fifty-three","three hundred and fifteen","one hundred and thirty-five","one hundred and twenty-five"], a:2,
     w:"İlanda “Students: 135” yazıyor. 135 yazıyla one hundred and thirty-five olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"SCIENCE CENTRE TRIP\nDate: 4th December\nStudents: 135\nBuses: 3\nMeeting place: the school garden, 8:15\nLunch: in the café on the 2nd floor\n\nWhich floor is the café on?", o:["The second floor","The first floor","The fourth floor","The third floor"], a:0,
     w:"İlanda kafe için “on the 2nd floor” yazıyor. 2nd yazıyla second (ikinci) olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Dear diary,\nToday is a different day. I normally study alone at home, but today I am studying in the library with my friends. Elif usually marks the important points, but now she is reading the text aloud. Ali often searches for pictures, but today he is counting the books on the shelves. I am writing the answers on our worksheet. We are a good team!\nDeniz\n\nWhat is Ali doing today?", o:["He is counting the pictures.","He is searching for books.","He is counting the books.","He is reading the text aloud."], a:2,
     w:"Günlükte Ali için “today he is counting the books on the shelves” deniyor. Resim aramak onun her zamanki işi, bugünkü işi değil."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Dear diary,\nToday is a different day. I normally study alone at home, but today I am studying in the library with my friends. Elif usually marks the important points, but now she is reading the text aloud. Ali often searches for pictures, but today he is counting the books on the shelves. I am writing the answers on our worksheet. We are a good team!\nDeniz\n\nWhich sentence is TRUE according to the diary?", o:["Deniz normally studies in the library.","Elif usually reads the text aloud.","Ali is writing the answers on the worksheet.","Deniz normally studies alone at home."], a:3,
     w:"Deniz “I normally study alone at home” diyor. Kütüphanede çalışması yalnız bugüne özgü bir durum."},
    {u:"EK · 2. Yazılı Hazırlık", q:"In the library, students read their books __________ because they don't want to make any noise.", o:["aloud","in turns","together","silently"], a:3,
     w:"silently = sessizce, ses çıkarmadan. Gürültü yapmamak için kitap sessiz okunur, aloud ise sesli okumak demektir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Zeynep is the same age as me, and we are in the same class. She is my __________. We often study together.", o:["level","peer","method","diary"], a:1,
     w:"peer = akran, yaşıt (aynı yaştaki kişi). level seviye, method yöntem, diary günlük demektir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Can usually __________ his notes at home, but today he __________ them in the canteen.", o:["is reviewing / reviews","reviews / is reviewing","review / reviewing","reviews / reviews"], a:1,
     w:"usually rutini gösterir, Present Simple kullanılır (he reviews). today ise bugüne özgü olanı gösterir, Present Continuous kullanılır (he is reviewing)."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif is revising her lessons in the library now, __________?", o:["doesn't she","is she","isn't she","isn't it"], a:2,
     w:"Cümlede olumlu “is” var, bu yüzden tag olumsuz olur. Elif yerine she gelir: isn't she? (değil mi?)"},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ali and Mert are working on a project for the Science lesson. __________ project is about recycling.", o:["Their","They","His","Them"], a:0,
     w:"Ali and Mert = they. Sahiplik bildiren iyelik sıfatı their (onların) ismin önüne gelir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read the model sentence and Ece's notes.\nModel: “I normally read in my room, but today I am reading in the garden.”\nEce: normally – study alone · today – study with my brother\n\nWhich sentence is correct for Ece's diary?", o:["I normally study with my brother, but today I am studying alone.","I am normally studying alone, but today I study with my brother.","I normally study alone, but today I am studying with my brother.","I normally studies alone, but today I studying with my brother."], a:2,
     w:"Ece'nin notlarına göre rutini “study alone”, bugünkü durumu “study with my brother”. Bu bilgiler modeldeki kalıba aynı sırayla yerleşince doğru cümle çıkar. Öteki cümlelerde ya bilgiler yer değiştirmiş ya da fiil biçimi bozulmuş."},
    {u:"EK · 2. Yazılı Hazırlık", q:"CLASS 6-C · PROFILE CARDS\nEla: tall · curly brown hair · social, caring\nBurak: short · straight black hair · clever, a bit lazy\nSelin: slim · wavy red hair · patient, organised\nKerem: tall · short blond hair · polite, serious\n\nWho has got wavy hair?", o:["Ela","Burak","Kerem","Selin"], a:3,
     w:"“wavy red hair” Selin'in kartında yazıyor. wavy = dalgalı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"CLASS 6-C · PROFILE CARDS\nEla: tall · curly brown hair · social, caring\nBurak: short · straight black hair · clever, a bit lazy\nSelin: slim · wavy red hair · patient, organised\nKerem: tall · short blond hair · polite, serious\n\nWhat does Ela look like?", o:["She is slim and she has got wavy red hair.","She is tall and she has got curly brown hair.","She is short and she has got straight black hair.","She is tall and she has got short blond hair."], a:1,
     w:"What does she look like? dış görünüşü sorar. Ela'nın kartında “tall · curly brown hair” yazıyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hi Ece,\nI want to tell you about my cousins, Defne and Mert. Defne is fourteen and Mert is ten. Defne is taller than Mert, but Mert is more social than her. Defne has got long straight hair and she always wears a bracelet. She is very organised. Mert is the funniest person in our family. He is a bit lazy, but he is very caring. He always helps our grandmother in the garden.\nLove,\nZeynep\n\nWhich sentence is TRUE according to the e-mail?", o:["Defne is older than Mert.","Mert is older than Defne.","Mert is taller than Defne.","Defne is more social than Mert."], a:0,
     w:"Defne on dört, Mert on yaşında, bu yüzden Defne daha büyüktür (older). E-postaya göre boyu uzun olan Defne, daha sosyal olan Mert'tir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hi Ece,\nI want to tell you about my cousins, Defne and Mert. Defne is fourteen and Mert is ten. Defne is taller than Mert, but Mert is more social than her. Defne has got long straight hair and she always wears a bracelet. She is very organised. Mert is the funniest person in our family. He is a bit lazy, but he is very caring. He always helps our grandmother in the garden.\nLove,\nZeynep\n\nWhy does Zeynep think Mert is caring?", o:["Because he is the funniest person in the family.","Because he always helps his grandma.","Because he is more social than Defne.","Because he always wears a bracelet."], a:1,
     w:"“He is very caring” cümlesinin hemen ardından büyükannesine her zaman yardım ettiği söyleniyor. Başkasına yardım etmek ilgili, şefkatli (caring) olmayı gösterir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Emre is playing football, but now he can't run because his __________ hurts. It is a part of his leg.", o:["neck","stomach","knee","back"], a:2,
     w:"knee = diz, bacağın bir parçasıdır. neck boyun, stomach mide, back sırt demektir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"It's a hot summer day at the beach. Selin is in the sea, and she is wearing her new __________.", o:["swimsuit","tights","jacket","trainers"], a:0,
     w:"Denize mayoyla girilir: swimsuit = mayo. tights tayt, jacket ceket, trainers spor ayakkabısı demektir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"A: __________ your sister got a necklace?\nB: Yes, she has. She wears it every day.", o:["Does","Is","Have","Has"], a:3,
     w:"Cevap “Yes, she has.” olduğu için soru “Has … got …?” ile kurulur. your sister = she olduğundan have değil has gelir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"A: __________ trainers are these?\nB: They're Burak's. He wears them in PE lessons.", o:["Who's","Where","Who","Whose"], a:3,
     w:"Eşyanın sahibini sormak için Whose (kimin) kullanılır. Who's ise Who is (kim) demektir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif: 1.52 m · Ece: 1.48 m · Selin: 1.60 m\n\nWhich sentence is correct?", o:["Ece is taller than Elif and Selin.","Selin is the tallest of the three.","Elif is the tallest of the three.","Selin is shorter than Elif and Ece."], a:1,
     w:"En uzun boy 1.60 m ile Selin'in. Üç kişi karşılaştırılınca en üstünlük kullanılır: the tallest."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read Elif's e-mail.\n“Hi Ece,\nMy new neighbour is Arda. He is short and he has got straight black hair. __________ He always helps his little brother with his homework, and he never gets angry. I like him a lot!\nLove,\nElif”\n\nWhich sentence completes the e-mail?", o:["He is caring and very patient.","He is rude and he is very lazy.","He have got big green eyes.","He is more taller than his brother."], a:0,
     w:"Kardeşine yardım eden ve hiç kızmayan biri caring (ilgili) ve patient (sabırlı) diye anlatılır. rude ve lazy metinle çelişir, öteki iki cümlede de dil bilgisi hatası var."}
  ]);

  /* ---------- 6. sınıf · Matematik ---------- */
  Q6.mat = (Q6.mat || []).concat([
    {u:"TEMA 4 · Veriden Olasılığa", q:"Madenî para atma deneyinde “yazı” ve “tura” olası sonuçlarından her birine ne ad verilir?", o:["Çıktı","Olay","Deney","Sıklık"], a:0,
     w:"Bir deneyin olası sonuçlarının her biri çıktıdır. Parayı atma işlemi deneyin kendisi, “tura gelmesi” gibi bir durum ise olaydır."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir madenî para 25 kez atılıyor ve 11 kez tura geliyor. Tura gelme olayının göreli sıklığı kaçtır?", o:["11/14","14/25","11/25","25/11"], a:2,
     w:"Göreli sıklık, olayın sıklığının toplam deney sayısına bölümüdür: 11/25. Tura sayısını yazı sayısına bölmek (11/14) yanlıştır."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir okçu 40 atışın 34'ünde hedefi vuruyor. Bu okçunun hedefi vurma olayının deneysel olasılığı yüzde kaçtır?", o:["%34","%75","%90","%85"], a:3,
     w:"Deneysel olasılık göreli sıklığa eşittir: 34/40 = 17/20 = 85/100, yani %85."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Aşağıdakilerden hangisi bir olayın deneysel olasılığı OLAMAZ?", o:["0,8","7/6","%45","3/10"], a:1,
     w:"Bir olay deney sayısından fazla gerçekleşemez, bu yüzden deneysel olasılık 0 ile 1 arasında bir sayıdır. 7/6 ise 1'den büyüktür."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir torbada 4 kırmızı ve 6 mavi top var. Çekilen top geri konarak 20 çekiliş yapılıyor ve 9 kez kırmızı top geliyor. Kırmızı top çekme olayının deneysel olasılığı kaçtır?", o:["9/20","4/10","9/11","11/20"], a:0,
     w:"Deneysel olasılık deneyin sonucuna göre bulunur: 20 çekilişin 9'u kırmızıdır, 9/20. Torbadaki oran (4/10) yalnız tahmin içindir."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir çark 50 kez çevriliyor. Okun sarıyı gösterme olayının göreli sıklığı 3/10 olduğuna göre ok kaç kez sarıyı göstermiştir?", o:["10","20","35","15"], a:3,
     w:"Sıklık = göreli sıklık × deney sayısı = 3/10 · 50 = 15."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Penaltı çalışmasında Ali 20 atışın 14'ünü, Can 25 atışın 19'unu gole çeviriyor. Bu verilere göre hangisi doğrudur?", o:["Ali'nin deneysel olasılığı daha yüksektir","İkisinin deneysel olasılığı eşittir","Can'ın deneysel olasılığı daha yüksektir","Atış sayıları farklı, karşılaştırma yapılamaz"], a:2,
     w:"Ali: 14/20 = 70/100 = %70. Can: 19/25 = 76/100 = %76. Deney sayıları farklı olduğunda oranlar karşılaştırılır."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Üzerinde 0'dan 9'a kadar rakamlar yazılı 10 eş kart bir torbadadır. Çekilen kart geri konarak 50 çekiliş yapılacaktır. Her rakam için beklenen sıklık kaçtır?", o:["1","5","10","50"], a:1,
     w:"Kartların çekilme şansı eşit olduğundan her rakam için tahminî olasılık 1/10 olur. Beklenen sıklık 50 · 1/10 = 5. Gözlenen sıklık bundan farklı çıkabilir."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir sayı küpü 40 kez atılıyor. Üst yüze gelen sayıların sıklıkları: 1 → 6, 2 → 8, 3 → 5, 4 → 7, 5 → 9, 6 → 5.\n\nÜst yüze 4'ten büyük bir sayı gelme olayının deneysel olasılığı kaçtır?", o:["9/40","3/10","7/20","1/3"], a:2,
     w:"4'ten büyük sayılar 5 ve 6'dır: 9 + 5 = 14 atış. 14/40 = 7/20."}
  ]);
  H6.mat = (H6.mat || []).concat([
    {u:"TEMA 4 · Veriden Olasılığa", q:"Olasılık spektrumunda 0 noktasına yerleştirilen bir olay için hangisi söylenir?", o:["Kesin olaydır","İmkânsız olaydır","Eşit şanslı bir olaydır","Olma olasılığı çok yüksektir"], a:1,
     w:"Spektrumun 0 ucu hiç gerçekleşemeyen olayları, 1 ucu her denemede gerçekleşen olayları, 1/2 noktası ise eşit şansı gösterir."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir çark çevirme deneyinde dört rengin göreli sıklıkları 1/5, 3/10, 2/5 ve x'tir. Buna göre x kaçtır?", o:["1/10","1/5","3/10","9/10"], a:0,
     w:"Bütün çıktıların göreli sıklıkları toplamı 1'dir: 1/5 + 3/10 + 2/5 = 2/10 + 3/10 + 4/10 = 9/10. x = 1 − 9/10 = 1/10."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir deneyde bir olayın göreli sıklığı 3/8, gerçekleşme sayısı 12'dir. Deney kaç kez yapılmıştır?", o:["24","36","32","40"], a:2,
     w:"Deney sayısının sekizde üçü 12 ise sekizde biri 4, tamamı 4 · 8 = 32'dir."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Bir fabrikada test edilen 250 ampulün 20'si arızalı çıkıyor. Rastgele seçilen bir ampulün sağlam olma olayının deneysel olasılığı yüzde kaçtır?", o:["%8","%20","%80","%92"], a:3,
     w:"Sağlam ampul sayısı 250 − 20 = 230'dur. 230/250 = 92/100 = %92."},
    {u:"TEMA 4 · Veriden Olasılığa", q:"Elif ve Zeynep aynı sayı küpünü 30'ar kez atıyor. Üst yüze 6 gelme sayısı Elif'te 4, Zeynep'te 7 oluyor. Bu durumla ilgili hangisi doğrudur?", o:["Deney sonuçları tekrarlarda değişebilir","Zeynep'in sayı küpü kesinlikle hilelidir","Elif deneyi yanlış yapmıştır","Deney 30 kez daha yapılsa aynı sonuç çıkar"], a:0,
     w:"Rastgele deneylerde aynı deneyi yapan kişilerin sonuçları farklı çıkabilir. Az denemeyle hile ya da hata olduğu söylenemez, daha güvenilir tahmin için deney sayısı artırılır."}
  ]);
  EKC6.mat = (EKC6.mat || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir bahçenin 2/5'sine domates, 1/3'ine biber ekilmiş, kalan kısma çiçek dikilmiştir. Çiçek dikilen kısım bahçenin kaçta kaçıdır?", o:["4/15","5/8","11/15","1/15"], a:0,
     w:"Paydalar 15'te eşitlenir: 2/5 = 6/15, 1/3 = 5/15. Ekili kısım 11/15, çiçek için kalan 15/15 − 11/15 = 4/15. Payları ve paydaları ayrı ayrı toplamak yanlıştır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir depodaki suyun 3/4'ü kullanılıyor, kalan suyun 2/5'si ile bahçe sulanıyor. Bahçeyi sulamak için kullanılan su, deponun tamamının kaçta kaçıdır?", o:["3/10","13/20","2/5","1/10"], a:3,
     w:"Kalan su 1 − 3/4 = 1/4. Bunun beşte ikisi alınır: 1/4 · 2/5 = 2/20 = 1/10. “Kalanın kesri kadarı” çarpmayla bulunur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"3 tam 3/4 kg pirinç, her biri 3/8 kg olan paketlere hiç artmadan dolduruluyor. Kaç paket gerekir?", o:["8","12","15","10"], a:3,
     w:"3 tam 3/4 = 15/4 = 30/8. Paydalar eşit olunca paylar bölünür: 30/8 ÷ 3/8 = 30 ÷ 3 = 10 paket."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir terzi 12,5 m kumaşın 4,75 m'sini pantolon, 3,8 m'sini ceket dikmek için kullanıyor. Geriye kaç metre kumaş kalır?", o:["3,95 m","4,05 m","3,85 m","8,55 m"], a:0,
     w:"Kullanılan kumaş 4,75 + 3,80 = 8,55 m. Kalan 12,50 − 8,55 = 3,95 m. Virgüller alt alta yazılır, eksik basamağa 0 eklenir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kilogramı 42,5 TL olan elmadan 2,4 kg alan bir kişi kaç TL öder?", o:["85 TL","102 TL","1020 TL","10,2 TL"], a:1,
     w:"Virgüller yokmuş gibi çarpılır: 425 · 24 = 10 200. Çarpanlarda toplam 2 ondalık basamak olduğu için sonuç 102,00 = 102 TL."},
    {u:"EK · 2. Yazılı Hazırlık", q:"4,5 litre portakal suyu, 0,25 litrelik bardaklara tamamen dolduruluyor. Kaç bardak dolar?", o:["1,8","180","1,125","18"], a:3,
     w:"Bölen ve bölünen 100 ile çarpılarak doğal sayıya çevrilir: 450 ÷ 25 = 18 bardak. 1'den küçük bir sayıya bölünce sonuç büyür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Maliyeti 350 TL olan bir ürüne %20 KDV ekleniyor. Mağaza, KDV'li fiyat üzerinden %10 indirim yapıyor. Ürün kaç TL'ye satılır?", o:["315 TL","385 TL","378 TL","420 TL"], a:2,
     w:"KDV'li fiyat 350 + 350 · 20/100 = 420 TL. İndirim 420 · 10/100 = 42 TL, satış fiyatı 420 − 42 = 378 TL. Yüzdeleri birleştirip %10 zam gibi hesaplamak (385 TL) yanlıştır, çünkü indirim daha büyük bir fiyat üzerinden yapılır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Can, 1200 TL'nin %35'iyle kitap, kalan paranın 1/4'iyle defter alıyor. Can'ın kaç TL'si kalır?", o:["480 TL","585 TL","195 TL","780 TL"], a:1,
     w:"Kitap 1200 · 35/100 = 420 TL, kalan 780 TL. Defter kalanın dörtte biri kadardır: 780 ÷ 4 = 195 TL. Son durumda 780 − 195 = 585 TL kalır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"7 kg ceviz 4 arkadaş arasında eşit olarak paylaştırılıyor. Her birine kaç kg ceviz düşer?", o:["1,3 kg","0,57 kg","1,4 kg","1,75 kg"], a:3,
     w:"Eşit paylaşma bölmedir: 7 ÷ 4 = 7/4 = 175/100 = 1,75 kg. “1 kalan 3” sonucunu 1,3 diye yazmak ya da bölüneni ve böleni yer değiştirmek yanlıştır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki kesirlerden hangisi payı paydaya bölündüğünde devirli bir ondalık gösterim verir?", o:["7/20","9/25","5/12","13/50"], a:2,
     w:"Paydası 10, 100, 1000 yapılabilen kesirlerin ondalık gösterimi sonludur: 7/20 = 0,35, 9/25 = 0,36, 13/50 = 0,26. 12 ise böyle genişletilemez, 5 ÷ 12 = 0,41666… devirlidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"4/9 kesrinin ondalık gösterimi devir çizgisiyle nasıl yazılır?", o:["0,4̄","0,04̄","0,44","2,25"], a:0,
     w:"4 ÷ 9 = 0,444… Kalan hep 4 olduğu için 4 rakamı sürekli tekrar eder ve üstüne devir çizgisi çekilir. 0,44 ise sonlu bir sayıdır, 4/9 kesrine eşit değildir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Çevresi 25 m olan kare biçimindeki bir bahçenin bir kenarı kaç metredir?", o:["6,2 m","6,5 m","6,25 m","100 m"], a:2,
     w:"Karenin dört kenarı eşittir: 25 ÷ 4 = 25/4 = 625/100 = 6,25 m. Çevreyi 4 ile çarpmak (100 m) yanlıştır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"8 m uzunluğundaki bir ip 3 eş parçaya bölünüyor. Bir parçanın uzunluğunun tam değeri hangisidir?", o:["2,6 m","2,7 m","0,375 m","2,6̄ m"], a:3,
     w:"8 ÷ 3 = 2,666… Kalan hep 2 olduğu için 6 sürekli tekrar eder, bölme bitmez. Tam değer 8/3 = 2,6̄ m. 2,7 yuvarlanmış, 2,6 ise kesilmiş değerdir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"0,6 km + 3 hm + 45 dam toplamı kaç metredir?", o:["48,6 m","135 m","1350 m","13 500 m"], a:2,
     w:"Hepsi metreye çevrilir: 0,6 km = 600 m, 3 hm = 300 m, 45 dam = 450 m. Toplam 600 + 300 + 450 = 1350 m."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir bisiklet yolu 3250 m uzunluğundadır. Bu uzunluk kaç kilometredir?", o:["0,325","3,25","32,5","325"], a:1,
     w:"Metreden kilometreye geçerken büyük birime gidilir ve 1000'e bölünür: 3250 ÷ 1000 = 3,25 km."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisinin uzunluğunu ifade etmek için en uygun birim milimetredir?", o:["Bir pencere camının kalınlığı","Bir okul bahçesinin uzunluğu","İki komşu ilçe arasındaki uzaklık","Bir otomobilin uzunluğu"], a:0,
     w:"Çok küçük uzunluklar milimetreyle ifade edilir. Bahçe ve otomobil uzunluğu için metre, ilçeler arası uzaklık için kilometre uygundur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Uzunlukları 1,2 m, 35 cm ve 8 dm olan üç çubuk uç uca ekleniyor. Toplam uzunluk kaç santimetredir?", o:["44,2","163","2350","235"], a:3,
     w:"Önce hepsi santimetreye çevrilir: 1,2 m = 120 cm, 8 dm = 80 cm. Toplam 120 + 35 + 80 = 235 cm."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kenar uzunluğu 45 cm olan kare biçimli 32 fayans, bir koridor boyunca tek sıra hâlinde aralıksız döşeniyor. Bu sıranın uzunluğu kaç metredir?", o:["1,44","14,4","144","1440"], a:1,
     w:"Toplam uzunluk 45 · 32 = 1440 cm. Santimetreden metreye geçerken 100'e bölünür: 1440 ÷ 100 = 14,4 m."},
    {u:"EK · 2. Yazılı Hazırlık", q:"5 + 2/10 + 7/1000 toplamının ondalık gösterimi hangisidir?", o:["5,207","5,27","5,027","5,2007"], a:0,
     w:"Paydası 10 olan kesir onda birler, paydası 1000 olan kesir binde birler basamağını gösterir. Yüzde birler basamağı boş kaldığı için oraya 0 yazılır: 5 + 0,2 + 0,007 = 5,207."},
    {u:"EK · 2. Yazılı Hazırlık", q:"6,384 sayısındaki 8 rakamının basamak değeri kaçtır?", o:["8","0,8","0,08","0,008"], a:2,
     w:"8, virgülden sonraki ikinci basamakta, yani yüzde birler basamağındadır. Basamak değeri 8/100 = 0,08."},
    {u:"EK · 2. Yazılı Hazırlık", q:"9,964 sayısı onda birler basamağına yuvarlanırsa kaç olur?", o:["9,9","10,0","9,96","10,1"], a:1,
     w:"Onda birler basamağındaki 9'un sağında 6 var ve 6 ≥ 5 olduğu için 9'a 1 eklenir. 9,9 + 0,1 = 10,0 olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki araştırma sorularından hangisiyle nicel (kesikli) veri toplanır?", o:["Sınıftaki öğrencilerin en sevdiği renk nedir?","Ailelerin evlerindeki kitap sayıları kaçtır?","Öğrencilerin okula geliş biçimi nedir?","Kütüphanede en çok okunan kitap türü nedir?"], a:1,
     w:"Kitap sayısı sayılarak bulunan bir sayıdır, bu yüzden nicel (kesikli) veridir. Renk, okula geliş biçimi ve kitap türü sözcükle ifade edilir, bunlar kategorik veridir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Sınıfımızda kaç öğrencinin el yazısı güzeldir?” sorusu iyi bir araştırma sorusu sayılmaz. Bunun temel nedeni hangisidir?", o:["Değişken açıkça belirlenemez","Veriler sayıyla ifade edilir","Yalnız bir sınıfta sorulur","Cevaplar kişiden kişiye değişir"], a:0,
     w:"“Güzel el yazısı” kişiye göre değişen bir yargıdır ve ölçülemez, bu yüzden değişken belirlenemez. Cevapların kişiden kişiye değişmesi ise iyi bir araştırma sorusunda aranan bir özelliktir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir dükkânda 7 gün boyunca satılan şemsiye sayıları 4, 5, 3, 6, 5, 5, 42'dir (bir gün sağanak yağış vardı).\n\nDükkân sahibi sıradan bir gün için satış tahmini yapmak istiyor. Hangi ölçüyü kullanması ve kaç şemsiye beklemesi daha uygundur?", o:["Aritmetik ortalama, 10 şemsiye","Ortanca, 5 şemsiye","Açıklık, 39 şemsiye","En büyük değer, 42 şemsiye"], a:1,
     w:"42 uç değerdir ve ortalamayı 10'a çıkarır, oysa günlerin çoğunda 3–6 şemsiye satılmıştır. Uç değerden etkilenmeyen ortanca (sıralı veri 3, 4, 5, 5, 5, 6, 42 içinde ortadaki 5) sıradan bir günü daha iyi temsil eder."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir veri setinin kök-yaprak gösterimi:\n1 | 2 5 5 9\n2 | 0 4 6\n\nBu veri setinin ortancası kaçtır?", o:["15","18","19","20"], a:2,
     w:"Veriler 12, 15, 15, 19, 20, 24, 26'dır. Yedi verinin ortasındaki dördüncü veri 19'dur. 15 iki kez tekrar eder ama ortadaki değer değildir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir hedef tahtasına yapılan 40 atışın 14'ü kırmızı bölgeye isabet ediyor. Kırmızı bölgeye isabet etme olayının deneysel olasılığı yüzde kaçtır?", o:["%35","%14","%26","%40"], a:0,
     w:"Göreli sıklık 14/40 = 7/20 = 35/100 olduğu için deneysel olasılık %35'tir. Deneysel olasılık göreli sıklığa eşittir."}
  ]);

  /* ---------- 6. sınıf · Sosyal Bilgiler ---------- */
  Q6.sos = (Q6.sos || []).concat([
    {u:"ALAN 3 · Ortak Mirasımız", q:"Türk Kara Kuvvetleri, MÖ 209 yılını kuruluş yılı olarak kabul eder.\n\nBu tarihin kuruluş yılı sayılmasının sebebi aşağıdakilerden hangisidir?", o:["Bumin Kağan'ın Ötüken'de devleti kurduğu yıl olması","Teoman'ın Asya Hun Devleti'ni kurduğu yıl olması","Mete Han'ın Asya Hun tahtına çıktığı yıl olması","Kutluk Kağan'ın Çin'e karşı bağımsızlık kazandığı yıl olması"], a:2,
     w:"Kitaptaki bilgiye göre MÖ 209, Büyük Hun hükümdarı Mete Han'ın tahta çıkış tarihidir ve Kara Kuvvetlerinin kuruluşu bu tarihe dayandırılır. Asya Hun Devleti ise MÖ 220'de Teoman tarafından kurulmuştur."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"İlk Türk devletlerinde devletin önemli işleri kurultayda görüşülürdü. Kurultaya kağanın eşi, boy beyleri ve devletin ileri gelenleri katılırdı.\n\nKurultayda alınan kararlarla ilgili aşağıdakilerden hangisi doğrudur?", o:["Kararlar kesindi, kağan bunlara uymak zorundaydı","Kararlar tavsiye niteliğindeydi, son söz kağanındı","Kararları yalnız boy beyleri oylayarak alırdı","Kararlar halk tarafından seçilen temsilcilerce alınırdı"], a:1,
     w:"Kurultay bir danışma meclisiydi. Askerî, siyasi, ekonomik ve kültürel konular burada konuşulur, çıkan görüşler kağana öneri olarak sunulur, son kararı kağan verirdi."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Bir müzede Türkistan'dan getirilmiş tapınak kalıntıları ve minyatür örnekleri sergilenmektedir. Rehber, bu eserlerin büyük bölümünün Uygurlara ait olduğunu söylüyor.\n\nUygurlarda bu tür eserlerin yaygınlaşmasının temel nedeni hangisidir?", o:["Türk adını resmî devlet adı olarak kullanmaları","Ordularını onluk sisteme göre düzenlemeleri","Çin'i vergiye bağlayarak güçlü bir ekonomi kurmaları","Manihaizmi benimseyip yerleşik hayata geçmeleri"], a:3,
     w:"Bögü Kağan döneminde Manihaizm dinini benimseyen Uygurlar bozkır hayatını bırakıp şehirleşmeye yöneldi. Yerleşik hayat, tapınak gibi kalıcı yapıların ve minyatür sanatının gelişmesini sağladı."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Göktürklerde töre, değişen şartlara göre yenilenebilirdi ancak bazı hükümleri hiç değişmezdi.\n\nAşağıdakilerden hangisi törenin değişmeyen hükümlerinden biri DEĞİLDİR?", o:["Yargu (yüksek mahkeme)","Könilik (adalet)","Uzluk (iyilik, faydalılık)","Tüzlük (eşitlik)"], a:0,
     w:"Törenin değişmeyen dört hükmü könilik (adalet), uzluk (iyilik), tüzlük (eşitlik) ve kişiliktir (insanlık). Yargu ise Göktürklerde yüksek devlet mahkemesinin adıdır."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Eski Türklere göre hükümdara devleti yönetme yetkisi ve gücü Gök Tanrı tarafından verilirdi. Bu anlayışa kut denirdi.\n\nKut anlayışına göre hükümdarın görevlerinden biri aşağıdakilerden hangisidir?", o:["Töreyi dilediği gibi değiştirip kurultayı kaldırmak","Orduyu paralı askerlerden oluşturup savaşmak","Halkı doyurmak, giydirmek ve güvenliğini sağlamak","Yalnız kendi boyunu koruyup diğerlerini dağıtmak"], a:2,
     w:"Kitapta kut anlayışına bağlı görevler dağınık boyları toplayıp nüfusu çoğaltmak, halkı doyurup giydirmek ve halkı korumak olarak sayılır. Hükümdarın yetkisi sınırsız değildi, töreyle sınırlıydı."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Eski Türk toplumunda aileler birleşerek daha büyük toplulukları oluştururdu.\n\nBu toplulukların küçükten büyüğe sıralanışı hangi seçenekte doğru verilmiştir?", o:["Urug – oguş – budun – boy","Oguş – urug – boy – budun","Boy – oguş – urug – budun","Oguş – boy – urug – budun"], a:1,
     w:"En küçük birim aile (oguş) idi. Ailelerin birleşmesiyle urug (sülale), urugların birleşmesiyle boy, boyların bir araya gelmesiyle budun (millet) oluşurdu. Devlete il denirdi."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Hz. Muhammed (sav) döneminde Mescid-i Nebevî'nin arkasında bir bölüm yapıldı. Burada kimsesiz Müslümanlar barınıyor, aynı zamanda Kur'an ve ilim öğreniyordu.\n\nBu bölüme verilen ad hangisidir?", o:["Küttâb","Beytülhikme","Rasathane","Suffe"], a:3,
     w:"Mescid-i Nebevî'nin arkasındaki suffe, İslam'ın ilk eğitim yerlerindendir. Küttâb çocuklara ilk dinî eğitimin verildiği okullara, Beytülhikme Abbasilerin Bağdat'taki bilim merkezine, rasathane gök cisimlerinin gözlendiği yapıya denir."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Hz. Muhammed (sav) 632'deki Veda Hutbesi'nde bütün insanlığa seslenmiştir. Bu hutbe, 1948'de ilan edilen İnsan Hakları Evrensel Bildirgesi ile benzerlik gösterir.\n\nİki metin arasındaki bu benzerlik aşağıdaki ilkelerden hangisinde görülür?", o:["İnsanların eşit, can ve mallarının dokunulmaz sayılması","Hutbede yalnız Müslümanların haklarının anlatılması","Hutbede İslam devletinin sınırlarının açıklanması","Mekkeli müşriklerle yapılan antlaşmanın duyurulması"], a:0,
     w:"Veda Hutbesi'nde hiçbir ayrım yapılmadan insanların eşit olduğu, can ve mal dokunulmazlığına sahip oldukları vurgulanmıştır. Bu evrensel mesajlar insan hakları bildirgesinin temel ilkeleriyle örtüşür."}
  ]);
  H6.sos = (H6.sos || []).concat([
    {u:"ALAN 3 · Ortak Mirasımız", q:"İlk Türk devletlerinin tarihini araştıran uzmanlar, bilgilerin çoğunu Çin gibi komşu devletlerin kaynaklarından edinir.\n\nBunun temel nedeni hangisidir?", o:["Türk kaynaklarının Moğol işgalinde yakılıp yok olması","Çin kaynaklarının o dönemde Türkçe yazılmış olması","Türklerin II. Göktürklere kadar yazılı eser bırakmaması","Türklerin tarihlerini yalnız Çin sarayında yazdırması"], a:2,
     w:"Konargöçer yaşayan Türkler II. Göktürk Devleti dönemine kadar yazılı eser bırakmamıştır. Bu yüzden ilk bilgiler komşu devletlerin kayıtlarından ve sözlü kültürdeki destanlardan gelir."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"İlk Türk ordularının başarısında, sahte bir geri çekilmeyle düşmanı peşinden sürükleyip tuzağa düşürmeye dayanan bir savaş yöntemi etkili olmuştur.\n\nBu yöntemin adı nedir?", o:["Kurt oyunu (turan taktiği)","Onluk sistem","Daimî ordu ve ordu-millet anlayışı","Kut anlayışı"], a:0,
     w:"Kitapta kurt oyunu, hilal ya da turan taktiği adlarıyla geçen bu yöntemde ordu geri çekiliyormuş gibi yapar, düşmanı tuzağa çektikten sonra çevirip yener."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Eski Türklerde bir ailenin zenginliği ve gücü en çok neyle ölçülürdü?", o:["Sahip olduğu tarla ve bağların genişliğiyle","Biriktirdiği altın ve gümüş paralarla","Çin'den aldığı ipek kumaşların miktarıyla","Sahip olduğu at ve koyun sürüleriyle"], a:3,
     w:"Eski Türk ekonomisi hayvancılığa dayanırdı. At sürüsü sahibine itibar, koyun sürüsü maddi güç kazandırdığı için zenginliğin ölçüsü bu sürüler sayılırdı."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Hicri takvimin kabul edilmesi, beytülmalin kurulması ve divan teşkilatının oluşturulması aynı halife döneminde gerçekleşmiştir.\n\nBu halife kimdir?", o:["Hz. Ebu Bekir","Hz. Ömer","Hz. Osman","Hz. Ali"], a:1,
     w:"Kûfe, Basra ve Fustat şehirlerinin kurulması da Hz. Ömer döneminin çalışmalarıdır. Hicri takvimin başlangıcı olarak 622'deki hicret yılı esas alınmıştır."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Müslümanlardan kâğıt kullanımını öğrenen Batı'da bilgi hızla yayılmaya başladı, bazı Arapça kelimeler İspanyolcaya geçti.\n\nBu gelişmelerde en etkili olan İslam devleti hangisidir?", o:["Abbasi Devleti","Endülüs Emevi Devleti","Dört Halife yönetimi","Medine'deki ilk İslam devleti"], a:1,
     w:"İspanya'da kurulan Endülüs Emevileri, bulundukları coğrafya sayesinde Batı'yı bilim, sanat ve mimaride etkilemiştir. Kâğıdın Batı'ya tanıtılması ve Arapça kelimelerin İspanyolcaya geçmesi bu etkinin örnekleridir."}
  ]);
  EKC6.sos = (EKC6.sos || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Ali doğduğunda ailenin ilk çocuğuydu. İki yıl sonra kız kardeşi doğunca ağabey oldu. Okula başlayınca öğrenci, altıncı sınıfta da hem sınıf başkanı hem voleybol takımının oyuncusu oldu.\n\nAli'nin hayatından verilen bu kesit aşağıdakilerden hangisini gösterir?", o:["Dâhil olunan grupların ve rollerin zamanla değiştiğini","Kişinin yalnızca ailesinde rol üstlendiğini","Sonradan kazanılan rollerin doğuştan gelenlerin yerini aldığını","Okuldaki rollerin kişinin isteğinden bağımsız olduğunu"], a:0,
     w:"Ali'nin çocuk ve ağabey rolleri ailede, öğrenci, sınıf başkanı ve oyuncu rolleri okulda ortaya çıkmıştır. Yeni gruplara katıldıkça rolleri değişip çoğalmış, doğuştan gelen rolleri de sürmüştür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Osmanlı Dönemi'nde varlıklı kişiler ramazanda tanımadıkları mahalle bakkallarına gider, veresiye defterindeki borçların bir kısmını ya da tamamını öderdi. Bu uygulamaya “zimem defteri” denir.\n\nBu uygulama hangi kültürel bağımız ve hangi millî değerle ilişkilidir?", o:["Sanat eserlerimiz ve çalışkanlık değeri","Dilimiz ve bağımsızlık sevgisi","Gelenek-göreneklerimiz ve yardımlaşma","Tarihimiz ve vatanseverlik duygusu"], a:2,
     w:"Zimem defteri kuşaktan kuşağa aktarılan bir gelenektir. İhtiyaç sahibinin borcunu, kim olduğunu bilmeden ödemek yardımlaşma ve dayanışma değerlerini yaşatır, toplumsal birliği güçlendirir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir habere göre ülkemizde üretilen gıdaların yaklaşık %35'i sofraya ulaşmadan ziyan oluyor ve her gün yaklaşık 12 milyon ekmek çöpe atılıyor.\n\nBu soruna yönelik önerilerden hangisi hem uygulanabilir hem sürdürülebilir niteliktedir?", o:["Bir hafta boyunca evde hiç ekmek tüketmemeye karar vermek","Ailece ihtiyaç kadar ekmek alıp bayatları değerlendirmek","Fırınların ekmek üretimini kanunla tamamen yasaklamak","Çöpe atılan ekmeklerin fotoğraflarını yalnızca paylaşmak"], a:1,
     w:"İhtiyaç kadar alışveriş her ailenin hemen başlayıp sürekli yapabileceği bir davranıştır. Bir haftalık bırakma kalıcı değildir, üretimi yasaklamak uygulanamaz, yalnızca fotoğraf paylaşmak da israfı azaltmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Müslüman Türk toplumunda bazı vakıflar sofralardan artan yemekleri kuşlara ve yabani hayvanlara ulaştırmak, bazıları da bulaşıcı hastalığa yakalanıp evine kapanan insanları tedavi ettirmek için kurulmuştu.\n\nBu vakıflarla ilgili hangi yargıya ulaşılabilir?", o:["Sorunların çözümünün tamamen devlete bırakıldığına","Vakıfların yalnız eğitim alanında hizmet verdiğine","Bu hizmetlerin karşılığında ücret alındığına","Toplumsal sorunlara kalıcı çözümler arandığına"], a:3,
     w:"Ecdadımız hiçbir çıkar beklemeden kurduğu vakıflarla insanların ve hayvanların ihtiyaçlarına uzun süreli çözümler üretmiştir. Örnekler bu vakıfların sağlık ve hayvan koruma gibi farklı alanlarda karşılıksız hizmet verdiğini de gösterir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif, Türkiye'nin konum özelliklerini “mutlak konum” ve “göreceli konum” olarak iki gruba ayırıyor.\n\nAşağıdakilerden hangisini “mutlak konum” grubuna yazmalıdır?", o:["Asya, Avrupa ve Afrika'nın birbirine yaklaştığı yerde olması","Üç tarafının denizlerle çevrili olması","36°–42° kuzey paralelleri arasında yer alması","Balkanlar ile Kafkaslar arasında bulunması"], a:2,
     w:"Mutlak konum bir yerin Ekvator'a ve başlangıç meridyenine göre yeridir, paralel ve meridyen dereceleriyle anlatılır. Kıtalara, denizlere ve komşu bölgelere göre anlatılan konum ise göreceli konumdur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Doğu Karadeniz'in kırsal kesimlerinde arazi çok engebelidir ve miras yoluyla küçük parçalara bölünmüştür.\n\nBu durumun yerleşmeye etkisi aşağıdakilerden hangisidir?", o:["Evlerin birbirinden uzak, dağınık kurulması","Evlerin bir su kaynağının çevresinde toplanması","Nüfusun kıyıdan iç kesimlere kayması","Köylerin geniş düzlüklerde kurulması"], a:0,
     w:"Engebeli ve parçalı arazide evler birbirinden uzak kurulur. Kitaba göre bu durum yol, su, elektrik ve kanalizasyon gibi hizmetleri her eve götürmeyi pahalılaştırır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Erzurum ve Kars platolarında büyükbaş hayvancılık gelişmiştir.\n\nBunun temel nedeni aşağıdakilerden hangisidir?", o:["Kışların ılık ve kar yağışsız geçmesi","Verimli kıyı ovalarına yakın olmaları","Yükseltinin az, arazinin düzlüklerden oluşması","Yaz yağışlarıyla yeşeren çayırların bulunması"], a:3,
     w:"Doğu Anadolu'daki bu yüksek platolarda yaz yağışları geniş çayırları yeşertir. Hayvanlar için bol ot bulunması büyükbaş hayvancılığı geliştirmiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"TÜİK verilerine göre nüfus yoğunluğu İstanbul'da kilometrekareye 2.943 kişi, Tunceli'de ise 11 kişidir.\n\nBu farkın oluşmasında etkili olan doğal çevre özelliği hangisidir?", o:["Tunceli'nin üç tarafının denizlerle çevrili olması","Tunceli'nin dağlık ve engebeli bir yapıda olması","İstanbul'un karasal iklimin etkisinde kalması","Tunceli'nin geniş kıyı ovalarına sahip olması"], a:1,
     w:"Tunceli dağlık ve engebeli bir ildir, bu da tarım alanlarını ve yerleşime uygun yerleri sınırlar. İstanbul ise kıyıda, Asya ile Avrupa'yı birbirine bağlayan bir konumdadır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Burdur Gölü'nün suyu her geçen yıl azalmaktadır.\n\nAşağıdakilerden hangisi bu azalmanın beşerî (insan kaynaklı) sebebidir?", o:["Uzun süren kuraklık dönemleri","Sıcak havada aşırı buharlaşma","Tarım için açılan sondaj kuyuları","Yağışların yıllar içinde azalması"], a:2,
     w:"Kuraklık, buharlaşma ve yağış azlığı doğal etkenlerdir. Tarım için yer altından su çeken sondajlar ise insan faaliyetidir ve gölü besleyen suyu azaltır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Konya'daki Bozkır Barajı tamamlanınca Dedemli Mahallesi baraj gölünün altında kalacak. Bu yüzden mahallede yaşayan iki bine yakın kişi, Meram'da kurulan yeni konutlara taşınıyor.\n\nBu durum aşağıdakilerden hangisine örnektir?", o:["İnsan yapımı bir tesisin göçe yol açmasına","Bir doğal afetin zorunlu göçe yol açmasına","İklim değişikliğinin nüfusu azaltmasına","Yer şekillerinin ulaşımı zorlaştırmasına"], a:0,
     w:"Baraj, insanın doğal çevreyi değiştirerek kurduğu beşerî bir yapıdır. Baraj gölünün mahalleyi kaplaması insanların başka bir yere taşınmasına, yani göçe neden olmuştur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Şanlıurfa ve Gaziantep platolarında sanayi, ticaret ve hizmet faaliyetleri yoğundur.\n\nBu durumu en çok etkileyen doğal çevre özelliği hangisidir?", o:["Yükseltisi az, düzlük alanların geniş olması","Kışları ılık ve yağışlı geçmesi","Kıyıya paralel yüksek dağlarla çevrili olması","Her mevsim bol yağış alması"], a:0,
     w:"Bu platolar yükseltisi az, geniş düzlüklerdir. Düz arazide yol yapım masrafı az olduğu için ulaşım kolaylaşmış, sanayi, ticaret ve hizmet faaliyetleri gelişmiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"3 Ekim 2009'da “Türk Dili Konuşan Ülkeler İş Birliği Konseyi” adıyla kurulan kuruluş, 12 Kasım 2021'de bugünkü adını almıştır.\n\nBu kuruluş hangisidir?", o:["Uluslararası Türk Kültürü Teşkilatı","Yunus Emre Enstitüsü","Türk Devletleri Teşkilatı","Türk İş Birliği ve Koordinasyon Ajansı"], a:2,
     w:"Kuruluş, Türk devletleri arasındaki iş birliğini ve dayanışmayı geliştirmek için kurulmuştur. Türkiye, Azerbaycan, Kazakistan, Kırgızistan ve Özbekistan üye, Macaristan, Türkmenistan ve KKTC gözlemcidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Yurtdışı Türkler ve Akraba Topluluklar Başkanlığı (YTB), “Türkiye Bursları” ile ülkemizde okuyan farklı ülkelerden öğrenciler için İstanbul'da mezuniyet töreni düzenledi.\n\nBu haber, hangi alandaki uluslararası iş birliğine örnektir?", o:["Spor","Turizm","Sağlık","Eğitim"], a:3,
     w:"Burs verilen öğrencilerin ülkemizde lisans, yüksek lisans ve doktora yapması bu alandaki iş birliğinin örneğidir. Bu öğrenciler ülkelerine döndüklerinde iki ülke arasında birer dostluk köprüsü olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki kuruluş–görev eşleştirmelerinden hangisi doğrudur?", o:["TÜRKSOY – yabancılara Türkçe öğretmek","YTB – Türk dünyasının turizm başkentini seçmek","Yunus Emre Enstitüsü – Ortak Türk Alfabesini hazırlamak","TİKA – yurt dışında kalkınma projeleri yürütmek"], a:3,
     w:"TİKA, Balkanlar'dan Türkistan'a, Afrika'dan Latin Amerika'ya kadar pek çok bölgede kalkınma projeleri yürüten bir iş birliği kuruluşudur. Yabancılara Türkçeyi Yunus Emre Enstitüsü öğretir, TÜRKSOY ise kültür ve sanat alanında çalışır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"2017'de Türkiye, Azerbaycan ve Gürcistan'ın iş birliğiyle açılan Bakü-Tiflis-Kars demir yolu, Çin'den Avrupa'ya uzanan “Demir İpek Yolu”nun bir parçasıdır.\n\nBu hattın ülkemize en önemli katkısı hangisidir?", o:["Ülkemizdeki bütün karayollarının yerini alması","Ülkemizin bölgedeki stratejik konumunun önemini artırması","Türk cumhuriyetleriyle sınırların kaldırılmasını sağlaması","Deniz ticaretini tamamen gereksiz hâle getirmesi"], a:1,
     w:"Hat sayesinde ülkemiz üzerinden Rusya, Orta Asya ve Çin'e yük taşınmaktadır. Tarihî İpek Yolu'nu canlandırmayı hedefleyen bu proje Türkiye'nin bölgedeki stratejik önemini artırır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Türk Dünyası Ortak Alfabe Komisyonu, 34 harften oluşan “Ortak Türk Alfabesi” önerisini oy birliğiyle kabul etmiştir.\n\nBu çalışmanın Türk dünyasına en önemli katkısı aşağıdakilerden hangisidir?", o:["Türk cumhuriyetlerinde tek para birimine geçilmesi","Türk devletlerinin ortak bir orduya sahip olması","Bütün Türk lehçelerinin yasaklanıp tek dil konuşulması","Türk halkları arasında yazılı iletişimin kolaylaşması"], a:3,
     w:"Ortak alfabe, farklı Türk lehçelerinde yazılmış metinlerin herkes tarafından kolayca okunmasını sağlar. Böylece Türk halkları arasındaki iletişim ve kültürel iş birliği artar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Atatürk 1933'te yaptığı bir konuşmada Sovyet Rusya'nın bir gün dağılabileceğini ve o gün geldiğinde Türkiye'nin ne yapacağını bilmesi gerektiğini söylemiştir.\n\nAtatürk bu sözleriyle aşağıdakilerden hangisini vurgulamıştır?", o:["Sovyet Rusya ile bütün ilişkilerin hemen kesilmesini","Türk cumhuriyetlerinin tek bir devlette birleştirilmesini","Türk dünyasıyla dil ve tarih bağlarının güçlendirilmesini","Yabancı dil öğretiminin okullardan kaldırılmasını"], a:2,
     w:"Atatürk, Sovyet yönetimindeki dili bir, inancı bir kardeşlerimize sahip çıkmaya hazırlanmak gerektiğini söylemiştir. Ona göre bu hazırlık dil, tarih ve kültür gibi manevi köprüleri sağlam tutmakla olur. Nitekim 1991'de beş bağımsız Türk cumhuriyeti kurulmuştur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Türkiye, Bosna Hersek'te sel felaketinden sonra afet bölgesine konteyner evler göndermiştir. Gazze'deki saldırılarda yaralanıp tedavi için ülkemize getirilen çocuklara da psikolojik destek ve Türkçe dersi verilmektedir.\n\nBu çalışmalar en çok neyi gösterir?", o:["Gönül ve kültür bağlarının yardımlaşmayla sürdürüldüğünü","Ülkemizin yalnızca Türk devletleriyle iş birliği yaptığını","Bu ülkelerin yönetiminin Türkiye'ye bağlı olduğunu","Yardımların yalnızca ekonomik çıkar için yapıldığını"], a:0,
     w:"Bosna Hersek ve Filistin Türk devleti olmadığı hâlde ülkemizin tarihten gelen kültür ve gönül coğrafyasında yer alır. İhtiyaç anında yapılan bu yardımlar Türkiye'nin farklı toplumlarla kurduğu dostluk bağlarını gösterir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İstemi Yabgu döneminde Göktürkler, Sasaniler ve Doğu Roma İmparatorluğu ile ilişkiler kurdu. 567'de Doğu Roma'ya gönderilen heyet, Türkistan'dan bu imparatorluğa giden ilk elçilik heyeti sayılır.\n\nBu bilgiler Göktürkler hakkında hangi yargıyı destekler?", o:["Uluslararası siyasette etkin bir güç oldukları","Yerleşik hayata geçip şehirler kurdukları","İslamiyet'i kabul edip Araplarla birleştikleri","Çin'in egemenliği altında yaşadıkları"], a:0,
     w:"Güçlü komşularla elçi alışverişi yapmak, Göktürklerin dönemin uluslararası ilişkilerinde söz sahibi olduğunu gösterir. Göktürkler Mukan Kağan zamanında İpek Yolu'na da hâkim olmuştu."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Günümüzde Türk ordusunda kullanılan onbaşı, yüzbaşı ve binbaşı gibi rütbe adlarının kökeni ilk Türk devletlerine dayanır.\n\nBu adlar ilk Türk devletlerinin hangi uygulamasının izlerini taşır?", o:["Savaşta sahte geri çekilme taktiğinin uygulanması","Ordunun onluk sisteme göre örgütlenmesi","Kurultayda askerî kararların alınması","Orduya paralı askerlerin alınması"], a:1,
     w:"Mete Han'ın ilk kez uyguladığı bu düzende en büyük birlik 10 bin kişilik tümendi. Tümenler biner, yüzer ve onar kişilik birliklere ayrılır, başlarında tümenbaşı, binbaşı, yüzbaşı ve onbaşı bulunurdu."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Afyonkarahisar ve Çorum'da Bayat, Konya'da Çiğil, İzmir'de Kınık adlı yerleşim yerleri vardır.\n\nBu adlarla ilgili aşağıdakilerden hangisi söylenebilir?", o:["Bu yerlerin İslamiyet'ten sonra kurulan ilk şehirler olduğu","Türkistan'daki boy adlarının Anadolu'da yaşatıldığı","Bu adların Orhun Kitabeleri'nden alınmış kelimeler olduğu","Bu yerlerin Göktürklerin başkentleri olduğu"], a:1,
     w:"Eski Türklerde her boyun kendine ait adı ve damgası vardı. Türkistan'dan gelen boyların adlarının Anadolu'daki yer adlarında sürmesi, ilk Türk devletlerinden kalan mirasın bugün de yaşadığını gösterir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kemer tokaları, kılıç ve hançer kabzaları, at koşum takımları ilk Türk devletlerinin en önemli sanat eserleri arasındadır. Bu eşyaların üzerine pars, kurt, geyik, at gibi hayvan figürleri işlenmiştir.\n\nSanat eserlerinin genellikle bu tür taşınabilir eşyalar üzerinde yapılmasının temel nedeni hangisidir?", o:["Taş ve ağaç işçiliğini bilmemeleri","İnançlarının heykel yapmayı yasaklaması","Konargöçer bir hayat sürmeleri","Eserleri yalnız Çin'e satmak için üretmeleri"], a:2,
     w:"Yazın yaylaya, kışın ovaya göç eden ve çadırda yaşayan Türkler, yanlarında taşıyabilecekleri eşyaları süslemiştir. Tahta oymacılığı gelişmişti, taştan balballar da yapılmıştı, bu yüzden heykel yasağı ya da işçilik bilgisizliği söz konusu olamaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hun Türkleri Çin sarayına at ve kürk vermiş, karşılığında ipek almışlardır.\n\nBu bilgi eski Türklerde ticaretle ilgili hangi yargıyı destekler?", o:["Alışverişte altın ve gümüş paranın yaygın olarak kullanıldığını","Türklerin ticarette yalnızca tarım ürünleri sattığını","Ticaretin devlet tarafından tamamen yasaklandığını","Ticaretin büyük ölçüde değiş tokuşa dayandığını"], a:3,
     w:"Eski Türk ticaretinde alınan malın karşılığında başka bir mal verilirdi. Türklerin sattığı malların başında canlı hayvan ve hayvan ürünleri geliyordu."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Zeynep, ilk Türk devletlerindeki kurultay ile günümüzdeki Türkiye Büyük Millet Meclisini karşılaştıran bir tablo hazırlıyor.\n\nZeynep'in “benzerlik” sütununa yazması gereken bilgi hangisidir?", o:["Devletin önemli işlerinin görüşüldüğü meclis olması","Üyelerinin halk tarafından seçimle belirlenmesi","Son sözün hükümdara ait olması","Aldığı kararların yalnızca tavsiye niteliği taşıması"], a:0,
     w:"Kurultayda askerî, siyasi, ekonomik ve kültürel konular görüşülürdü, TBMM'de de ülkenin önemli işleri görüşülür. Kurultayın kararları ise tavsiye niteliğindeydi ve son söz kağanındı, TBMM'nin üyelerini ise halk seçer."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Abbasiler döneminde Bağdat'ta kurulan Beytülhikme'de Hint, Helen ve Yunan bilimine ait eserler tercüme edilmiş, farklı din ve kökenlerden bilginler birlikte çalışmıştır.\n\nBu çalışmaların insanlığın ortak mirasına katkısı hangisidir?", o:["Bilimsel çalışmaların yalnız dinî konularla sınırlı kalması","Eski bilgileri geliştirip günümüz bilimlerine temel atması","Farklı kültürlerin eserlerinin tamamen yok edilmesi","Bilginlerin yalnız Arap kökenli kişilerden seçilmesi"], a:1,
     w:"Beytülhikme'de antik dünyanın eserleri Arapçaya çevrilmekle kalmamış, matematikten tıbba pek çok alanda yeni bilgiler üretilmiştir. Bu çalışmalar günümüz bilimlerinin temelini oluşturmuştur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hicretten sonra Müslümanlar ile Müslüman olmayanlar arasındaki anlaşmazlıkları çözmek ve şehir halkının karşılıklı haklarını belirlemek için yazılı bir belge hazırlanmıştır.\n\nBazı düşünürlerce insanlık tarihinin ilk yazılı anayasası sayılan bu belge hangisidir?", o:["Hudeybiye Antlaşması","Medine Vesikası","Veda Hutbesi","Tıbb-ı Nebevî"], a:1,
     w:"Medine Vesikası, şehirde yaşayan farklı inanç ve topluluklar arasında hukuki bir zemin oluşturmuştur. Hudeybiye 628'de Mekkeli müşriklerle yapılan bir antlaşmadır, Veda Hutbesi ise Peygamberimizin 632'deki konuşmasıdır."}
  ]);

  /* ---------- 6. sınıf · Türkçe ---------- */
  Q6.tur = (Q6.tur || []).concat([
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Bir ülkeyi gerçekten tanımak isteyen kişi, yalnızca müzelerini ve ünlü yapılarını gezmekle yetinmemelidir. O ülkenin pazarlarında dolaşmalı, insanlarıyla aynı sofraya oturmalı, türkülerini dinlemelidir. Çünkü bir kültür en çok gündelik hayatın içinde yaşar.\n\nBu paragrafın ana düşüncesi aşağıdakilerden hangisidir?", o:["Bir ülkenin tarihini öğrenmenin en iyi yolu müzelerini gezmektir.","Gezilerde en çok zaman pazarlarda dolaşmaya ayrılmalıdır.","Bir milleti anlamak için onun her günkü yaşayışına katılmak gerekir.","Bir milletin duygularını en iyi o milletin türküleri anlatır."], a:2,
     w:"Son cümle ana düşünceyi açıklıyor: Bir kültür en çok gündelik hayatta yaşar. Bu yüzden bir ülkeyi tanımak için pazarına, sofrasına, türküsüne yani her günkü yaşayışına katılmak gerekir. Müzeler ve türküler paragrafın yalnızca bir parçasıdır."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Halk dansları, bir yörenin insanlarının duygularını ve yaşayışını hareketlerle anlatır. Karadeniz'in hızlı horonu, dalgalı denizi ve hareketli insanlarını yansıtır. Doğu Anadolu'nun halayları ise birlik olmayı, omuz omuza vermeyi anlatır. Zeybek oyunlarında Ege'nin yiğit insanlarının ağırbaşlı duruşu görülür.\n\nBu paragrafta aşağıdakilerden hangisine DEĞİNİLMEMİŞTİR?", o:["Horonun Karadeniz'in doğasıyla ilişkisine","Halayın birlik duygusunu yansıttığına","Zeybeğin hangi bölgeye ait olduğuna","Halk danslarında hangi çalgıların çalındığına"], a:3,
     w:"Paragrafta horonun Karadeniz'in denizini ve insanını yansıttığı, halayın birliği anlattığı, zeybeğin Ege'ye ait olduğu söyleniyor. Dansların hangi çalgılarla oynandığından hiç söz edilmiyor."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Origami, kâğıdı kesmeden ve yapıştırmadan yalnızca katlayarak çeşitli şekiller oluşturma sanatıdır. Japonya'da yüzyıllardır yapılan origamide tek bir kare kâğıtla turna, kurbağa ya da çiçek gibi şekiller yapılabilir. Origami el becerisini geliştirdiği ve sabrı öğrettiği için bugün pek çok okulda da öğretilmektedir.\n\nBu metnin anahtar kelimeleri aşağıdakilerin hangisinde birlikte verilmiştir?", o:["origami, kâğıt, katlamak, şekil","origami, Japonya, turna, kurbağa","yüzyıl, okul, sabır, bugün","kesmek, yapıştırmak, tek, kare"], a:0,
     w:"Metin, origaminin kâğıdı katlayarak şekil yapma sanatı olduğunu anlatıyor. Konuyu taşıyan ve sık geçen sözcükler origami, kâğıt, katlamak ve şekildir. Turna, kurbağa, okul gibi sözcükler ayrıntıdır."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Masallar yalnızca çocukları eğlendirmez, onlara hayatı da öğretir. Halk kültürü üzerine uzun yıllar çalışmış bir araştırmacı, “Masal dinleyerek büyüyen çocuk, iyiyle kötüyü erken ayırt etmeyi öğrenir.” der. Gerçekten de pek çok masalda iyilik ödüllendirilir, kötülük cezasını bulur.\n\nBu paragrafta düşünceyi geliştirmek için asıl olarak hangi yola başvurulmuştur?", o:["Sayısal verilerden yararlanma","Tanık gösterme","Benzetme","Tanımlama"], a:1,
     w:"Yazar, masalların çocuklara hayatı öğrettiği düşüncesini halk kültürü üzerine çalışan bir araştırmacının sözüyle güçlendirmiş. Bir uzmanın sözüyle düşünceyi desteklemek tanık göstermedir."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Kitap okumak, farklı kültürleri tanımamıza yardımcı olur. Okul kütüphanemizde geçen yıl en çok ödünç alınan 50 kitabın 32'si başka ülkelerin masallarını ve öykülerini anlatıyordu. Bu kitapları okuyan öğrencilerin yüzde 80'i yeni bir ülkeyi merak etmeye başladığını söyledi.\n\nBu paragrafta düşünceyi geliştirmek için daha çok hangi yoldan yararlanılmıştır?", o:["Benzetme","Tanık gösterme","Tanımlama ve örneklendirme","Sayısal verilerden yararlanma"], a:3,
     w:"Yazar düşüncesini “50 kitabın 32'si” ve “yüzde 80” gibi rakamlarla desteklemiş. Rakamlar düşünceyi somut ve inandırıcı kılar."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Hat, harflerin belirli kurallara göre güzel ve estetik biçimde yazılması sanatıdır. Bu sanatla uğraşan kişiye hattat denir. Hattatlar kamış kalem, mürekkep ve özel olarak hazırlanmış kâğıt kullanır.\n\nBu paragrafta düşünceyi geliştirmek için hangi yola başvurulmuştur?", o:["Tanımlama","Benzetme","Tanık gösterme","Sayısal verilerden yararlanma"], a:0,
     w:"Paragraf hat sanatının ne olduğunu açıklıyor ve “hattat” sözcüğünün anlamını veriyor. “… sanatıdır”, “… denir” gibi kalıplar tanımlamanın ipuçlarıdır."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Japonya'da kiraz ağaçları çiçek açmıştı,\nBir çocuk eğilerek selam verdi bana.\n\nFas'ta bir çarşıda nane kokusu sardı her yanı,\nYaşlı bir adam gülümseyerek çay uzattı.\n\nEve döndüğümde annem kapıda bekliyordu,\nDünyanın en güzel sofrası bizim evdeydi.\n\nBu şiir kaç dize ve kaç kıtadan oluşmaktadır?", o:["3 dize, 6 kıta","6 dize, 2 kıta","6 dize, 3 kıta","2 dize, 3 kıta"], a:2,
     w:"Şiirin her satırı bir dizedir, toplam 6 dize var. Boşluklarla ayrılmış üç bölüm yani üç kıta var. Her kıta iki dizeden oluştuğu için bu kıtalara beyit de denir."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Dedemin saçları bembeyaz, kar gibi,\nGülüşü ılık ılık, bahar gibi.\nHer akşam bir masal anlatır bize,\nSesi serin, akan bir pınar gibi.\n\nBu dörtlükteki redif aşağıdakilerden hangisidir?", o:["-ar","gibi","-ar gibi","bize"], a:1,
     w:"Redif, dize sonlarında aynen tekrar eden, anlamı ve görevi aynı olan sözcük ya da ektir. Üç dizenin sonunda “gibi” sözcüğü aynı görevle tekrar ediyor. Ondan önceki kar, bahar ve pınar sözcüklerindeki “-ar” ise uyaktır."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Halk müziğimizde pek çok çalgı kullanılır. Bağlama ve kemençe tellerinden ses çıkarılarak çalınır. Davul ve def vurularak, zurna ve kaval ise üflenerek çalınır.\n\nMetindeki çalgılar çalınış biçimine göre sınıflandırıldığında hangisi doğru olur?", o:["Telli: bağlama, kemençe · Vurmalı: davul, def · Üflemeli: zurna, kaval","Telli: bağlama, zurna · Vurmalı: davul, def · Üflemeli: kemençe, kaval","Telli: bağlama, kemençe · Vurmalı: davul, kaval · Üflemeli: zurna, def","Telli: kemençe, def · Vurmalı: davul, bağlama · Üflemeli: zurna, kaval"], a:0,
     w:"Metne göre bağlama ve kemençe tellerinden, davul ve def vurularak, zurna ve kaval üflenerek çalınır. Sınıflandırmada her unsur, ölçüte uyan tek bir gruba yerleştirilir."}
  ]);
  H6.tur = (H6.tur || []).concat([
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Her ülkenin kendine özgü bir selamlaşma biçimi vardır. Mesela Japonlar karşılarındaki kişiyi hafifçe eğilerek selamlar. Tayland'da insanlar ellerini göğüslerinin önünde birleştirir. Türkiye'de büyüklerin eli öpülüp alına konur.\n\nBu paragrafta düşünceyi geliştirmek için daha çok hangi yola başvurulmuştur?", o:["Tanımlama","Örneklendirme","Tanık gösterme","Sayısal verilerden yararlanma"], a:1,
     w:"Yazar, her ülkenin kendine özgü bir selamlaşma biçimi olduğu düşüncesini Japonya, Tayland ve Türkiye'den örneklerle somutlaştırmış. “Mesela” sözcüğü örneklendirmenin ipucudur."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Geleneksel Japon evlerinde odalar kaydırmalı kâğıt kapılarla birbirinden ayrılır, yerlere hasır döşenir. Geleneksel Türk evlerinde ise odalar ahşap kapılarla ayrılır, yerleri kilim ve halılar süsler. Her iki evde de içeri ayakkabıyla girilmez.\n\nBu paragrafta düşünceyi geliştirmek için hangi yola başvurulmuştur?", o:["Tanık gösterme","Sayısal verilerden yararlanma","Tanımlama","Karşılaştırma"], a:3,
     w:"Japon ve Türk evleri benzer ve farklı yönleriyle birlikte ele alınmış. Kapılar ve yer döşemeleri farklı, ayakkabıyla girmeme ortak. “ise” ve “her iki … de” sözleri bu yolun ipuçlarıdır."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Kapadokya'daki peri bacaları, uzaktan bakıldığında başlarına taş şapka geçirmiş dev nöbetçiler gibi görünür. Gün doğarken bu kayalar pembe bir ipek kumaş gibi parlar.\n\nBu paragrafta düşünceyi geliştirmek için hangi yola başvurulmuştur?", o:["Benzetme","Tanık gösterme","Sayısal verilerden yararlanma","Tanımlama"], a:0,
     w:"Peri bacaları taş şapkalı dev nöbetçilere, gün doğarken parlayan kayalar ipek kumaşa benzetilmiş. “gibi” sözcüğü bu yolun ipucudur."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Gün doğunca uyanır yemyeşil orman,\nDağların arasından yükselir duman.\nÇoban kavalını çalar uzaklarda,\nBu ne güzel, bu ne tatlı bir zaman.\n\nBu dörtlükte uyak hangi sözcükler arasında kurulmuştur?", o:["orman – uzaklarda – zaman","uyanır – yükselir – çalar","orman – duman – zaman","doğunca – arasından – kavalını"], a:2,
     w:"Uyak dize sonlarındaki ses benzerliğidir. Orman, duman ve zaman sözcükleri “-man” sesiyle uyaklanıyor. Üçüncü dizenin sonundaki “uzaklarda” bunlarla uyaklı değildir."},
    {u:"KONU 4 · Paragraf ve Metin Türleri", q:"Dünyanın birçok yerinde insanlar yeni yılı farklı geleneklerle karşılar. Kimi ülkelerde gece yarısı on iki üzüm yenir, kimilerinde kapılar süslenir, kimilerinde de gökyüzü havai fişeklerle aydınlanır. Bu geleneklerin hepsinde ortak bir dilek vardır: Herkes yeni yılın bereketli ve mutlu geçmesini ister.\n\nBu paragrafın konusu aşağıdakilerden hangisidir?", o:["Havai fişeklerin ilk kez hangi ülkelerde kullanıldığı","Yeni yılın çeşitli ülkelerde nasıl karşılandığı","Üzümün insan sağlığına yararları","Evlerin kapılarını süslemenin incelikleri"], a:1,
     w:"Paragraf, yeni yılın dünyanın farklı yerlerinde hangi geleneklerle karşılandığını anlatıyor. Üzüm, kapı süsleme ve havai fişek yalnızca örnek olarak geçiyor."}
  ]);
  EKC6.tur = (EKC6.tur || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Millî Mücadele yıllarında bir millî marş yazılması için müsabaka açıldı. Yurdun dört bir yanından yüzlerce şiir gönderildi. Sonunda Mehmet Âkif Ersoy'un yazdığı İstiklal Marşı, 12 Mart 1921'de Türkiye Büyük Millet Meclisinde kabul edildi.\n\nMetinde geçen “müsabaka” sözcüğünün anlamı hangisidir?", o:["Toplantı","Yarışma","Kutlama","Sergi"], a:1,
     w:"İpucu yüzlerce şiirin gönderilmesi ve sonunda birinin kabul edilmesi. Pek çok kişinin katıldığı ve en iyisinin seçildiği etkinlik yarışmadır. Müsabaka = yarışma."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Japonya'da insanlar selamlaşırken birbirlerine hafifçe eğilir. Bu davranış, karşıdaki kişiye duyulan hürmeti gösterir. Yaşça büyüklerin ve öğretmenlerin karşısında daha derin eğilinir.\n\nMetinde geçen “hürmet” sözcüğünün anlamı hangisidir?", o:["Korku","Özlem","Kızgınlık","Saygı"], a:3,
     w:"İpucu: Eğilerek selam vermek ve büyüklerin karşısında daha derin eğilmek saygı göstermenin bir yoludur. Hürmet = saygı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Merhaba Elif,\nBen Yuki, Japonya'nın Kyoto şehrinde yaşıyorum. Bizim evlerimizde içeri girerken ayakkabılar kapıda çıkarılır. Yemeklerimizi genellikle çubuklarla yeriz. Okulumuzda öğle yemeğinden sonra sınıfımızı kendimiz temizleriz. Sizin okulunuzda da böyle bir alışkanlık var mı? Mektubunu bekliyorum.\nSevgiler, Yuki\n\nMektuba göre Yuki'nin okulunda öğle yemeğinden sonra ne yapılır?", o:["Öğrenciler bahçede birlikte oyun oynar.","Öğrenciler ayakkabılarını kapıda çıkarır.","Öğrenciler sınıfı kendileri temizler.","Öğrenciler arkadaşlarına mektup yazar."], a:2,
     w:"Mektupta açıkça yazıyor: “Okulumuzda öğle yemeğinden sonra sınıfımızı kendimiz temizleriz.” Yüzey anlam sorusunda cevap metinde aranır, yorum katılmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Merhaba Elif,\nBen Yuki, Japonya'nın Kyoto şehrinde yaşıyorum. Bizim evlerimizde içeri girerken ayakkabılar kapıda çıkarılır. Yemeklerimizi genellikle çubuklarla yeriz. Okulumuzda öğle yemeğinden sonra sınıfımızı kendimiz temizleriz. Sizin okulunuzda da böyle bir alışkanlık var mı? Mektubunu bekliyorum.\nSevgiler, Yuki\n\nMektuba göre aşağıdakilerden hangisi SÖYLENEMEZ?", o:["Yuki, Kyoto şehrinde yaşamaktadır.","Yuki'nin evine ayakkabıyla girilmez.","Yuki, yemeğini her zaman kaşıkla yer.","Yuki, Elif'ten bir cevap beklemektedir."], a:2,
     w:"Mektupta yemeklerin genellikle çubuklarla yendiği yazıyor, kaşıktan hiç söz edilmiyor. “Her zaman kaşıkla” bilgisi mektupla çelişir. Diğer üç bilgi mektupta açıkça var."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir afişin ortasında, farklı ülkelerin yöresel kıyafetlerini giymiş altı çocuk el ele tutuşmuş. Çocukların arkasında kocaman, gülümseyen bir dünya resmi var. Afişin üst kısmında “23 Nisan Çocuk Şenliği” yazıyor. En altta ise “Bir dünya, bin renk” sözü yer alıyor.\n\nBu afişte iletilmek istenen asıl düşünce hangisidir?", o:["Kültürleri ayrı olsa da çocuklar dost olabilir.","Yöresel kıyafetler yalnızca şenliklerde giyilmelidir.","Dünyanın en kalabalık ülkeleri afişte gösterilmiştir.","Çocuklar en çok resim yapmayı ve dans etmeyi sever."], a:0,
     w:"Görsel ve yazı birlikte okunur. Farklı yöresel kıyafetler farklı kültürleri, el ele tutuşmak dostluğu, gülümseyen dünya barışı anlatır. “Bir dünya, bin renk” sözü de farklılıkların bir arada güzel olduğunu vurgular."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir sütun grafiğinin başlığında “6-A sınıfı hangi ülkeyi görmek istiyor?” yazıyor. Grafikte dört sütun var. Sütunların üstündeki sayılar şöyle: Japonya 10, Mısır 7, Brezilya 5, Kanada 3 öğrenci.\n\nBu grafiğe göre aşağıdakilerden hangisi söylenebilir?", o:["Japonya'yı seçenler, Mısır'ı seçenlerin iki katıdır.","Brezilya'yı seçenler, Kanada'yı seçenlerden azdır.","Ankete toplam yirmi öğrenci katılmıştır.","Kanada'yı seçen öğrenci sayısı en azdır."], a:3,
     w:"Sütunlardaki sayılar karşılaştırılır. En küçük sayı 3'tür ve Kanada'ya aittir. Japonya 10, Mısır 7 olduğu için iki kat değildir. Toplam 10 + 7 + 5 + 3 = 25 öğrencidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kerem o sabah her zamankinden erken uyandı. Ütülü gömleğini giydi, yakasına kırmızı beyaz bir rozet taktı. Okula giden sokak baştan sona bayraklarla süslenmişti. Uzaktan bando sesleri geliyordu. Okul bahçesinde veliler ve öğrenciler kürsünün önünde sıra sıra dizilmişti.\n\nBu metinden aşağıdakilerin hangisi çıkarılabilir?", o:["Kerem o gün okula geç kalmıştır.","O gün okulda bir tören yapılacaktır.","Törende Kerem bir şiir okuyacaktır.","Kerem'in ailesi törene gelmeyecektir."], a:1,
     w:"Metinde tören sözcüğü geçmiyor ama ipuçları bunu gösteriyor: bayraklarla süslü sokak, bando sesleri, kürsünün önünde dizilen veliler ve öğrenciler. Basit çıkarım, birkaç ipucunu birleştirip açıkça söylenmeyeni bulmaktır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Millî Mücadele yıllarında köylerde ordu için yardım toplanıyordu. Hasan Dede'nin tek varlığı bir ineğiydi. Hasan Dede ineğini satıp bütün parasını yardım toplayanlara verdi. Komşuları “Şimdi sütü nereden bulacaksın?” diye sorunca “Vatan olmazsa ne süt kalır ne ev.” dedi.\n\nHasan Dede'nin davranışından hareketle ulaşılabilecek en kapsamlı yargı hangisidir?", o:["O yıllarda halk, vatanı için elindeki her şeyi vermeye hazırdı.","Köylerde süt ihtiyacı o yıllarda genellikle ineklerden karşılanırdı.","Yardım toplayanlar köylülerden yalnızca para istiyordu.","Hasan Dede, köyünün en zengin kişilerinden biriydi."], a:0,
     w:"Hasan Dede tek varlığını vatan için vermekten çekinmiyor. Üst düzey çıkarımda tek bir ayrıntıdan değil, davranışın ardındaki değerden genel bir yargıya ulaşılır. Süt ve yardım bilgileri ayrıntıdır, zenginlik ise metinle çelişir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sınıfa yeni gelen Lin, ilk günlerde kimseyle konuşmadı. Türkçeyi henüz iyi bilmiyordu. Bir teneffüste Can yanına gelip resim defterini açtı. Lin defterin bir köşesine bir ejderha çizdi, Can da yanına bir uçurtma. İkisi birden güldü. O günden sonra her teneffüste birlikte resim yaptılar. Dönem sonunda Lin, Can'a Türkçe bir not yazdı: “Sen benim ilk arkadaşımsın.”\n\nBu metinden çıkarılabilecek en kapsamlı yargı hangisidir?", o:["Resim yapmak çocukların en sevdiği teneffüs etkinliğidir.","Okula yeni gelen öğrenciler ilk günlerde her zaman sessiz kalır.","Dostluk kurmak için aynı dili konuşmak her zaman gerekmez.","Bir dili öğrenmenin en iyi yolu resim yapmaktır."], a:2,
     w:"Lin ile Can başta ortak bir dil konuşamıyor ama resim yoluyla anlaşıp arkadaş oluyorlar. Metnin bütünü, dostluğun dil engelini aşabileceğini gösteriyor. Diğer yargılar metinde dayanağı olmayan genellemelerdir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ece ile kardeşi Efe, Anıtkabir'i ziyaret etti. Ece müzedeki eşyaları tek tek inceledi, defterine notlar aldı. Efe ise en çok Aslanlı Yol'dan etkilendi, aslan heykellerinin resmini çizdi. İkisi de Atatürk'ün mozolesinin önünde uzun süre sessizce durdu.\n\nMetne göre Ece ile Efe'nin ortak davranışı hangisidir?", o:["Müzedeki bütün eşyaları tek tek incelemeleri","Aslan heykellerinin resmini çizmeleri","Mozolenin karşısında saygıyla beklemeleri","Gördüklerini defterlerine not etmeleri"], a:2,
     w:"“İkisi de” sözü ortak davranışı gösteriyor: Kardeşler mozolenin önünde uzun süre sessizce durdu. Eşyaları incelemek ve not almak yalnızca Ece'nin, resim çizmek yalnızca Efe'nin davranışıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Türkiye'de misafire genellikle Türk kahvesi ya da çay ikram edilir. Japonya'da ise misafire çoğunlukla yeşil çay sunulur. İki ülkede de misafir başköşeye oturtulur ve evin en değerli kişisi sayılır.\n\nMetne göre Türkiye ile Japonya arasındaki fark hangi konudadır?", o:["Misafire ikram edilen içecek","Misafire gösterilen değer","Misafirin oturtulduğu yer","Misafirin evde ağırlandığı süre"], a:0,
     w:"“ise” sözcüğü farkı gösteriyor: Türkiye'de Türk kahvesi ya da çay, Japonya'da yeşil çay ikram ediliyor. Misafire verilen değer ve oturtulduğu yer iki ülkede aynıdır, ağırlama süresinden ise hiç söz edilmiyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"1. metin: Kapadokya'daki peri bacaları, çok uzun zaman önce yanardağlardan çıkan küllerin katmanlar hâlinde birikmesi ve bu katmanların rüzgâr ve yağmurla aşınmasıyla oluşmuştur. Bölge her yıl dünyanın dört bir yanından çok sayıda turist çeker.\n2. metin: Sabahın ilk ışığında balonla yükseldim. Aşağıda peri bacaları taştan şapkalarıyla bana el sallıyor gibiydi. O an kendimi bir masalın içinde sandım.\n\nBu iki metinle ilgili aşağıdakilerden hangisi söylenebilir?", o:["İki metinde de yazar, kendi yaşadığı bir anıyı ayrıntılı biçimde anlatır.","İki metin de peri bacalarının nasıl oluştuğunu bilimsel olarak açıklar.","1. metinde öznel, 2. metinde ise nesnel bir anlatım tercih edilmiştir.","İkisinin konusu aynıdır ama 1. metin bilgi verir, 2. metin duygu aktarır."], a:3,
     w:"İki metin de peri bacalarını anlatıyor. 1. metin oluşumlarını nesnel bilgilerle açıklıyor, 2. metinde yazar kendi yaşadığını ve duygularını anlatıyor. Metinler arası karşılaştırmada konu, amaç ve anlatım birlikte değerlendirilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bayram sabahı Elif ile dedesi köy meydanına gitti. Meydanda davullar çalıyor, halay çekiliyordu. Öğleye doğru ikisi de çınarın altındaki uzun sofraya oturdu.\n\nMetindeki unsurlar “kişi, yer, zaman” başlıklarına göre sınıflandırıldığında hangisi doğru olur?", o:["Kişi: Elif, dede · Yer: köy meydanı, sofra · Zaman: bayram sabahı, halay","Kişi: Elif, dede · Yer: köy meydanı, çınarın altı · Zaman: bayram sabahı, öğle","Kişi: Elif, davul · Yer: çınarın altı, köy meydanı · Zaman: öğle, bayram sabahı","Kişi: dede, halay · Yer: köy meydanı, öğle vakti · Zaman: bayram sabahı, çınar"], a:1,
     w:"Kişiler Elif ve dedesi, yerler köy meydanı ve çınarın altı, zaman bayram sabahı ve öğle vaktidir. Davul, halay ve sofra ise olayda geçen nesne ve etkinliklerdir, kişi ya da zaman bildirmez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ebru, suyun üzerine serpilen boyalarla yapılan geleneksel bir sanattır. Ebru yapan sanatçı, özel bir bitki özüyle koyulaştırılmış suya fırçayla boya serper. Sonra boyaları ince bir çubukla şekillendirerek desen oluşturur. Bu desen, suyun üzerine yavaşça bırakılan kâğıda geçer. Sudaki boyalar hiçbir zaman aynı biçimi almadığı için her ebru tektir.\n\nBu metnin konusunu en iyi yansıtan anahtar kelimeler hangileridir?", o:["ebru, su, boya, desen","fırça, çubuk, bitki, sanatçı","sonra, yavaşça, hiçbir, için","geleneksel, ince, aynı, tek"], a:0,
     w:"Anahtar kelimeler metnin konusunu taşıyan, sık geçen temel sözcüklerdir. Metin, ebrunun su üzerindeki boyalarla oluşturulan desenlerle yapıldığını anlatıyor. Fırça ve çubuk ayrıntıdır, “sonra, yavaşça, için” gibi sözcükler ise konuyu taşımaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Arılar çiçek çiçek dolaşır, yapar bal,\nKuşlar yuva kurar, sallanır her bir dal.\nOrmanın sesini dinle, biraz dur,\nDoğanın koynunda bir süre daha kal.\n\nBu dörtlükte uyağı oluşturan ses benzerliği hangisidir?", o:["-ur","-ar","-ır","-al"], a:3,
     w:"Uyak dize sonlarına bakılarak bulunur. Bal, dal ve kal sözcüklerinde “-al” ses benzerliği vardır. “dur” uyağa katılmaz. “yapar, kurar” gibi sözcükler dize içinde kaldığı için uyak oluşturmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bizim evde her akşam demlenen bir çay var,\nPenceremizden bize gülümseyen bir ay var.\nNinem masal anlatır, dedem okur gazete,\nBu küçük evde kocaman bir saray var.\n\nBu dörtlükte redif olarak kullanılan sözcük hangisidir?", o:["-ay","var","ay var","bir"], a:1,
     w:"Redif, dize sonlarında aynen tekrar eden, anlamı ve görevi aynı olan ek ya da sözcüktür. Üç dizenin sonunda “var” sözcüğü tekrar ediyor. Ondan önceki çay, ay ve saray sözcüklerindeki “-ay” ise uyaktır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kardeşimin gülüşü bahar gibi,\nElleri yumuşacık, bembeyaz kar gibi.\nUyurken izlerim onu sessizce,\nYanakları kıpkırmızı, bir nar gibi.\n\nBir gün bütün dünyayı gezsem bile\nAçmaz hiçbir bahçede böyle çiçek.\nAnnemin sesi, kardeşimin gülüşü\nBenim için en güzel, en gerçek.\n\nBu şiirle ilgili aşağıdakilerden hangisi YANLIŞTIR?", o:["Şiir iki kıta ve sekiz dizeden oluşur.","Birinci kıtada “gibi” sözcüğü redif olarak kullanılmıştır.","İkinci kıtada yalnızca ikinci ve dördüncü dizeler uyaklıdır.","İki kıtada da uyak aynı seslerle kurulmuştur."], a:3,
     w:"Birinci kıtada uyak bahar, kar ve nar sözcüklerindeki “-ar”, ikinci kıtada çiçek ve gerçek sözcüklerindeki “-çek” sesleriyle kurulmuş. Uyak sesleri farklı olduğu için bu yargı yanlıştır, diğerleri doğrudur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Nevruz, baharın gelişini ve doğanın uyanışını kutlayan çok eski bir bayramdır. Her yıl 21 Mart günü kutlanan bu bayram, Türkiye'nin yanı sıra Azerbaycan, Kazakistan ve Özbekistan gibi pek çok ülkede coşkuyla karşılanır. Bugün dünyada 300 milyondan fazla insan bu bayramı kutlamaktadır.\n\nBu paragrafta düşünceyi geliştirme yollarından hangisine BAŞVURULMAMIŞTIR?", o:["Tanımlama","Örneklendirme","Tanık gösterme","Sayısal verilerden yararlanma"], a:2,
     w:"Paragrafta Nevruz tanımlanmış, kutlandığı ülkelerden örnekler verilmiş, kutlayanların sayısı rakamla belirtilmiş. Bir uzmanın ya da tanınmış bir kişinin sözüne yer verilmediği için tanık gösterme yoktur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ninem, kapımızı çalan her misafiri baş tacı eder. Onu evin en güzel köşesine oturtur, en güzel yemeklerini önüne koyar. Misafir giderken de arkasından bir tas su döker ki yolu açık olsun.\n\nMetinde geçen “baş tacı etmek” deyiminin anlamı hangisidir?", o:["Başına süslü, değerli bir şapka takmak","Çok değer verip özenle ağırlamak","Kapıda uzun süre bekletmek","Bir an önce evden göndermek"], a:1,
     w:"Deyim burada mecaz anlamıyla kullanılmış. Ninenin misafiri en güzel köşeye oturtup en güzel yemekleri ikram etmesi anlamı açıklıyor: Baş tacı etmek, birine çok değer verip onu özenle ağırlamaktır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sözcük havuzu: pasaport · harita · baharat\n\nAşağıdakilerden hangisi bu üç sözcüğün hepsini anlamına uygun kullanarak yaratıcı bir öykü başlangıcı oluşturmuştur?", o:["Eski haritayı açar açmaz odaya baharat kokusu yayıldı, pasaportum kıpırdandı.","Pasaportumu çantama yerleştirdim, sonra haritaya bakarak havaalanının yolunu buldum.","Annem çorbaya biraz baharat ekledi, ben de masada eski bir harita çizmeye başladım.","Baharat çarşısında dolaşırken pasaportumu kaybettim, çok üzülüp hemen eve döndüm."], a:0,
     w:"Yalnızca bu cümlede üç sözcüğün üçü de var. Ayrıca kokunun odaya yayılması ve pasaportun “kıpırdanması” gibi hayal gücüne dayanan ayrıntılar yolculuk heyecanını canlı biçimde sezdiriyor. Diğer cümlelerde sözcüklerden biri eksik."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif, Türkiye ile Japonya'daki okul hayatını karşılaştıran bir yazı yazıyor.\n\nAşağıdaki cümlelerden hangisinde iki ülkenin okul hayatı karşılaştırılmıştır?", o:["Japonya, Asya kıtasının doğusunda yer alan ve binlerce adadan oluşan bir ülkedir.","Japon okullarında öğrenciler sabah derse başlamadan önce ayakkabılarını değiştirir.","Okul, öğrencilerin bilgi ve beceri kazandığı, arkadaşlık kurduğu bir eğitim kurumudur.","Bizde okullar eylülde açılır, Japonya'da ise okul yılı nisan ayında başlar."], a:3,
     w:"Karşılaştırma, iki şeyi benzer ya da farklı yönleriyle birlikte ele almaktır. Bu cümlede iki ülkede okul yılının başladığı ay yan yana konmuş, “ise” farkı göstermiş. Diğer cümleler yalnızca tek bir şey hakkında bilgi veriyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Can, “Türk mutfağının tatlıları” konulu yazısını sınıflandırma yaparak geliştirmek istiyor.\n\nCan'ın yazısına ekleyeceği cümle aşağıdakilerden hangisi olmalıdır?", o:["Baklava, ince yufkaların arasına ceviz ya da fıstık konarak yapılan bir tatlıdır.","Ninem, bayram sabahı yapılan tatlıların evin en güzel geleneği olduğunu söylerdi.","Bu tatlıları üçe ayırabiliriz: hamur tatlıları, sütlü tatlılar ve meyve tatlıları.","Türk lokumu, yüzyıllardır pek çok ülkede sevilerek yenen bir tatlıdır."], a:2,
     w:"Sınıflandırma, varlıkları ortak özelliklerine göre gruplara ayırmaktır. Bu cümlede tatlılar türlerine göre üç gruba ayrılmış. Diğer cümleler bir tatlıyı tanıtıyor, bir anıyı aktarıyor ya da bilgi veriyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Öğretmen, öğrencilerden “Farklı kültürleri tanımak insanı zenginleştirir.” düşüncesini yorumlamalarını istedi.\n\nAşağıdaki öğrenci yazılarından hangisinde görüş bir gerekçeyle desteklenmiştir?", o:["Dünyada iki yüze yakın ülke vardır ve bu ülkelerde binlerce dil konuşulur.","Bence doğru, çünkü başka kültürlerden insanlar tanıyan kişi yeni bakış açıları kazanır.","Geçen yaz ailemle birlikte komşu bir ülkeye gittik ve orada çok güzel bir hafta geçirdik.","Bu düşünceye kesinlikle katılıyorum ve herkesin de katılması gerektiğini düşünüyorum."], a:1,
     w:"Yorum yazarken önce görüş açıkça söylenir, sonra “çünkü” gibi bir sözle gerekçesi verilir. Bu yazı ikisini de yapıyor. Diğerlerinde ya görüş yok, yalnızca bilgi ya da anı var, ya da görüş gerekçesiz bırakılmış."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Zeynep, “Okulumuzda yabancı dil öğrenmeye ilgi artıyor.” düşüncesini sayısal verilerden yararlanarak desteklemek istiyor.\n\nZeynep'in paragrafına ekleyeceği cümle hangisi olmalıdır?", o:["Geçen yıl dil kulübüne 40 öğrenci katılmıştı, bu yıl bu sayı 75'e çıktı.","Öğretmenimiz, yeni bir dil öğrenmenin yeni bir dünyayı keşfetmek gibi olduğunu söyledi.","Yabancı dil, insanın kendi ana dili dışında öğrendiği her dildir.","Örneğin arkadaşım Can, yaz tatilinde kendi kendine İspanyolca öğrenmeye başladı."], a:0,
     w:"Sayısal veri, düşünceyi rakamlarla destekler. Kulübe katılanların 40'tan 75'e çıkması ilginin arttığını somut biçimde gösteriyor. Diğer cümlelerde rakam yok."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki cümlelerin hangisinde iki noktadan sonra, önceki cümleyi açıklayan tam bir cümle gelmiştir?", o:["Kitap fuarında üç ülkenin standını tek tek gezdik: Japonya, Mısır ve Peru.","Bu geziden bir ders çıkardım: Farklı olan her şey yanlış değildir.","Zeynep: Bu müzeyi daha önce hiç gezmemiştim, çok beğendim.","Pazardan şunları aldık: domates, biber, patlıcan ve taze fasulye."], a:1,
     w:"İki noktadan sonraki cümle “bir ders” sözünün ne olduğunu açıklıyor; açıklama tam bir cümle olduğu için büyük harfle başlar. Öbür cümlelerde iki noktadan sonra ya sıralanan ögeler ya da konuşan kişinin sözü geliyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki cümlelerin hangisinde “de / da” ile ilgili bir yazım yanlışı yapılmıştır?", o:["Kitabını Ayşe'de unutmuşsun.","Hem çay hem de kahve ikram ettiler.","Ayşe'de bizimle müzeye gelecek.","Paris'te yaşayan kuzenim de geldi."], a:2,
     w:"Bu cümledeki “de” bile, dahi anlamında bir bağlaçtır. Bağlaç olan de/da ayrı yazılır ve kesme işaretiyle ayrılmaz: “Ayşe de bizimle müzeye gelecek.” “Ayşe'de unutmuşsun” sözündeki “-de” ise bulunma hâli ekidir ve özel ada geldiği için kesmeyle ayrılır."}
  ]);

  /* ---------- 7. sınıf · Din Kültürü ve Ahlak Bilgisi ---------- */
  Q7.din = (Q7.din || []).concat([
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Allah'ın peygamberleri aracılığıyla gönderdiği, insanları kendi özgür iradeleriyle iyiye ve doğruya yöneltmeyi amaçlayan ilahi kurallar bütününe ne ad verilir?", o:["Mezhep","Din","Din anlayışı","İtikat"], a:1,
     w:"Bu tanım dinin tanımıdır. İlk insan ve ilk peygamber Hz. Âdem'den son peygamber Hz. Muhammed'e kadar bütün peygamberlere gönderilen dinin adı İslam'dır."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"“Din anlayışı” ile ilgili aşağıdaki bilgilerden hangisi YANLIŞTIR?", o:["İnsanların ilahi mesajı yorumlamasıyla oluşur.","Kişiye ve zamana göre değişebilir.","Yorum içerdiği için bireyseldir.","Bütün Müslümanlar için bağlayıcıdır."], a:3,
     w:"Müslümanlar için bağlayıcı olan, dinin kendisidir. Din anlayışı insanların yorumu olduğu için bireyseldir, kişiye ve zamana göre değişebilir."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Tıp eğitimi almış bir kişi, insanın yaratılış aşamalarını anlatan ayetleri tıp bilgisiyle açıklarken bir tarihçi aynı ayetleri farklı bir bakış açısıyla değerlendirebilir.\n\nBu durum, din anlayışındaki yorum farklılıklarının hangi sebebine örnektir?", o:["Kişilerin bilgi birikimi ve uzmanlıklarının farklı olması","İslam'ın farklı kültürlerin yaşadığı bölgelere yayılması","Dinin temel ilkelerinin zamanla değişmiş olması","Bölgelere göre farklı mimari anlayışların bulunması"], a:0,
     w:"Meslek, bilgi birikimi, yetenek ve tecrübe gibi kişisel özellikler insanların ayetlerden anladıklarını etkiler. Bu, insanın yapısından kaynaklanan bir farklılıktır."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Hz. Peygamber'in vefatından sonra İslam'ın geniş bir coğrafyaya yayılması, Müslümanların din anlayışını nasıl etkilemiştir?", o:["İslam'ın temel ilkeleri bölgeden bölgeye değişmiştir.","Müslüman olan halklar bütün eski kültürlerini bırakmıştır.","Din anlayışı, bulunulan bölgenin koşullarından etkilenmiştir.","Farklı bölgelerdeki Müslümanlar âlimlere hiç başvurmamıştır."], a:2,
     w:"Müslümanlar farklı kültürlerle tanışmış, din anlayışları da yaşadıkları bölgenin koşullarından etkilenmiştir. Müslüman olan halklar İslam'a uygun alışkanlık ve kültürlerini sürdürmüştür."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Hz. Peygamber'den sonra karşılaşılan yeni sorunları çözmeye çalışan sahabe ve âlimler, yorumlarını neye dayandırmışlardır?", o:["Yalnızca kendi bölgelerinin geleneklerine","Kur'an-ı Kerim'e ve sünnete","Yalnızca kişisel zevk ve tercihlerine","Önceki dinlerin kutsal kitaplarına"], a:1,
     w:"Müslümanlar sorunlarını önce sahabilere, sonra âlimlere götürmüş, onlar da meselelerin çözümünde Kur'an-ı Kerim'i ve sünneti esas almıştır. Ortaya çıkan yorumlar, İslam'ı doğru anlama ve aslına uygun yaşama çabasının sonucudur."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Aşağıdakilerden hangisi din anlayışındaki yorum farklılıklarının faydalarından biri DEĞİLDİR?", o:["Müslümanlar arasındaki iletişimi zayıflatması","Fıkıh, kelam, tasavvuf gibi ilimlerin doğmasına vesile olması","İslam'ın farklı kültürlerde kabul görmesini kolaylaştırması","Toplumda farklılıklara saygı kültürünü oluşturması"], a:0,
     w:"Dinin temel ilkelerine bağlı kalınarak yapılan yorumlar Müslümanlar arasındaki iletişimi zayıflatmamış, tersine güçlendirmiştir. Bu yorumlar ilimlerin doğmasına, İslam'ın yayılmasına ve farklılıklara saygıya da katkı sağlamıştır."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Mevlana'nın Mesnevi'deki hikâyesinde karanlıkta file dokunan kişilerden biri hortuma dokunup “Fil bir boruya benziyor.” der, bir başkası kulağa dokunup “Fil bir yelpaze gibi.” der.\n\nBu hikâyeden çıkarılabilecek sonuç aşağıdakilerden hangisidir?", o:["Görülmeyen bir şey hakkında asla hiçbir yorum yapılamaz.","Bir konuda yalnızca ilk konuşanın görüşü doğrudur.","Dokunarak edinilen bilgiler her zaman yanlıştır.","İnsanlar aynı şeyi farklı açılardan değerlendirebilir."], a:3,
     w:"Herkes filin yalnız dokunduğu bölümünü bildiği için onu farklı tarif etmiştir. İnsanlar da olayları kendi bakış açılarıyla değerlendirir, bu yüzden dinle ilgili konularda da farklı yorumlar ortaya çıkabilir."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"İslam'ın temel ilkelerinin değişmesinin söz konusu olmamasının sebebi aşağıdakilerden hangisidir?", o:["Her dönemde âlimler tarafından yeniden yorumlanmaları","Farklı kültürlerin etkisiyle zamanla oluşmaları","Vahiyle belirlenip sünnetle hayata geçirilmiş olmaları","Yalnızca belirli bir bölgede yaşayanlara hitap etmeleri"], a:2,
     w:"İslam'ın temel ilkeleri vahiyle belirlenmiş ve Hz. Peygamber'in sünnetiyle hayata geçirilmiştir, bu yüzden değişmez. Bu ilkeleri anlamak ve uygulamak ise akıl ve irade sahibi insanın sorumluluğundadır."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Âlimlerin dinin ayrıntılarına ilişkin konularda kendine özgü kural ve metotlarla oluşturdukları görüşler toplamına ne ad verilir?", o:["İtikat","Mezhep","Vahiy","Sünnet"], a:1,
     w:"Mezhep sözlükte “gidilecek yol, takip edilen yöntem, metot, ekol” demektir. İslam düşüncesindeki farklı yorumlar zamanla sistemleşerek mezhep adını almıştır."}
  ]);
  H7.din = (H7.din || []).concat([
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"“Bu Kur'an, ayetlerini düşünsünler ve akıl sahipleri öğüt alsınlar diye sana indirdiğimiz mübarek bir kitaptır.” (Sad suresi 29. ayet)\n\nBu ayete göre Kur'an karşısında insandan nasıl bir tutum beklenir?", o:["Anlamını önemsemeden yalnızca ezberlemesi","Akla hiç başvurmadan yalnızca okuması","Üzerinde düşünerek ondan öğüt alması","Başkalarının yorumlarını aynen tekrarlaması"], a:2,
     w:"Ayet, Kur'an'ın üzerinde düşünülmesi ve ondan öğüt alınması için indirildiğini bildirir. Dini anlamak için aklı kullanmak gerekir. İnsanların bilgi ve bakış açıları farklı olduğundan bu çaba farklı yorumlara da yol açabilir."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Aşağıdakilerden hangisi din anlayışındaki yorum farklılıklarının sebeplerinden biri DEĞİLDİR?", o:["İnsanların zevk ve yeteneklerinin farklı olması","Dinin temel ilkelerinin zamanla değişmesi","İslam'ın geniş coğrafyalara yayılması","Bazı ayetlerin farklı şekillerde yorumlanması"], a:1,
     w:"Yorum farklılıkları insanın yapısından, İslam'ın farklı coğrafyalara yayılmasından ve bazı ayet ve uygulamaların farklı yorumlanmasından doğar. Dinin temel ilkeleri ise vahiyle belirlendiği için değişmez."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Bir öğrenci din ile din anlayışını karşılaştıran bir tablo hazırlıyor.\n\nAşağıdaki bilgilerden hangisini tablonun “din” sütununa yazmalıdır?", o:["Müslümanlar için bağlayıcıdır.","Yorum içerdiği için bireyseldir.","İnsanın bakış açısına göre şekillenir.","Kişiden kişiye farklılık gösterebilir."], a:0,
     w:"Din Kur'an-ı Kerim ve sünnet kaynaklıdır ve Müslümanlar için bağlayıcıdır. Bireysel olan, kişiye ve bakış açısına göre farklılaşabilen ise din anlayışıdır."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"Âlimlerin meselelerin çözümünde ortaya koyduğu farklı görüşler, aşağıdakilerden hangisinin doğmasına vesile olmuştur?", o:["Yeni inanç esaslarının ortaya çıkmasının","Farz ibadetlerin sayısının artmasının","Kur'an-ı Kerim'in farklı nüshalarının","Fıkıh, kelam ve tasavvuf gibi ilimlerin"], a:3,
     w:"Âlimlerin farklı görüşleri fıkıh, kelam ve tasavvuf gibi ilimlerin doğmasına vesile olmuş, İslam düşüncesinde ilmî birikimi zenginleştirmiştir."},
    {u:"ÜNİTE 3 · İslam Düşüncesinde Yorumlar", q:"İslam'ın yayıldığı bölgelerde yaşayan halklar, Müslüman olduktan sonra hangi alışkanlık ve kültürlerini sürdürmüşlerdir?", o:["İslam'a uygun olanlarını","Yalnızca dil ve kıyafetlerini","İslam'dan önceki bütün alışkanlıklarını","Yalnızca yöneticilerin seçtiklerini"], a:0,
     w:"Kitaba göre Müslüman olan halklar İslam'a uygun olan alışkanlık ve kültürlerini sürdürmüştür. Yani İslam yerel kültürleri bütünüyle silmemiş, dine uygun olanlar yaşamaya devam etmiştir."}
  ]);
  EKC7.din = (EKC7.din || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi haccın farz olmasının şartlarından biri DEĞİLDİR?", o:["Sağlıklı olmak","Yol güvenliğine sahip olmak","Mukim olmak","Belirli ekonomik güce sahip olmak"], a:2,
     w:"Haccın şartları Müslüman, akıllı ve ergen, sağlıklı ve hür olmak, ekonomik güce ve yol güvenliğine sahip olmaktır. Mukim olmak, yani yolculukta bulunmamak ise kurban kesmekle yükümlü olmanın şartlarındandır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hac ve umreyle ilgili aşağıdaki kavram–tanım eşleştirmelerinden hangisi YANLIŞTIR?", o:["Şavt – Kâbe'nin etrafında bir tur dönmek","Say – Safa ile Merve arasında yedi kez gidip gelmek","Mikat – ihrama girilmesi gereken sınır yerleri","Telbiye – Arafat'ta bir süre beklemek"], a:3,
     w:"Arafat'ta bir süre beklemeye vakfe denir. Telbiye, ihrama girenlerin okuduğu “Lebbeyk Allahümme lebbeyk…” diye başlayan duadır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Haccın yapılışı sıralandığında Arafat vakfesinden hemen SONRA hangi görev gelir?", o:["Kudüm tavafı","Müzdelife vakfesi","Veda tavafı","Safa ile Merve arasında say"], a:1,
     w:"Arife Günü Arafat'ta vakfe yapıldıktan sonra güneş batınca Müzdelife'ye geçilir. Bayramın ilk günü sabah namazından sonra haccın vaciplerinden olan Müzdelife vakfesi yapılır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Umre ibadetiyle ilgili aşağıdaki bilgilerden hangisi doğrudur?", o:["Hac günleri dışında yılın herhangi bir zamanında yapılabilir.","Şartları, hac için aranan şartlardan farklıdır.","İmkânı olan her Müslüman'a, hac gibi ömründe bir kez farzdır.","Umrede de Arafat'ta vakfe yapılır ve şeytan taşlanır."], a:0,
     w:"Umrenin hac gibi belirli bir vakti yoktur, hac günleri dışında her zaman yapılabilir. Şartları hacla aynıdır, hükmü sünnettir. Vakfe ve şeytan taşlama yalnız hacda yapılır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir hacı adayı günlüğüne şunu yazmıştır: “Elime aldığım taşları atarken kibir, bencillik ve cimrilik gibi kötü huylarımı taşladığımı hissettim.”\n\nBu hacı adayının sözünü ettiği görev hangi mekânda yerine getirilir?", o:["Arafat","Müzdelife","Mina","Safa ve Merve"], a:2,
     w:"Şeytan taşlama, Kurban Bayramı'nın ilk günü Mina'da yapılır ve bayramın diğer günlerinde de sürer. Müzdelife'de ise taşlamada kullanılacak taşlar toplanır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kurban ibadetiyle ilgili aşağıdaki bilgilerden hangisi YANLIŞTIR?", o:["Farz bir ibadettir.","Mal ile yapılan bir ibadettir.","Hicret'in ikinci yılında emredilmiştir.","Önceki ilahi dinlerde de yer almıştır."], a:0,
     w:"Kurban vacip bir ibadettir. Mal ile yapılır, Hicret'in ikinci yılında emredilmiştir ve önceki ilahi dinlerde de vardır (Hac 34)."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kurbanlık hayvanlarla ilgili aşağıdaki eşleştirmelerden hangisi doğrudur?", o:["Koyun – yedi kişiye kadar ortaklaşa kesilebilir","Sığır – bir yaşını doldurması yeterlidir","Keçi – iki yaşını doldurmuş olmalıdır","Deve – beş yaşını doldurmuş olmalıdır"], a:3,
     w:"Koyun ve keçi bir, sığır ve manda iki, deve beş yaşını doldurmuş olmalıdır. Koyun ve keçi bir kişi adına, sığır, manda ve deve ise bir ile yedi kişi arasında ortaklaşa kesilebilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Onların etleri ve kanları asla Allah'a ulaşmaz. Fakat O'na sizin takvanız ulaşır…” (Hac suresi 37. ayet)\n\nBu ayetten kurban ibadetiyle ilgili hangi sonuca ulaşılabilir?", o:["Kurbanın değeri, kesilen hayvanın büyüklüğüne bağlıdır.","Kurbanda asıl önemli olan, kulun Allah'a bağlılığıdır.","Kurban yalnızca etinin paylaşılması için kesilir.","Kurban kesmek yerine parasını bağışlamak yeterlidir."], a:1,
     w:"Ayete göre Allah'a ulaşan, kurbanın eti ya da kanı değil, kulun takvası yani Allah'a karşı gelmekten sakınmasıdır. Kurban, kulun Allah'a bağlılığının sembolüdür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hz. Peygamber kurban etinin nasıl paylaştırılmasını tavsiye etmiştir?", o:["Tamamının kurban kesemeyen ihtiyaç sahiplerine dağıtılmasını","Tamamının aile içinde yenip gelen misafirlere ikram edilmesini","Üçe bölünüp ihtiyaç sahibi, akraba-komşu ve aileye ayrılmasını","Yarısının satılıp parasının yardım kuruluşlarına bağışlanmasını"], a:2,
     w:"Peygamberimiz etin bir bölümünün kurban kesemeyen ihtiyaç sahiplerine, bir bölümünün akraba ve komşulara verilmesini, kalanının aile içinde yenmesini tavsiye etmiştir. Böylece kurban, toplumda yardımlaşma ve dayanışmayı canlı tutar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kurbanlık hayvan seçilirken aşağıdakilerden hangisine dikkat edilmesi GEREKMEZ?", o:["Kulağının ya da kuyruğunun yarıdan fazlasının kopmuş olmamasına","Semiz olmasına, aşırı zayıf olmamasına","Bir ya da iki gözünün kör olmamasına","Tüylerinin tek renk olmasına"], a:3,
     w:"Kurbanlık hayvan sağlıklı, semiz ve canlı bakışlı olmalıdır. Gözü kör, kulağı ya da kuyruğu yarıdan fazla kopmuş olmamalı, cildinde yara bulunmamalıdır. Tüylerinin rengi ise bir şart değildir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi hac ibadetinin kültürümüze yansımalarından biri DEĞİLDİR?", o:["Hacı adaylarının dualarla uğurlanması","Hacdan dönenlerin ziyaret edilip tebrik edilmesi","Hacıların misafirlerine zemzem ve hurma ikram etmesi","Hacı adaylarına Arife Günü bayramlık giydirilmesi"], a:3,
     w:"Hacı adaylarının dualarla uğurlanması, hacdan dönenlerin ziyaret edilmesi, zemzem ve hurma ikramı hac geleneklerimizdendir. Bayramlığını Arife Günü giyen çocuklara bazı yörelerde “Arife çiçeği” denir, bu bir bayram geleneğidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bazı yörelerimizde hâlâ yaşatılan “hacı kapısı” geleneği aşağıdakilerden hangisidir?", o:["Hacca gidenin evinin dış kapısının boyanıp dinî motiflerle süslenmesi","Hacı adaylarının yola çıkmadan önce kapı kapı dolaşıp helallik istemesi","Hacdan dönenlerin komşu kapılarına zemzem ve hurma bırakması","Bayram sabahı evlerin kapılarının tekbirlerle açılması"], a:0,
     w:"Hac yolculuğuna çıkan kişinin ailesi evin dış kapısını boyar ve dinî motiflerle süsler. Hacı, dönüşünde bu kapının önünde sevinçle karşılanır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Teşrik tekbiri hangi zaman aralığında getirilir?", o:["Bayram namazından sonra, yalnızca cami avlusunda","Arife sabahından bayramın 4. günü ikindisine kadar","Ramazan boyunca her gece teravih namazlarından sonra","Bayramın yalnızca ilk günü, kurban kesilirken"], a:1,
     w:"Teşrik tekbiri Arife Günü sabah namazından başlayarak bayramın dördüncü günü ikindi namazına kadar farz namazların ardından getirilir: “Allahu ekber Allahu ekber, Lâ ilâhe illallahu vallahu ekber. Allahu ekber ve lillahi'l-hamd.”"},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif'in ailesi bayram sabahı erkenden kalktı. Babası ve dedesi teşrik tekbiri getirerek bayram namazına gitti. Namazdan sonra kurban kesildi, etin bir kısmı komşulara ve ihtiyaç sahiplerine dağıtıldı. Öğleden sonra büyükler ziyaret edildi, çocuklara harçlık verildi.\n\nBu metinde aşağıdaki geleneklerden hangisine DEĞİNİLMEMİŞTİR?", o:["Bayram namazı kılınması","Kurban etinin paylaşılması","Hacı adaylarının uğurlanması","Aile büyüklerinin ziyaret edilmesi"], a:2,
     w:"Metinde teşrik tekbiri, bayram namazı, kurban etinin paylaşılması, büyüklerin ziyaret edilmesi ve çocuklara harçlık verilmesi anlatılır. Hacı adaylarının uğurlanmasından söz edilmez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ali'nin dedesi, hastalıktan kurtulursa bir kurban keseceğini adamıştı. İyileşince adadığı kurbanı kesti.\n\nBu kurbanla ilgili aşağıdakilerden hangisi doğrudur?", o:["Etinden adak sahibi ve ailesi yiyemez.","Hükmü müstehaptır, isteyen keser.","Yeni doğan bir çocuk için kesilir.","Hükmü sünnettir, etinden herkes yiyebilir."], a:0,
     w:"Bir dileğin gerçekleşmesi için kesilen kurban adak kurbanıdır. Hükmü vaciptir, etinden adak sahibi ve ailesi yiyemez. Akika yeni doğan çocuk için kesilir ve sünnettir, şükür kurbanı ise müstehaptır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kâfirun suresinin indirilmesine sebep olan olay aşağıdakilerden hangisidir?", o:["Müşriklerin Müslümanların Kâbe'yi ziyaret etmesini engellemesi","Müşriklerin bir yıl Allah'a, bir yıl putlara ibadeti önermesi","Müslümanların Mekke'den Medine'ye hicret etmeye hazırlanması","Müşriklerin Peygamberimizden mucize göstermesini istemesi"], a:1,
     w:"Rivayete göre Mekkeli müşrikler Peygamberimize bir yıl Allah'a, bir yıl kendi putlarına ibadet etmeyi teklif etmiş, sure bu teklif üzerine indirilmiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kâfirun suresindeki “Leküm dînüküm veliye dîn” ayetinin anlamı aşağıdakilerden hangisidir?", o:["Ben sizin kulluk ettiklerinize kulluk etmem.","Siz de benim kulluk ettiğime kulluk edecek değilsiniz.","Ben sizin kulluk ettiklerinize kulluk edecek değilim.","Sizin dininiz size, benim dinim de banadır."], a:3,
     w:"“Leküm dînüküm veliye dîn” surenin altıncı ve son ayetidir, anlamı “Sizin dininiz size, benim dinim de banadır.” şeklindedir. “Lâ a'büdü mâ ta'büdûn” ise “Ben sizin kulluk ettiklerinize kulluk etmem.” demektir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kâfirun suresinin anlamından aşağıdaki mesajlardan hangisi çıkarılabilir?", o:["Tevhit inancından asla taviz verilmez.","Kötülüklerin şerrinden Allah'a sığınılmalıdır.","Kişi kendi inancını başkalarına dayatmalıdır.","Farklı inançlar zamanla birleştirilmelidir."], a:0,
     w:"Surede tevhit dışındaki her inanç reddedilir, iman ile küfür arasında inanç konusunda uzlaşma olmayacağı bildirilir. Allah'a sığınmayı öğütleyen sureler ise Felak ve Nâs'tır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Din ile din anlayışı arasındaki farkla ilgili aşağıdakilerden hangisi doğrudur?", o:["Din de din anlayışı da yorum içerdiği için bireyseldir.","Din anlayışı vahiy kaynaklı olduğu için hiç değişmez.","Din bağlayıcıdır, din anlayışı kişiye göre değişebilir.","Dinin temel ilkeleri zamana göre değişebilir."], a:2,
     w:"Din Allah'tan gelir, Müslümanlar için bağlayıcıdır ve temel ilkeleri değişmez. Din anlayışı ise insanların yorumudur, bireyseldir, kişiye ve zamana göre değişebilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kur'an-ı Kerim'deki bazı ayetler ve Hz. Peygamber'in bazı uygulamaları âlimler tarafından farklı şekillerde anlaşılmıştır.\n\nBu durumla ilgili aşağıdakilerden hangisi söylenebilir?", o:["Dinin temel ilkelerinin değiştiğini gösterir.","Din anlayışındaki farklılıkların sebeplerindendir.","Âlimlerin Kur'an ve sünneti esas almadığını gösterir.","Müslümanlar arasında ayrılığa yol açan bir eksikliktir."], a:1,
     w:"İslam'ın temel kaynakları Kur'an ve sünnettir. Bazı ayetlerin ve Hz. Peygamber'in uygulamalarının farklı yorumlanması, din anlayışındaki farklılıkların sebeplerinden biridir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıda bazı melekler ve görevleri eşleştirilmiştir:\nI. Cebrail – vahiy getirmek\nII. Mikâil – sûra üflemek\nIII. Azrail – ölüm vakti gelenlerin canını almak\nIV. İsrafil – rızıkların dağıtılması\n\nBu eşleştirmelerden hangileri doğrudur?", o:["I ve II","I ve III","II ve IV","III ve IV"], a:1,
     w:"Cebrail vahiy getirir, Azrail ölüm vakti gelenlerin canını alır. Sûra üfleyen İsrafil, rızıkların dağıtılması ve tabiat olaylarıyla görevli olan ise Mikâil'dir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ahiret hayatının aşamaları hangi seçenekte doğru sıralanmıştır?", o:["Kıyamet → ölüm → baas → mahşer → mizan → cennet ve cehennem","Ölüm → baas → kıyamet → mahşer → mizan → cennet ve cehennem","Ölüm → kıyamet → mahşer → baas → mizan → cennet ve cehennem","Ölüm → kıyamet → baas → mahşer → mizan → cennet ve cehennem"], a:3,
     w:"Ahiret hayatı ölümle başlar. Ardından kıyamet kopar, insanlar yeniden diriltilir (baas), mahşerde toplanır, ameller mizanda tartılır ve herkes cennete ya da cehenneme gider."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Dedesini kaybeden Can'a annesi “Ölüm bir son değil, dedenle ahirette yeniden buluşacağız.” der.\n\nAnnesinin bu sözü, ahiret inancının insana kazandırdıklarından hangisini yansıtır?", o:["Yok olma endişesinden kurtulmayı","Dünya işlerinden bütünüyle el çekmeyi","Yaşanan acıyı hiç hissetmemeyi","Sorumluluklarını başkalarına bırakmayı"], a:0,
     w:"Ahirete inanan insan ölümün yok oluş olmadığını, sevdikleriyle ahirette yeniden buluşacağını bilir. Bu inanç ona yok olma endişesinden kurtulup huzur bulma imkânı verir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ahirette yaptıklarının hesabını vereceğine inanan Ali, parktaki ağaçlara zarar veren arkadaşlarını uyarır ve sokak hayvanlarına su koyar.\n\nAli'nin bu davranışları, ahiret inancının hangi kazanımıyla ilgilidir?", o:["Kıyametin zamanını öğrenme merakı","Musibetlere karşı sabırlı olma","Canlılara karşı sorumluluk bilinci","Dünya hayatını tek hayat sanma"], a:2,
     w:"Ahirete inanan insan yaptıklarının hesabını vereceğini bilir. Bu yüzden ailesine, çevresine ve bütün canlılara karşı sorumluluk bilinciyle davranır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Nâs suresindeki “Minel cinneti vennâs” ayetinin anlamı aşağıdakilerden hangisidir?", o:["İnsanların İlah'ına","İnsanların Melik'ine","Sinsi vesvesecinin kötülüğünden","Cinlerden ve insanlardan"], a:3,
     w:"Surenin son ayeti olan “Minel cinneti vennâs” “cinlerden ve insanlardan” demektir. Kalplere vesvese veren sinsi vesvesecinin cinlerden de insanlardan da olabileceğini bildirir."}
  ]);

  /* ---------- 7. sınıf · Fen Bilimleri ---------- */
  Q7.fen = (Q7.fen || []).concat([
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Proteinlerin kimyasal sindirimi hangi organda başlar?", o:["Ağız","İnce bağırsak","Mide","Kalın bağırsak"], a:2,
     w:"Mide öz suyundaki enzimler proteinlerin kimyasal sindirimini başlatır. Midede ayrıca kasların kasılıp gevşemesiyle fiziksel sindirim olur."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Sindirimi tamamlanan besinlerin emilerek kana geçmesini hızlandıran, ince bağırsağın iç yüzeyindeki girintili çıkıntılı yapılar hangisidir?", o:["Alveol","Bronşçuk","Safra kesesi","Villus"], a:3,
     w:"Villuslar ince bağırsağın iç yüzeyini genişleterek temas yüzeyini artırır, böylece besinler hızla emilir. Alveol ve bronşçuk solunum sistemine aittir, safra kesesi ise karaciğerin salgısını toplar."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Aşağıdaki yapı ve organlardan hangisinde sindirim GERÇEKLEŞMEZ?", o:["Ağız","Yemek borusu","Mide","İnce bağırsak"], a:1,
     w:"Yemek borusu besini kas hareketleriyle yutaktan mideye iletir, bu yapıda sindirim olmaz. Ağızda, midede ve ince bağırsakta ise sindirim gerçekleşir."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Karaciğerin salgıladığı safra sıvısı ile ilgili hangisi doğrudur?", o:["Kalın bağırsağa gönderilir.","Proteinlerin kimyasal sindirimini başlatır.","Yağların fiziksel sindirimine yardım eder.","Pankreasta depolanır."], a:2,
     w:"Safra karaciğerde üretilir, safra kesesinde toplanır ve bir kanalla ince bağırsağa gönderilir. Orada yağların fiziksel sindirimine yardım eder."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Kan ile vücut hücreleri arasındaki madde alışverişi dolaşım sisteminin hangi yapısında gerçekleşir?", o:["Kılcal damar","Kalp","Atardamar","Toplardamar"], a:0,
     w:"Kılcal damarlar atardamarlarla toplardamarları birbirine bağlayan en ince damarlardır. İnce yapıları sayesinde kan ile hücreler arasındaki madde alışverişi burada olur."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Yaralanmalarda damarın iç yüzeyinde pıhtılaşarak kan kaybını önleyen yapı hangisidir?", o:["Alyuvar","Kan pulcukları","Akyuvar","Plazma"], a:1,
     w:"Kan pulcukları zedelenen damarın iç yüzeyinde pıhtılaşıp yarayı tıkar. Alyuvar oksijen ve karbon dioksit taşır, akyuvar mikroplara karşı savunma yapar, plazma ise kanın sıvı kısmıdır."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Aşağıdaki kişilerden hangisi kan bağışçısı OLAMAZ?", o:["30 yaşında, 70 kg, sağlıklı bir erkek","19 yaşında, 55 kg, sağlıklı bir kadın","45 yaşında, 80 kg, sağlıklı bir kadın","16 yaşında, 60 kg, sağlıklı bir genç"], a:3,
     w:"Kan bağışı için 18–65 yaş arasında, 50 kg'ın üzerinde ve önemli bir sağlık sorunu olmayan biri olmak gerekir. 16 yaşındaki genç yaş şartını sağlamaz."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Solunum sırasında havadaki oksijenin kana, kandaki karbon dioksidin havaya geçtiği yapı hangisidir?", o:["Alveol","Gırtlak","Soluk borusu","Bronş"], a:0,
     w:"Alveoller bronşçukların uçlarındaki hava keseleridir ve gaz alışverişi burada gerçekleşir. Gırtlak, soluk borusu ve bronş havanın geçtiği yollardır, gaz alışverişi onlarda olmaz."}
  ]);
  H7.fen = (H7.fen || []).concat([
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Nefes alırken göğüs boşluğunun genişlemesini sağlayan olay hangisidir?", o:["Diyaframın kasılıp düzleşmesi","Diyaframın gevşeyip kubbeleşmesi","Kaburga arası kasların gevşemesi","Karın boşluğunun genişlemesi"], a:0,
     w:"Soluk alırken diyafram kasılıp düzleşir, kaburga arası kaslar da kasılır. Göğüs boşluğu genişler, karın boşluğu daralır ve akciğerlere hava dolar."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Büyük kan dolaşımında kan kalbin hangi tarafından çıkar ve hangi tarafına döner?", o:["Sağ taraftan çıkar, sol tarafa döner.","Sol taraftan çıkar, sağ tarafa döner.","Sol taraftan çıkar, yine sol tarafa döner.","Sağ taraftan çıkar, yine sağ tarafa döner."], a:1,
     w:"Büyük dolaşımda oksijence zengin kan kalbin sol tarafından atardamarla vücuda gönderilir. Hücrelerde oksijenini bırakan kan toplardamarlarla kalbin sağ tarafına döner."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Pankreasın ürettiği pankreas öz suyu ile ilgili hangisi doğrudur?", o:["Safra kesesinde biriktirilir.","Kimyasal sindirime yardım eder.","Yalnızca yağların sindirimine etki eder.","Kalın bağırsakta etkisini gösterir."], a:1,
     w:"Pankreas öz suyu bir kanalla ince bağırsağa gönderilir ve karbohidrat, protein ve yağların kimyasal sindirimine yardım eder."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Kan bağışı ile ilgili aşağıdakilerden hangisi YANLIŞTIR?", o:["Gönüllü ve sağlıklı kişilerce yapılır.","Toplumsal dayanışmayı güçlendirir.","Ülkemizde yalnızca Türk Kızılaya yapılabilir.","Ameliyat olan hastaların hayatını kurtarabilir."], a:2,
     w:"Kan bağışı için Türk Kızılay kan merkezlerine ya da hastanelerdeki ilgili birimlere başvurulabilir. Bağış gönüllü ve sağlıklı kişilerce yapılır, hayat kurtarır ve dayanışmayı güçlendirir."},
    {u:"ÜNİTE 3 · Vücudumuzdaki Sistemler", q:"Burnun iç yüzeyindeki kılların solunumdaki görevi nedir?", o:["Havayı ısıtmak","Havayı nemlendirmek","Sesin oluşmasını sağlamak","Toz ve mikropları tutmak"], a:3,
     w:"Burundaki kıllar havadaki toz ve mikropları tutarak havayı temizler. Havayı mukus nemlendirir, kılcal damarlar ısıtır. Ses ise gırtlaktaki ses tellerinde oluşur."}
  ]);
  EKC7.fen = (EKC7.fen || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Görevini tamamlamış uydular, roket parçaları ve boş yakıt tankları Dünya'nın çevresinde kontrolsüz biçimde dolanmaya devam ediyor.\n\nAşağıdakilerden hangisi bu soruna yönelik uygun bir çözüm önerisidir?", o:["Eskiyen uyduları yörüngede bırakıp yenilerini göndermek","Uzay çöplerini yakalayıp Dünya'ya geri getirmek","Parçaları uzayda patlatıp daha küçük hâle getirmek","Tek kullanımlık roket sayısını artırmak"], a:1,
     w:"Ders kitabında önerilen çözümler arasında uzay çöplerini çeşitli sistemlerle yakalayıp Dünya'ya getirmek ve görevi biten uyduları kontrollü biçimde yörüngeden çıkarmak vardır. Parçaları küçültmek işe yaramaz, çünkü çok hızlı dolanan küçük parçalar da uzay araçlarına büyük zarar verebilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Can ve Ali özdeş kutuları eşit büyüklükte kuvvetle, kuvvet doğrultusunda itiyor. Can kutusunu 4 m, Ali ise 2 m ilerletiyor.\n\nBuna göre ikisinin yaptığı işler için hangisi doğrudur?", o:["Can'ın yaptığı iş Ali'ninkinin iki katıdır.","Can'ın yaptığı iş Ali'ninkinin yarısıdır.","İkisinin yaptığı iş eşittir, çünkü kuvvetler eşittir.","İkisi de iş yapmamıştır, çünkü kutular sonunda durmuştur."], a:0,
     w:"Fiziksel anlamda iş, uygulanan kuvvetle ve kuvvet doğrultusunda alınan yolla doğru orantılıdır. Kuvvetler eşit, Can'ın aldığı yol Ali'ninkinin iki katı olduğundan yaptığı iş de iki katıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki durumların hangisinde fiziksel anlamda iş yapılmıştır?", o:["Halteri başının üstünde hareketsiz tutan sporcu","Sırt çantasıyla yatay yolda yürüyen öğrenci","Yerdeki kutuyu kaldırıp masaya koyan işçi","Duvarı itip yerinden oynatamayan çocuk"], a:2,
     w:"Kutuyu yukarı kaldıran işçi, kuvvet uyguladığı doğrultuda kutuyu hareket ettirdiği için iş yapmıştır. Halteri tutan sporcuda ve duvarı iten çocukta yer değiştirme yoktur. Çantayla yatay yürüyen öğrencide ise kuvvet yukarı, hareket yatay olduğundan iş yapılmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aynı yolda eşit hızla giden bir kamyon ile bir otomobilin kinetik enerjileri için hangisi doğrudur?", o:["Otomobilinki daha büyüktür, çünkü daha hafiftir.","Kamyonunki daha büyüktür, çünkü kütlesi daha büyüktür.","İkisininki eşittir, çünkü hızları eşittir.","İkisinin de kinetik enerjisi yoktur, çünkü hızları sabittir."], a:1,
     w:"Kinetik enerji kütle ve hızla doğru orantılıdır. Hızları eşit olduğunda kütlesi büyük olan kamyonun kinetik enerjisi daha büyüktür. Sabit hızla da olsa hareket eden her cismin kinetik enerjisi vardır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aynı yükseklikteki iki dalda ağırlıkları 2 N ve 1 N olan iki elma asılı duruyor.\n\nElmaların çekim potansiyel enerjileri için hangisi doğrudur?", o:["2 N'luk elmanınki daha büyüktür.","1 N'luk elmanınki daha büyüktür.","Yükseklikleri aynı olduğu için eşittir.","Hareketsiz oldukları için ikisininki de sıfırdır."], a:0,
     w:"Çekim potansiyel enerjisi ağırlığa ve yüksekliğe bağlıdır. Yükseklikler eşit olduğundan ağırlığı büyük olan 2 N'luk elmanın enerjisi daha büyüktür. Hareketsiz olmak kinetik enerjiyi sıfır yapar, çekim potansiyel enerjisini değil."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir okçu yayını gerip oku dikey olarak yukarı doğru bırakıyor. Ok, yaydan çıktıktan sonra yükseldikçe yavaşlıyor ve en yüksek noktada bir an duruyor.\n\nGerilmiş yayın bırakıldığı andan okun en yüksek noktaya ulaştığı ana kadar gerçekleşen enerji dönüşümlerinin sırası hangisidir? (Hava direnci önemsizdir.)", o:["Çekim potansiyel → kinetik → esneklik potansiyel","Kinetik → esneklik potansiyel → çekim potansiyel","Esneklik potansiyel → çekim potansiyel → kinetik","Esneklik potansiyel → kinetik → çekim potansiyel"], a:3,
     w:"Gerilen yayda depolanan esneklik potansiyel enerjisi, yay bırakılınca okun kinetik enerjisine dönüşür. Ok yükseldikçe yavaşlar, kinetik enerjisi çekim potansiyel enerjisine dönüşür ve en yüksek noktada bir an durur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hızla giden bir bisikletli frene basıyor ve bisiklet bir süre sonra duruyor.\n\nBisikletin hareket enerjisi ile ilgili doğru açıklama hangisidir?", o:["Hareket enerjisi tekerleklerde esneklik enerjisi olarak saklanmıştır.","Hareket enerjisi frene basıldığı anda tamamen yok olmuştur.","Hareket enerjisi sürtünmeyle ısı ve ses enerjisine dönüşmüştür.","Hareket enerjisi tamamen çekim potansiyel enerjisine dönüşmüştür."], a:2,
     w:"Frenlerde ve tekerlekle yol arasında oluşan sürtünme, hareket enerjisini ısı ve ses enerjisine dönüştürür. Bisiklet bu yüzden yavaşlayıp durur, frenler de ısınır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sürtünmenin önemsiz olduğu bir sarkaçta topuz X noktasından serbest bırakılıyor. Topuz en alçak Y noktasından geçip karşı taraftaki en yüksek Z noktasına çıkıyor.\n\nBuna göre aşağıdakilerden hangisi doğrudur?", o:["Y noktasında kinetik enerji en büyüktür.","X noktasında kinetik enerji en büyüktür.","Z noktası X noktasından daha yüksektedir.","Z noktasında potansiyel enerji sıfırdır."], a:0,
     w:"Topuz alçaldıkça potansiyel enerjisi kinetik enerjiye dönüşür, bu yüzden en alçak Y noktasında hızı ve kinetik enerjisi en büyüktür. X noktasında hızı sıfırdır. Sürtünme olmadığı için Z noktası X ile aynı yüksekliktedir ve burada potansiyel enerji en büyüktür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sürtünmenin önemsiz olduğu bir rampanın tepesinde duran oyuncak arabanın potansiyel enerjisi 40 J'dür. Araba serbest bırakıldıktan sonra rampadan inerken bir noktada potansiyel enerjisi 15 J oluyor.\n\nBu noktada arabanın kinetik enerjisi kaç J'dür?", o:["15","25","40","55"], a:1,
     w:"Tepede duran arabanın kinetik enerjisi yoktur, 40 J'lük enerjinin tamamı potansiyeldir. Potansiyel enerji 15 J'e düştüğünde aradaki 40 − 15 = 25 J kinetik enerjiye dönüşmüştür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki olay–enerji dönüşümü eşleştirmelerinden hangisi YANLIŞTIR?", o:["Rüzgârla dönen türbin: kinetik → elektrik","Barajdan düşen su: potansiyel → kinetik","Çalışan ütü: elektrik → ısı","Yanan lamba: ışık → elektrik"], a:3,
     w:"Yanan lambada elektrik enerjisi ışık ve ısı enerjisine dönüşür, bu eşleştirmede dönüşümün yönü ters yazılmıştır. Türbinde rüzgârın hareket enerjisi elektriğe, düşen suda potansiyel enerji kinetik enerjiye, ütüde elektrik enerjisi ısıya dönüşür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sürtünmenin önemsiz olduğu sarkaç, zıplayan top ve eğik düzlemde kayan araba deneylerinde potansiyel ve kinetik enerjinin birbirine dönüştüğü gözleniyor.\n\nBu gözlemlerden yapılabilecek en uygun genelleme hangisidir?", o:["Toplam enerji korunur, yalnızca tür değiştirir.","Hareket eden cisimlerin enerjisi zamanla yok olur.","Potansiyel enerji her zaman kinetik enerjiden büyüktür.","Cisimler yalnızca hareket ederken enerjiye sahiptir."], a:0,
     w:"Deneylerin hepsinde enerjinin bir türü azalırken diğeri aynı miktarda artar. Buradan enerjinin yoktan var olmadığı, var olan enerjinin de yok olmayıp başka bir türe dönüştüğü sonucuna varılır. Buna enerjinin korunumu kanunu denir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki organ–görev eşleştirmelerinden hangisi YANLIŞTIR?", o:["Ağız – besinlerin vücuda alındığı ilk organ","Yemek borusu – besini kas hareketleriyle mideye iletme","Yutak – proteinlerin kimyasal sindirimini başlatma","Mide – besini bulamaç hâline getirip ince bağırsağa gönderme"], a:2,
     w:"Yutakta sindirim gerçekleşmez, yutak besini ağızdan yemek borusuna iletir. Diğer eşleştirmelerdeki görevler doğrudur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir öğrenci sindirim sistemi modelinde ince bağırsağın iç yüzeyini düz bir kâğıt yerine girintili çıkıntılı bir kumaşla kaplıyor.\n\nÖğrenci bu tercihle ince bağırsağın hangi özelliğini göstermek istemiştir?", o:["Villusların emilim alanını genişletmesi","Safranın yağların sindirimine yardım etmesi","Sindirilmeyen artıkların burada depolanması","Pankreas öz suyunun buraya dökülmesi"], a:0,
     w:"Villuslar ince bağırsağın iç yüzeyini genişleterek emilimi hızlandırır. Girintili çıkıntılı kumaş bu yapıyı temsil eder."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi kimyasal sindirime örnektir?", o:["Dişlerin elmayı küçük parçalara ayırması","Mide öz suyunun proteinleri parçalaması","Safranın yağları küçük parçalara ayırması","Midenin kasılıp gevşeyerek besini ezmesi"], a:1,
     w:"Mide öz suyundaki enzimler proteinleri yapı taşlarına ayırır, bu kimyasal sindirimdir. Dişlerle parçalama, midenin kasılıp gevşemesi ve safranın yağlara etkisi ise fiziksel sindirimdir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Karaciğer ve pankreas için aşağıdakilerden hangisi ortak bir özelliktir?", o:["Besinler içlerinden geçerek ilerler.","Salgıları ince bağırsağa gelir.","Proteinlerin sindirimini başlatırlar.","Salgıları yalnızca yağlara etki eder."], a:1,
     w:"Karaciğerin safrası da pankreasın öz suyu da kanallarla ince bağırsağa gelir. Bu iki organ sindirime yardım eder ama besin içlerinden geçmez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kalın bağırsak ile ilgili aşağıdakilerden hangisi doğrudur?", o:["Besinlerin kimyasal sindirimi burada tamamlanır.","Safra sıvısı bu organa dökülür.","Su ile bazı mineral ve vitaminler burada emilir.","Proteinlerin fiziksel sindirimi burada başlar."], a:2,
     w:"Kalın bağırsakta sindirim olmaz. Sindirilmeyen artıklar burada bir süre bekler, geriye kalan su ile bazı mineral ve vitaminler emilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif, “Ağızda yalnızca fiziksel sindirim olur.” diyor.\n\nAşağıdaki gözlemlerden hangisi Elif'in bu görüşünün yanlış olduğunu gösterir?", o:["Elmanın dişlerle küçük parçalara ayrılması","Lokmanın yutulunca yemek borusuna geçmesi","Ekmeğin uzun süre çiğnenince tatlanması","Sıcak çorbanın dili yakması"], a:2,
     w:"Uzun süre çiğnenen ekmeğin tatlanması, tükürükteki enzimlerin ekmekteki karbohidratı parçaladığını gösterir. Bu kimyasal sindirimdir. Dişlerle parçalama fiziksel sindirimdir, yutma ise yalnızca iletimdir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Küçük kan dolaşımında kanın izlediği yol hangisidir?", o:["Kalbin sol tarafı → vücut → kalbin sağ tarafı","Kalbin sağ tarafı → vücut → kalbin sol tarafı","Kalbin sol tarafı → akciğerler → kalbin sağ tarafı","Kalbin sağ tarafı → akciğerler → kalbin sol tarafı"], a:3,
     w:"Küçük kan dolaşımında oksijeni az olan kan kalbin sağ tarafından akciğerlere gider. Orada oksijen alıp karbon dioksit bırakır ve kalbin sol tarafına döner."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Dolaşım sistemiyle ilgili aşağıdaki ifadelerden hangisi doğrudur?", o:["Kalp yalnızca oksijence zengin kanı vücuda pompalar.","Atardamarlar kanı vücuttan kalbe getirir.","Kılcal damarlar atardamarla toplardamarı bağlar.","Dolaşım sistemi yalnızca kalp ve kandan oluşur."], a:2,
     w:"Kılcal damarlar atardamarları toplardamarlara bağlar. Kalp hem oksijence zengin hem oksijence fakir kanı pompalar, kanı kalbe getiren damarlar toplardamarlardır ve dolaşım sisteminde damarlar da bulunur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hastalanan bir kişinin kanında sayısı artan ve vücudu mikroplara karşı savunan yapı hangisidir?", o:["Alyuvar","Plazma","Kan pulcukları","Akyuvar"], a:3,
     w:"Akyuvarlar beyaz kan hücreleridir, vücudu mikroplara karşı savunur ve hastalıkta sayıları artar. Alyuvar gaz taşır, kan pulcukları pıhtılaşmayı sağlar, plazma ise kanın sıvı kısmıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Nabız ile ilgili aşağıdakilerden hangisi doğrudur?", o:["Toplardamar duvarındaki basıncın parmakla hissedilmesidir.","Kanın atardamar duvarına yaptığı basıncın hissedilmesidir.","Dinlenen bir yetişkinde dakikada 150–200 kez atar.","Koşarken yavaşlar, dinlenirken hızlanır."], a:1,
     w:"Kalp kasılıp gevşedikçe kanın atardamar duvarına yaptığı basınç, el bileği gibi yerlerde parmakla nabız olarak hissedilir. Dinlenen bir yetişkinde nabız genellikle dakikada 60–100 arasındadır ve sporda artar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kan bağışının toplumsal dayanışma açısından önemini en iyi açıklayan ifade hangisidir?", o:["Bağışçının kendi kan grubunu öğrenmesini sağlar.","Hayat kurtarır ve toplumda yardımlaşmayı güçlendirir.","Hastanelerdeki ilaç ihtiyacını tamamen ortadan kaldırır.","Bağışçının kan hücrelerinin hızla çoğalmasını sağlar."], a:1,
     w:"Ameliyatlar, kronik rahatsızlıklar ve kan hastalıkları nedeniyle birçok kişi kana ihtiyaç duyar. Düzenli bağış bu ihtiyacı karşılayarak hayat kurtarır ve insanlar arasında yardımlaşma ile dayanışmayı güçlendirir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi kan bağışı yapabilmek için aranan şartlardan biri DEĞİLDİR?", o:["18–65 yaş aralığında olmak","50 kilogramın üzerinde olmak","Önemli bir sağlık sorunu olmamak","Belirli bir kan grubundan olmak"], a:3,
     w:"Kan bağışı için 18–65 yaş arasında, 50 kg'ın üzerinde ve önemli bir sağlık sorunu olmayan biri olmak gerekir. Kan grubuyla ilgili böyle bir şart yoktur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hem sindirim hem de solunum sisteminde yer alan yapı hangisidir?", o:["Gırtlak","Yemek borusu","Soluk borusu","Yutak"], a:3,
     w:"Yutak, ağız ve burun boşluklarının arkasında soluk borusu ile yemek borusunu birleştirir. Besin buradan yemek borusuna, hava ise gırtlağa geçer."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Soluk verme sırasında aşağıdakilerden hangisi gerçekleşir?", o:["Diyafram kasılarak düzleşir.","Kaburga arası kaslar kasılır.","Göğüs boşluğu daralır.","Akciğerlerin hacmi artar."], a:2,
     w:"Soluk vermede diyafram gevşeyip kubbeleşir, kaburga arası kaslar gevşer. Göğüs boşluğu daralır, akciğerlerin hacmi azalır ve hava dışarı atılır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Solunum sistemi bir ağaca benzetiliyor. Bu benzetmede ağacın gövdesi soluk borusuna, dalları ise bronşlara karşılık geliyor.\n\nAğacın yapraklarına karşılık gelen yapı hangisidir?", o:["Alveol","Gırtlak","Diyafram","Burun"], a:0,
     w:"Bronşlar akciğer içinde bronşçuklara ayrılır, bronşçukların uçlarında da alveoller bulunur. Ağacın en uç kısmındaki yapraklar bu yüzden alveollere benzetilir."}
  ]);

  /* ---------- 7. sınıf · İngilizce ---------- */
  Q7.ing = (Q7.ing || []).concat([
    {u:"UNIT 4 · Wild Animals", q:"Pandas ____ in the mountains of China. They eat bamboo.", o:["lives","live","is living","are live"], a:1,
     w:"Pandas çoğul bir öznedir (they). Genel bir doğruyu anlatırken çoğul özneyle fiil yalın kalır: Pandas live. Fiile -s yalnız tekil özneyle eklenir."},
    {u:"UNIT 4 · Wild Animals", q:"A cheetah ____ run very fast, so it catches its prey easily.", o:["is","can't","can","are"], a:2,
     w:"Yetenek can ile anlatılır, ardından fiil yalın gelir: can run. Cümlenin sonu (so it catches its prey easily) hızlı koşabildiğini gösterdiği için can't uymaz."},
    {u:"UNIT 4 · Wild Animals", q:"This animal lives in the desert. It has got one or two humps, and it can live without water for many days. What is it?", o:["a camel","a penguin","a dolphin","a gorilla"], a:0,
     w:"Çölde yaşayan, bir ya da iki hörgücü (hump) olan ve günlerce susuz kalabilen hayvan devedir: camel."},
    {u:"UNIT 4 · Wild Animals", q:"This bird can't fly, but it can swim very well. It lives in Antarctica and eats fish. What is it?", o:["an eagle","a parrot","an owl","a penguin"], a:3,
     w:"Uçamayan ama çok iyi yüzen, Antarktika'da yaşayan kuş penguendir: penguin. Kartal, papağan ve baykuş uçabilen kuşlardır."},
    {u:"UNIT 4 · Wild Animals", q:"A hundred years ago, there ____ many tigers in the forests of Asia. Today there are only a few thousand.", o:["is","was","are","were"], a:3,
     w:"A hundred years ago geçmişi gösterir. Many tigers çoğul olduğu için geçmişte there were kullanılır, there was ise tekil isimle gelir."},
    {u:"UNIT 4 · Wild Animals", q:"Orangutans are in danger ____ people cut down the rainforests.", o:["because","so","but","or"], a:0,
     w:"Boşluktan sonraki kısım (insanların yağmur ormanlarını kesmesi) tehlikenin nedenidir. Neden because ile bağlanır."},
    {u:"UNIT 4 · Wild Animals", q:"The dodo couldn't fly and sailors hunted it, ____ there are no dodos in the world today.", o:["but","so","because","or"], a:1,
     w:"Boşluktan sonraki kısım (bugün hiç dodo kalmaması) önceki olayların sonucudur. Sonuç so ile bağlanır. Couldn't fly, uçamıyordu demektir."},
    {u:"UNIT 4 · Wild Animals", q:"Hunters kill elephants for their tusks. People ____ buy things made of ivory.", o:["should","can","shouldn't","must"], a:2,
     w:"Fildişi için filler öldürüldüğüne göre fildişinden yapılmış eşya alınmamalıdır: shouldn't buy. Bu kalıpta fiil yalın gelir."},
    {u:"UNIT 4 · Wild Animals", q:"There are no dinosaurs on Earth today. They all died millions of years ago. Dinosaurs are ____.", o:["endangered","extinct","dangerous","protected"], a:1,
     w:"Bugün hiç yaşamayan, nesli tamamen tükenmiş canlılar için extinct kullanılır. Endangered ise hâlâ yaşayan ama sayısı çok azalmış türleri anlatır."},
    {u:"UNIT 4 · Wild Animals", q:"Read the text.\n\nSnow leopards live in the high mountains of Central Asia. They have got thick grey fur with dark spots. Hunters kill them for their beautiful fur, so there aren't many snow leopards today.\n\nAccording to the text, why are snow leopards in danger?", o:["Because they live in high mountains.","Because they have got dark spots.","Because people hunt them for their fur.","Because they can't find any water."], a:2,
     w:"Metindeki neden cümlesi: Hunters kill them for their beautiful fur. Cevapta aynı bilgi başka sözcüklerle verilmiş. Dağlarda yaşamak ve benekli olmak tehlike nedeni değildir."},
    {u:"UNIT 5 · Television", q:"A presenter chats with famous guests about their lives in this programme. What kind of programme is it?", o:["a talk show","a cartoon","a weather forecast","a sitcom"], a:0,
     w:"Bir sunucunun ünlü konuklarla hayatları hakkında sohbet ettiği program talk show, yani sohbet programıdır."},
    {u:"UNIT 5 · Television", q:"This programme shows real facts about nature, animals or history. What kind of programme is it?", o:["a sitcom","a soap opera","a talent show","a documentary"], a:3,
     w:"Doğa, hayvanlar ya da tarih hakkında gerçek bilgiler veren program belgeseldir: documentary."},
    {u:"UNIT 5 · Television", q:"My brother prefers sports programmes ____ soap operas.", o:["than","from","to","with"], a:2,
     w:"Prefer A to B kalıbında tercih edilen şey ile öteki to ile bağlanır. Than yalnız -er ya da more ile kurulan karşılaştırmada kullanılır."},
    {u:"UNIT 5 · Television", q:"The news ____ on at eight o'clock every evening.", o:["are","is","do","have"], a:1,
     w:"The news sonu -s ile bitse de tekil sayılır, bu yüzden fiil is olur."},
    {u:"UNIT 5 · Television", q:"What time ____ the quiz show start? – At quarter past eight.", o:["is","do","are","does"], a:3,
     w:"Start bir fiildir. Geniş zaman sorusunda tekil özneyle (the quiz show) does kullanılır, start yalın kalır."},
    {u:"UNIT 5 · Television", q:"TV GUIDE · SUNDAY\n18:00 Animal Friends (cartoon)\n19:00 The News\n19:30 Weather Forecast\n19:45 Brain Box (quiz show)\n21:00 Star Voices (talent show)\n\nWhat time does the weather forecast start?", o:["At seven o'clock.","At half past seven.","At quarter to eight.","At nine o'clock."], a:1,
     w:"Rehberde hava durumunun yanında 19:30 yazıyor. 19:30 İngilizcede half past seven (yedi buçuk) diye söylenir."},
    {u:"UNIT 5 · Television", q:"My grandfather ____ watches the news. He watches it every evening at eight.", o:["always","never","rarely","sometimes"], a:0,
     w:"Her akşam izliyorsa her zaman izliyordur: always. Sıklık zarfı fiilden önce gelir."},
    {u:"UNIT 5 · Television", q:"Last night we ____ a very funny sitcom on TV.", o:["watch","watches","watched","are watching"], a:2,
     w:"Last night geçmişi gösterir. Düzenli fiiller geçmişte -ed alır."},
    {u:"UNIT 5 · Television", q:"____ you watch the talent show final yesterday? – Yes, I did.", o:["Do","Were","Are","Did"], a:3,
     w:"Yesterday ve cevaptaki “Yes, I did.” geçmiş zaman sorusunu gösterir: Did + özne + yalın fiil."},
    {u:"UNIT 5 · Television", q:"Read the text.\n\nI'm Deniz. I watch TV for an hour every evening. I love cartoons because they are funny. My sister loves documentaries because she wants to learn about science.\n\nWhy does Deniz love cartoons?", o:["Because they are funny.","Because they are informative.","Because they are about science.","Because they are on every evening."], a:0,
     w:"Metinde: I love cartoons because they are funny. Bilim öğrenmek istediği için belgeselleri seçen kişi Deniz'in kız kardeşidir."}
  ]);
  H7.ing = (H7.ing || []).concat([
    {u:"UNIT 4 · Wild Animals", q:"Which animals live on the African savannah?", o:["lions and zebras","penguins and seals","whales and sharks","pandas and koalas"], a:0,
     w:"Afrika savanı aslan, zebra, zürafa ve fil gibi hayvanların yaşam alanıdır. Penguen ve fok kutuplarda, balina ve köpek balığı okyanusta yaşar."},
    {u:"UNIT 4 · Wild Animals", q:"A ____ is an animal that hunts and eats other animals.", o:["prey","mammal","predator","herbivore"], a:2,
     w:"Başka hayvanları avlayıp yiyen hayvana predator (yırtıcı) denir. Prey avlanan hayvan, herbivore otçul hayvan, mammal memelidir."},
    {u:"UNIT 4 · Wild Animals", q:"Kangaroos ____ fly, but they can jump very far.", o:["can","isn't","doesn't","can't"], a:3,
     w:"But zıtlık bildirir: Uçamazlar ama çok uzağa zıplayabilirler. Kangaroos çoğul olduğu için doesn't uymaz, isn't de fiilin önünde bu anlamı vermez."},
    {u:"UNIT 4 · Wild Animals", q:"Ten years ago, this forest was very big. Today it ____ small because people cut down the trees.", o:["was","is","were","are"], a:1,
     w:"Today bugünü gösterir. Forest (it) tekil olduğu için geniş zamanda is kullanılır."},
    {u:"UNIT 4 · Wild Animals", q:"Read the text.\n\nThe brown bear lives in the forests of Turkey. In autumn, it eats a lot of fruit and nuts. In winter, it sleeps in a cave for months.\n\nWhat does the brown bear do in winter?", o:["It sleeps in a cave.","It eats a lot of fruit.","It hunts fish in rivers.","It looks for food in the snow."], a:0,
     w:"Metne göre ayı kışın aylarca mağarada uyur; buna kış uykusu denir. Çok meyve yemek sonbaharda yaptığı iştir; balık avlamak ve karda yiyecek aramak metinde geçmiyor."},
    {u:"UNIT 5 · Television", q:"The same characters are in every episode of this funny series. What kind of programme is it?", o:["a documentary","the news","a weather forecast","a sitcom"], a:3,
     w:"Her bölümünde aynı karakterlerin olduğu komik dizi sitcom'dur (durum komedisi)."},
    {u:"UNIT 5 · Television", q:"You use it to change the channel or turn the TV on and off. What is it?", o:["an episode","a channel","a remote control","an advert"], a:2,
     w:"Kanal değiştirmeye, televizyonu açıp kapatmaya yarayan alet kumandadır: remote control."},
    {u:"UNIT 5 · Television", q:"My sister can't stand soap operas. She ____ them.", o:["loves","hates","enjoys","prefers"], a:1,
     w:"Can't stand hiç dayanamamak, nefret etmek demektir. Bu yüzden hates uygun, loves ve enjoys ise sevmek anlamındadır."},
    {u:"UNIT 5 · Television", q:"Last Saturday, the jury ____ a young dancer from Sivas as the winner.", o:["choose","chooses","choosed","chose"], a:3,
     w:"Choose düzensiz bir fiildir: choose → chose. Last Saturday geçmişi gösterir."},
    {u:"UNIT 5 · Television", q:"What kind of programmes ____ your brother like? – He likes sports programmes.", o:["does","do","is","did"], a:0,
     w:"Your brother tekil (he) olduğu için geniş zaman sorusunda does kullanılır. Cevaptaki likes de geniş zamanı gösterir."}
  ]);
  EKC7.ing = (EKC7.ing || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Read about Elif.\n\nElif is my best friend. She is tall and slim, and she has got long curly hair. She never gets angry, and she waits calmly for her turn.\n\nWhat is Elif like?", o:["She is lazy.","She is patient.","She is rude.","She is impatient."], a:1,
     w:"What is she like? kişiliği sorar. Hiç kızmayan, sırasını sakince bekleyen biri sabırlıdır: patient. Impatient bunun tersidir; metinde tembellik (lazy) ya da kabalık (rude) anlatılmıyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read about Burak.\n\nBurak is a young tennis player. He plays tennis every day after school. He goes swimming on Tuesdays and Thursdays. He does yoga only on Sundays. He never plays computer games before a match.\n\nWhich sentence about Burak is correct?", o:["He goes swimming every day.","He does yoga twice a week.","He plays tennis only at weekends.","He goes swimming twice a week."], a:3,
     w:"Salı ve perşembe iki gündür: twice a week. Metne göre tenisi her gün oynar, yogayı yalnız pazar günü yapar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"MARIE CURIE\nMarie Curie was born in Warsaw, Poland, in 1867. In 1891, she moved to Paris and studied physics and maths at university. In 1895, she married Pierre Curie, a French scientist. They worked together, and in 1903 they won the Nobel Prize in Physics. In 1911, Marie won her second Nobel Prize, this time in Chemistry. She died in 1934.\n\nWhen was Marie Curie born?", o:["In 1867.","In 1891.","In 1903.","In 1934."], a:0,
     w:"When tarih sorar. Doğum bilgisi ilk cümlede: was born in Warsaw, Poland, in 1867. Metindeki öteki yıllar başka olaylara aittir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"MARIE CURIE\nMarie Curie was born in Warsaw, Poland, in 1867. In 1891, she moved to Paris and studied physics and maths at university. In 1895, she married Pierre Curie, a French scientist. They worked together, and in 1903 they won the Nobel Prize in Physics. In 1911, Marie won her second Nobel Prize, this time in Chemistry. She died in 1934.\n\nWhat did she do in 1891?", o:["She won a Nobel Prize.","She married a scientist.","She moved to Paris.","She was born in Warsaw."], a:2,
     w:"Metinde o yılla başlayan cümleyi bul: In 1891, she moved to Paris… Soruda yıl verildiyse cevap o yılın geçtiği cümlededir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"MARIE CURIE\nMarie Curie was born in Warsaw, Poland, in 1867. In 1891, she moved to Paris and studied physics and maths at university. In 1895, she married Pierre Curie, a French scientist. They worked together, and in 1903 they won the Nobel Prize in Physics. In 1911, Marie won her second Nobel Prize, this time in Chemistry. She died in 1934.\n\nWho was Pierre Curie?", o:["A Polish scientist.","A French writer.","A Polish teacher.","A French scientist."], a:3,
     w:"Metinde: she married Pierre Curie, a French scientist. Addan sonraki virgüllü açıklama kişinin kim olduğunu söyler. Polonyalı olan Marie'dir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"MARIE CURIE\nMarie Curie was born in Warsaw, Poland, in 1867. In 1891, she moved to Paris and studied physics and maths at university. In 1895, she married Pierre Curie, a French scientist. They worked together, and in 1903 they won the Nobel Prize in Physics. In 1911, Marie won her second Nobel Prize, this time in Chemistry. She died in 1934.\n\nWhen did Marie win her second Nobel Prize?", o:["In 1903.","In 1911.","In 1895.","In 1934."], a:1,
     w:"Second (ikinci) sözcüğünün geçtiği cümle: In 1911, Marie won her second Nobel Prize, this time in Chemistry. İlk ödülü Pierre ile birlikte kazanmıştı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read the text.\n\nLeyla Aksoy writes books for children. She grew up in Çanakkale. She wrote her first story at the age of nine. She studied Turkish literature at university in İzmir. In 2018, her third book won a prize.\n\nHow old was Leyla when she wrote her first story?", o:["She was nine.","She was six.","She was eighteen.","She was twenty."], a:0,
     w:"At the age of nine, when she was nine demektir: dokuz yaşındayken. Metindeki 2018 ödülün yılıdır, yaşı vermez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"NOTES · OZAN TEKİN (wildlife photographer)\n1988: born in Artvin\n1999: got his first camera\n2010: graduated from university\n2014: took photos of bears in the Kaçkar Mountains\n2019: won an international photo prize\n\nWhich sentence is correct for Ozan's biography?", o:["He born in Artvin in 1988.","He is born in Artvin in 1988.","He was born in Artvin in 1988.","He was born in Artvin on 1988."], a:2,
     w:"Doğum bilgisi was born ile yazılır ve yılın önüne in gelir. Born tek başına fiil olmaz, is born da geçmişteki doğumu anlatmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"NOTES · OZAN TEKİN (wildlife photographer)\n1988: born in Artvin\n1999: got his first camera\n2010: graduated from university\n2014: took photos of bears in the Kaçkar Mountains\n2019: won an international photo prize\n\nWhich sentence is correct according to the notes?", o:["He got his first camera in 2010.","He took photos of bears in 2014.","He won a photo prize in 1999.","He took photos of bears in 2019."], a:1,
     w:"Notlarda ayılar 2014 satırında geçiyor. Rapor yazarken her olayı kendi yılıyla eşleştir. Take düzensizdir, geçmişte took olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Put the sentences in order to make a short biography.\n\n1) In 2008, she became a doctor.\n2) Nur Demir was born in Sinop in 1980.\n3) Now she works at a children's hospital in Ankara.\n4) After high school, she studied medicine at university.\n\nWhich order is correct?", o:["4 – 2 – 1 – 3","2 – 1 – 4 – 3","1 – 2 – 4 – 3","2 – 4 – 1 – 3"], a:3,
     w:"Biyografi doğumla başlar (2), sonra okul (4), meslek (1) ve bugünkü durum (3) gelir. Bugünü anlatan 3. cümle Simple Present'tir, en sona yazılır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Complete the report.\n\nTarık loved football, but he ____ become a professional player. He became a sports teacher in 2012.", o:["didn't","doesn't","wasn't","isn't"], a:0,
     w:"Geçmişteki bir olayın olumsuzu didn't + yalın fiil ile yazılır: didn't become. Doesn't geniş zamandır, wasn't ve isn't ise yalın fiille kullanılmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"GIANT PANDAS: THEN AND NOW\nIn the 1980s, there were only about 1,100 giant pandas in the wild. People cut down the bamboo forests, so many pandas lost their homes and their food. Then China opened lots of nature reserves for pandas. Today there are more than 1,800 pandas in the wild.\n\nWhy did many pandas lose their homes?", o:["Because China opened nature reserves.","Because people hunted them in the forests.","Because people cut down the forests.","Because they didn't like bamboo."], a:2,
     w:"Metinde: People cut down the bamboo forests, so many pandas lost their homes… Pandalar, bambu ormanları kesildiği için yuvalarını ve yiyeceklerini kaybetti."},
    {u:"EK · 2. Yazılı Hazırlık", q:"GIANT PANDAS: THEN AND NOW\nIn the 1980s, there were only about 1,100 giant pandas in the wild. People cut down the bamboo forests, so many pandas lost their homes and their food. Then China opened lots of nature reserves for pandas. Today there are more than 1,800 pandas in the wild.\n\nWhich sentence is true according to the text?", o:["In the 1980s, there were more than 1,800 pandas in the wild.","Today there are more pandas in the wild than in the 1980s.","Pandas lost their homes because of the nature reserves.","Today there aren't any giant pandas in the wild."], a:1,
     w:"1980'lerde doğada yaklaşık 1.100 panda vardı, bugün 1.800'den fazla var. Yani sayı arttı. Koruma alanları pandalara yardım etmek için açıldı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"SEA TURTLES IN DALYAN\nEvery summer, sea turtles come to İztuzu Beach in Dalyan. They lay their eggs in the sand at night. Many years ago, people wanted to build a big hotel on this beach. Nature lovers didn't want it because the turtles needed a quiet beach. In the end, they didn't build the hotel, and the beach became a protected area. Today the beach is closed at night in summer, so the turtles can lay their eggs safely.\n\nWhy didn't nature lovers want the hotel?", o:["Because the hotel was too expensive.","Because the turtles came only in winter.","Because the beach needed more tourists.","Because the turtles needed a quiet beach."], a:3,
     w:"Metinde: Nature lovers didn't want it because the turtles needed a quiet beach. Kaplumbağaların yumurtlamak için sessiz bir kumsala ihtiyacı vardı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"SEA TURTLES IN DALYAN\nEvery summer, sea turtles come to İztuzu Beach in Dalyan. They lay their eggs in the sand at night. Many years ago, people wanted to build a big hotel on this beach. Nature lovers didn't want it because the turtles needed a quiet beach. In the end, they didn't build the hotel, and the beach became a protected area. Today the beach is closed at night in summer, so the turtles can lay their eggs safely.\n\nWhat is true about İztuzu Beach today?", o:["People can't go there at night in summer.","People can't go there during the day in summer.","There is a big new hotel on the sand now.","Turtles don't lay their eggs there anymore."], a:0,
     w:"Son cümleye göre kumsal yaz gecelerinde kapalıdır, böylece kaplumbağalar yumurtalarını güvenle bırakır. Gündüz kumsal açıktır ve kaplumbağalar her yaz gelmeye devam eder."},
    {u:"EK · 2. Yazılı Hazırlık", q:"OUR SAFARI\nLast summer, my family went on a safari in Kenya. On the first day, we saw a group of lions under a tree. Zebras and giraffes were near the river. In the evening, an elephant walked very close to our car!\n\nWhich animal is NOT in the text?", o:["zebra","giraffe","rhino","elephant"], a:2,
     w:"Metindeki hayvan adları lions, zebras, giraffes ve an elephant. Gergedan (rhino) metinde geçmiyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read and find the animal.\n\nThis bird can't fly, but it can run very fast. It lives in Africa, and it is the biggest bird in the world.", o:["an eagle","a parrot","an owl","an ostrich"], a:3,
     w:"Uçamayan ama çok hızlı koşan, Afrika'da yaşayan ve dünyanın en büyük kuşu olan hayvan devekuşudur: ostrich. Kartal, papağan ve baykuş uçabilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read and find the animal.\n\nIt lives in Australia. It has got strong back legs and a long tail, and it can jump very far. A mother carries her baby in a pouch.", o:["a kangaroo","a koala","a monkey","a cheetah"], a:0,
     w:"Avustralya'da yaşayan, güçlü arka bacakları ve uzun kuyruğuyla çok uzağa zıplayan, yavrusunu kesede taşıyan hayvan kangurudur. Koala da Avustralya'da yaşar ve kesesi vardır ama zıplamaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"FACT FILE · KOALA\nHome: forests in eastern Australia\nFood: eucalyptus leaves\nSleep: about 20 hours a day\nDanger: forest fires, people cut down trees\n\nWhich sentence is correct for a paragraph about koalas?", o:["Koalas sleeps about 20 hours a day.","Koalas are sleep about 20 hours a day.","Koalas sleep about 20 hours a day.","Koalas sleep about 20 hours a week."], a:2,
     w:"Koalas çoğul öznedir, fiil -s almaz. Bilgi kartında günde (a day) yaklaşık 20 saat yazıyor. Are ile sleep bu cümlede yan yana kullanılmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"FACT FILE · KOALA\nHome: forests in eastern Australia\nFood: eucalyptus leaves\nSleep: about 20 hours a day\nDanger: forest fires, people cut down trees\n\nWhich sentence gives the correct reason?", o:["They are in danger because they sleep about 20 hours.","They are in danger because people cut down their trees.","They are in danger, so people cut down their trees.","They are in danger, so they only eat eucalyptus leaves."], a:1,
     w:"Bilgi kartındaki Danger satırı nedeni verir ve neden because ile bağlanır. So sonucu bağladığı için anlamı ters çevirir, uyumak ve yaprak yemek de tehlike nedeni değildir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read the paragraph.\n\n(1) Camels live in the deserts of Africa and Asia. (2) They have got one or two humps. (3) Penguins can swim very well in cold water. (4) Camels can walk for many days without water.\n\nWhich sentence does NOT belong in the paragraph?", o:["Sentence 1","Sentence 2","Sentence 3","Sentence 4"], a:2,
     w:"Paragraf develeri anlatıyor. Penguenlerden söz eden 3. cümle konunun dışında kalıyor. Yaban hayatı yazısında bütün cümleler aynı hayvan hakkında olmalı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Complete the paragraph.\n\nCheetahs live on the savannahs of Africa. They have got yellow fur with black spots. They can run very fast. Today there aren't many cheetahs because farmers kill them and their habitat is getting smaller. We ____ protect them.", o:["shouldn't","doesn't","isn't","should"], a:3,
     w:"Paragraf çitaların neden azaldığını anlatıyor, son cümle bir öneri olmalı: We should protect them. Doesn't ve isn't, we öznesiyle bu cümlede kullanılamaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read the text.\n\nHi, I'm Ece. My family loves TV, but we like different programmes. My father always watches the news at 8 p.m. My mother prefers cooking shows to the news. My little brother watches cartoons every morning before school. I love quiz shows because I learn new things from them.\n\nWhy does Ece love quiz shows?", o:["Because they are funny.","Because they are educational.","Because they are on every morning.","Because her mother loves them."], a:1,
     w:"Ece bilgi yarışmalarından yeni şeyler öğrendiğini söylüyor (I learn new things). Öğretici programlar educational'dır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read the text.\n\nHi, I'm Ece. My family loves TV, but we like different programmes. My father always watches the news at 8 p.m. My mother prefers cooking shows to the news. My little brother watches cartoons every morning before school. I love quiz shows because I learn new things from them.\n\nWhich sentence about Ece's family is correct?", o:["Her brother watches cartoons every morning.","Her brother watches the news every morning.","Her mother prefers the news to cooking shows.","Her father watches cartoons every evening."], a:0,
     w:"Metinde: My little brother watches cartoons every morning before school. Haberleri akşam 8'de izleyen babasıdır, annesi ise yemek programlarını haberlere tercih eder."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Read the text.\n\nLast Saturday, I watched the final of a talent show with my grandparents. There were three finalists. A girl from Hatay sang a folk song. A boy from Rize danced the horon. Twins from Ankara did magic tricks. In the end, the jury chose the girl from Hatay. My grandmother cried because she was so happy.\n\nWho won the talent show?", o:["The boy from Rize.","The twins from Ankara.","The girl from Hatay.","The writer's grandmother."], a:2,
     w:"Metinde: In the end, the jury chose the girl from Hatay. Jüri sonunda Hataylı kızı seçti. Choose fiilinin geçmiş hâli chose'dur."}
  ]);

  /* ---------- 7. sınıf · Matematik ---------- */
  Q7.mat = (Q7.mat || []).concat([
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Eş küplerle kurulan bir yapının üstten görünümüne, her karede üst üste duran küp sayısı yazılmıştır (0 boş kare demektir). Üst satır yapının arka sırası, alt satır ön sırasıdır.\n\nArka sıra (soldan sağa): 3 1 2\nÖn sıra (soldan sağa): 1 2 0\n\nBu yapıya önden bakıldığında kaç kare görülür?", o:["5","6","7","9"], a:2,
     w:"Önden bakınca her sütunun yalnız en yüksek kulesi görünür: solda 3, ortada 2, sağda 2 küp. Önden görünümde 3 + 2 + 2 = 7 kare vardır."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Eş küplerle oluşturulan bir yapının önden görünümü ile arkadan görünümü arasındaki ilişki hangisidir?", o:["Dikey bir doğruya göre birbirinin simetriğidir","Yatay bir doğruya göre birbirinin simetriğidir","Her yapıda birbirinin tıpatıp aynısıdır","Aralarında hiçbir geometrik ilişki bulunmaz"], a:0,
     w:"Yapının arkasına geçince sağ ile sol yer değiştirir. Bu yüzden ön ve arka görünümler dikey bir doğruya göre simetriktir."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Dikdörtgenler prizmasının yüzey açınımıyla ilgili aşağıdakilerden hangisi YANLIŞTIR?", o:["Açınım, altı tane dikdörtgensel bölgeden oluşmaktadır","Aynı prizmanın birden fazla açınımı çizilebilir","Karşılıklı iki yüz, açınımda bir kenarı paylaşabilir","Karşılıklı yüzlerin alanları birbirine eşittir"], a:2,
     w:"Açınımda ortak kenarı olan iki yüz, kutu kapanınca komşu olur. Karşılıklı yüzler hiçbir zaman komşu olmadığı için açınımda bir kenarı paylaşamaz."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Taban ayrıtı 5 cm, yüksekliği 8 cm olan kare prizmanın yüzey alanı kaç cm²'dir?", o:["160","185","200","210"], a:3,
     w:"İki kare taban 2 · 5 · 5 = 50 cm², dört yan yüz 4 · 5 · 8 = 160 cm² eder. Yüzey alanı 50 + 160 = 210 cm²."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Can iki kutunun kapasitesini karşılaştırmak istiyor. Birinci kutuyu misketlerle, ikinci kutuyu sayı küpleriyle dolduruyor. Birinci kutuya 85 misket, ikinci kutuya 60 sayı küpü sığıyor.\n\nCan'ın “Birinci kutunun kapasitesi daha büyüktür.” sonucu için hangisi doğrudur?", o:["Doğrudur, çünkü birinci kutuya daha çok sayıda nesne sığmıştır","Yanlıştır, çünkü kutular aynı eş nesnelerle doldurulmamıştır","Doğrudur, çünkü misketler sayı küplerinden çok daha küçüktür","Yanlıştır, çünkü misketler kutuyu hiç boşluk bırakmadan doldurur"], a:1,
     w:"Kapasiteler ancak aynı eş nesnelerle, aralarında boşluk kalmadan doldurularak karşılaştırılabilir. Misket ve sayı küpü farklı nesneler olduğu için sayıları kıyaslanamaz."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Bir kutunun tabanına birim küpler 3 sıra hâlinde, her sırada 7 küp olacak biçimde diziliyor. Kutu, bu katmandan 6 tanesi üst üste konunca tamamen doluyor. Kutunun hacmi kaç br³'tür?", o:["16","21","42","126"], a:3,
     w:"Bir katmanda 3 · 7 = 21 birim küp vardır. Kutuda 6 katman olduğuna göre hacim 21 · 6 = 126 br³."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Bir bahçe için 0,35 m³ toprak alınıyor. Bu toprağın hacmi kaç dm³'tür?", o:["3,5","35","350","3500"], a:2,
     w:"Metreküpten desimetreküpe geçerken sayı 1000 ile çarpılır: 0,35 · 1000 = 350 dm³."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Taban ayrıtları 50 cm ve 30 cm olan dikdörtgenler prizması biçimindeki bir akvaryuma bir taş bırakılıyor. Taş tamamen suyun içinde kalıyor ve su seviyesi 2 cm yükseliyor. Taşın hacmi kaç litredir?", o:["3","0,3","30","300"], a:0,
     w:"Yükselen suyun hacmi taşın hacmine eşittir: 50 · 30 · 2 = 3000 cm³. Bu da 3 dm³, yani 3 L eder."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Ayrıtları 40 cm, 30 cm ve 20 cm olan bir sandığın bütün dış yüzeyi boyanacaktır. Bir kutu boya 2000 cm² alanı boyadığına göre en az kaç kutu boya gerekir?", o:["2","3","4","12"], a:1,
     w:"Yüzey alanı 2 · (40 · 30 + 40 · 20 + 30 · 20) = 5200 cm². 5200 ÷ 2000 = 2,6 olduğu için 2 kutu yetmez, en az 3 kutu gerekir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Aşağıdakilerden hangisi nicel (sürekli) veriye örnektir?", o:["Ailedeki kardeş sayısı","Öğrencilerin en sevdiği renk","Bir maçta atılan toplam gol sayısı","Öğrencilerin boy uzunlukları"], a:3,
     w:"Boy uzunluğu ölçümle bulunur ve iki ölçüm arasında sınırsız değer alabilir. Kardeş ve gol sayısı kesikli, en sevilen renk kategorik veridir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Elif, okulundaki öğrencilerin uyku süreleriyle ilgili bir araştırma yapmak istiyor. Aşağıdakilerden hangisi bu araştırma için uygun bir araştırma sorusudur?", o:["Dün gece saat kaçta yattın, sabah kaçta kalktın?","7/B öğrencilerinin uyku sürelerinin eğilimi nasıldır?","Okulumuzda ilk ders her sabah saat kaçta başlıyor?","Uyumadan önce kitap okumayı sever misin, neden?"], a:1,
     w:"Araştırma sorusu bir grubun verisindeki eğilimi sorar ve cevaplar kişiden kişiye değişir. Kişiye tek tek sorulanlar anket sorusudur, ilk dersin saati ise herkes için aynıdır."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"“İlimizdeki ortaokul öğrencilerinin okula geliş süreleri nasıl bir eğilim gösterir?” araştırma sorusu için evreni en iyi temsil edecek örneklem hangisidir?", o:["İlin farklı ilçelerinden seçilen öğrenciler","Okula en yakın sokakta oturan bütün öğrenciler","Okul servisini kullanan tek bir sınıfın öğrencileri","Yalnızca okula yürüyerek gelen öğrenciler"], a:0,
     w:"Örneklem evrenin özelliklerini taşımalıdır. Farklı ilçelerden seçilen öğrenciler okula yakın ve uzak oturanları birlikte içerir, öteki gruplar ise tek tip olduğu için sonucu yanıltır."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Zeynep'in boyu aynı gün, art arda iki farklı mezurayla ölçülüyor. Birinci ölçüm 152,4 cm, ikinci ölçüm 152,9 cm çıkıyor.\n\nİki ölçüm arasındaki farkın temel sebebi hangisidir?", o:["Kişiden kişiye değişen doğal boy farklılığı","Örneklemin evreni iyi temsil etmemesi","Ölçüm aracından kaynaklanan değişebilirlik","Verilerin kategorik veri türünde olması"], a:2,
     w:"Ölçülen kişi ve zaman aynıdır, değişen yalnız mezuradır. Fark bu yüzden ölçüm aracından kaynaklanan değişebilirliktir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"İstatistiksel araştırma sürecinin adımları hangi seçenekte doğru sırayla verilmiştir?", o:["Veri toplama → Soruyu belirleme → Analiz → Yorumlama","Soruyu belirleme → Analiz → Veri toplama → Yorumlama","Veri toplama → Analiz → Soruyu belirleme → Yorumlama","Soruyu belirleme → Veri toplama → Analiz → Yorumlama"], a:3,
     w:"Önce araştırma sorusu ile evren ve örneklem belirlenir, sonra veriler toplanıp analize hazırlanır. Ardından veriler görselleştirilip özetlenir, en son yorumlanıp karar verilir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Bir şehirde bir yıl boyunca her ayın ortalama hava sıcaklığı kaydediliyor. Sıcaklığın aylara göre artış ve azalışını en açık gösterecek grafik hangisidir?", o:["Çizgi grafiği","Daire grafiği","Nokta grafiği","Şekil grafiği"], a:0,
     w:"Sıcaklık sürekli bir veridir ve zamana bağlı değişir. Noktaları çizgiyle birleştiren grafik, artış ve azalış eğilimini en açık gösterir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Bir haftada her gün içilen su miktarları (L) şöyledir:\n\n2,0 1,8 2,4 2,6 2,2 1,9 2,3\n\nBu verilerin ortancası kaç litredir?", o:["2,0","2,2","2,4","2,6"], a:1,
     w:"Önce veriler sıralanır: 1,8 1,9 2,0 2,2 2,3 2,4 2,6. Yedi verinin ortasındaki dördüncü değer 2,2 L'dir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Ayşe ile Elif'in son 5 maçta attığı sayıların aritmetik ortalaması ikisi için de 15'tir. Ortalama mutlak sapma Ayşe'de 5,6, Elif'te 1,6'dır.\n\nBu bilgilere göre hangisi söylenebilir?", o:["Ayşe'nin performansı daha istikrarlıdır","İkisinin performansı aynı ölçüde istikrarlıdır","Ayşe her maçta Elif'ten daha çok sayı atmıştır","Elif'in performansı daha istikrarlıdır"], a:3,
     w:"Ortalama mutlak sapma, verilerin ortalamadan ne kadar uzaklaştığını gösterir. Elif'in değeri küçük olduğu için sayıları ortalama çevresinde toplanmıştır, yani daha istikrarlıdır."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Bir hastanın vücut sıcaklığı saat 10.00'da 39,1 °C, 11.00'de 38,8 °C, 12.00'de 38,2 °C ve 13.00'te 37,6 °C ölçülmüştür. Ali bu verilere bakarak “İlaç içtiği için ateşi düştü.” diyor.\n\nAli'nin yorumu için hangisi doğrudur?", o:["Sıcaklık her saat düştüğü için yorum kesinlikle doğrudur","Dört ölçüm yapıldığı için yorum her zaman doğrudur","Verilerde ilaçla ilgili bilgi yok, yorum veriye dayanmıyor","Sıcaklık 37,6 °C'ye kadar indiği için yorum kesin doğrudur"], a:2,
     w:"Veriler yalnız sıcaklığın düştüğünü gösterir, düşüşün sebebini göstermez. Tabloda ya da grafikte olmayan bir bilgiyle yapılan yorum yanıltıcı olabilir."}
  ]);
  H7.mat = (H7.mat || []).concat([
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Eş küplerle kurulan bir yapının üstten görünümüne, her karede üst üste duran küp sayısı yazılmıştır. Üst satır arka sıra, alt satır ön sıradır.\n\nArka sıra (soldan sağa): 2 1 2\nÖn sıra (soldan sağa): 1 3 1\n\nHangi küp yapıdan alınırsa yapının önden görünümü DEĞİŞMEZ?", o:["Ön sıranın ortasındaki kulenin en üstteki küpü","Arka sıranın solundaki kulenin en üstteki küpü","Arka sıranın sağındaki kulenin en üstteki küpü","Ön sıranın sağındaki tek katlı kuledeki küp"], a:3,
     w:"Önden bakınca her sütunun yalnız en yüksek kulesi görünür. Sağ sütunda arkadaki 2 katlı kule öndeki tek küpten yüksek olduğu için o küp alınsa da sağ sütun önden yine 2 kare görünür."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Bir küpün bütün ayrıtlarının uzunlukları toplamı 84 cm'dir. Bu küpün yüzey alanı kaç cm²'dir?", o:["49","196","294","343"], a:2,
     w:"Küpün 12 eş ayrıtı vardır: 84 ÷ 12 = 7 cm. Bir yüzün alanı 7 · 7 = 49 cm², altı yüzün alanı 6 · 49 = 294 cm²."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Bir dikdörtgenler prizmasının taban ayrıtlarından biri yarıya indiriliyor, yüksekliği 3 katına çıkarılıyor, öteki ayrıtı değişmiyor. Prizmanın hacmi için hangisi doğrudur?", o:["3 katına çıkar","1,5 katına çıkar","6 katına çıkar","4,5 katına çıkar"], a:1,
     w:"Hacim üç ayrıtın çarpımıdır. Bir çarpan yarıya inip bir çarpan 3 katına çıkınca hacim (1/2) · 3 = 1,5 katına çıkar."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Aşağıdakilerden hangisi 1 litreye eşit DEĞİLDİR?", o:["100 mL","1 dm³","1000 cm³","10 dL"], a:0,
     w:"1 L = 1 dm³ = 1000 cm³ ve 1 L = 10 dL = 1000 mL'dir. 100 mL ise litrenin onda biridir."},
    {u:"TEMA 5 · Geometrik Nicelikler (1)", q:"Ayrıtları 10 cm, 20 cm ve 30 cm olan dikdörtgenler prizması biçimindeki bir kutu, ayrıtı 5 cm olan eş küplerle boşluk kalmadan dolduruluyor. Kutuya kaç küp yerleştirilir?", o:["12","48","240","1200"], a:1,
     w:"Ayrıtlar boyunca 10 ÷ 5 = 2, 20 ÷ 5 = 4 ve 30 ÷ 5 = 6 küp sığar. Kutuya 2 · 4 · 6 = 48 küp yerleştirilir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Aşağıdakilerden hangisi kişisel veri DEĞİLDİR?", o:["Bir öğrencinin ev adresi","Bir kişinin kan grubu","Okulun kuruluş yılı","Bir öğrencinin kilosu"], a:2,
     w:"Kimlik, sağlık, adres, banka ve günlük yaşam bilgileri kişiye aittir. Okulun kuruluş yılı bir kişiyle ilgili olmadığı için kişisel veri sayılmaz."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Bir öğrenci, ülkemizdeki yıllık yağış miktarlarıyla ilgili hazır verilere ulaşmak istiyor. Bu veriler için en güvenilir kaynak hangisidir?", o:["Meteoroloji Genel Müdürlüğünün resmî sitesi","Kaynağı belirtilmemiş bir sosyal medya paylaşımı","Bir arkadaşının kendi gözlemine dayanan tahmini","Reklam içeren kişisel bir blog yazısı"], a:0,
     w:"Hazır veriler, bu verileri düzenli toplayan resmî kurumların sitelerinden (gov.tr, edu.tr, org.tr uzantılı) alınmalıdır. Kaynağı belirsiz paylaşımlar ve tahminler güvenilir değildir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Bir veri setinin temsil değeri ile ilgili hangisi doğrudur?", o:["Mutlaka veri setinde yer alan bir sayı olmalıdır","Her zaman veri setinin en büyük değeridir","Yalnız tepe değer temsil değeri olarak seçilebilir","Veri setinde bulunmayan bir sayı da olabilir"], a:3,
     w:"Temsil değeri, gerekçesi yazılarak seçilen ve veri setini en iyi anlatan değerdir. Örneğin veri setinde yer almayan aritmetik ortalama da temsil değeri olabilir."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"3, 7, 8, 10 ve 12 verilerinin ortalama mutlak sapması kaçtır?", o:["2","2,4","3","9"], a:1,
     w:"Ortalama 40 ÷ 5 = 8. Verilerin 8'e uzaklıkları 5, 1, 0, 2 ve 4, toplamları 12. Ortalama mutlak sapma 12 ÷ 5 = 2,4."},
    {u:"TEMA 8 · İstatistiksel Araştırma Süreci", q:"Bir istatistiksel araştırmada “evren” için hangisi doğrudur?", o:["Verilerin toplanabileceği en geniş gruptur","Evrenden seçilen ve onu temsil eden küçük gruptur","Anketteki bütün sorulardan oluşur","Verileri gösteren grafiğin adıdır"], a:0,
     w:"Evren, araştırma sorusuna yönelik verilerin toplanabileceği en geniş gruptur. Ondan seçilen ve onu temsil eden daha küçük gruba örneklem denir."}
  ]);
  EKC7.mat = (EKC7.mat || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Deniz seviyesinin 18,6 m altındaki bir dalgıç önce 7,25 m yükseliyor, sonra 3,4 m alçalıyor. Dalgıcın son konumu deniz seviyesine göre kaç metredir?", o:["−14,75","−29,25","−7,95","14,75"], a:0,
     w:"Deniz seviyesinin altı negatif alınır: −18,6 + 7,25 = −11,35 ve −11,35 − 3,4 = −14,75. Dalgıç deniz seviyesinin 14,75 m altındadır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif harçlığının 2/5'i ile kitap alıyor. Kalan paranın 1/3'ü ile defter alınca geriye 180 TL kalıyor. Elif'in harçlığı kaç TL'dir?", o:["540","450","675","900"], a:1,
     w:"Kitaptan sonra harçlığın 3/5'i kalır. Bunun 1/3'ü harçlığın 1/5'i olduğundan geriye 3/5 − 1/5 = 2/5 kalır. Harçlığın 2/5'i 180 TL ise tamamı 180 ÷ 2 · 5 = 450 TL."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elektrik kesilince −18 °C olan bir dondurucunun iç sıcaklığı her saat 2,5 °C artıyor. Kaç saat sonra sıcaklık −5,5 °C olur?", o:["2,2","9,4","5","12,5"], a:2,
     w:"Sıcaklık −18 °C'den −5,5 °C'ye çıkınca −5,5 − (−18) = 12,5 °C artmış olur. 12,5 ÷ 2,5 = 5 saat."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Eş küplerle kurulan bir yapı için şunlar biliniyor:\n• Üstten bakınca 2 sıra ve 3 sütundan oluşan 6 kare görülür, bütün kareler doludur.\n• Önden bakınca sütunların yüksekliği soldan sağa 3, 1 ve 2 küptür.\n• Sağdan bakınca sıraların yüksekliği önden arkaya 3 ve 2 küptür.\n\nBu yapı en az kaç küple kurulmuştur?", o:["6","11","12","9"], a:3,
     w:"Her kareye en az 1 küp gerekir (6 küp). Sol sütunun ön karesine 3 küp koymak önden 3'ü ve sağdan 3'ü birlikte sağlar (+2), sağ sütunun arka karesine 2 küp koymak önden 2'yi ve sağdan 2'yi sağlar (+1). En az 6 + 2 + 1 = 9 küp gerekir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir yapının üstten görünümüne, her karede üst üste duran küp sayısı yazılmıştır. Üst satır arka sıra, alt satır ön sıradır.\n\nArka sıra (soldan sağa): 1 2 4\nÖn sıra (soldan sağa): 3 1 1\n\nBu yapıya sağdan bakıldığında kaç kare görülür?", o:["7","6","9","12"], a:0,
     w:"Sağdan bakınca her sıranın yalnız en yüksek kulesi görünür: arka sırada 4, ön sırada 3 küp. Sağdan görünümde 4 + 3 = 7 kare vardır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ayrıtları 6 cm, 5 cm ve 4 cm olan dikdörtgenler prizmasının yüzey alanı kaç cm²'dir?", o:["88","148","74","120"], a:1,
     w:"Üç farklı yüzün alanı 6 · 5 = 30, 6 · 4 = 24 ve 5 · 4 = 20 cm²'dir. Her birinden ikişer tane olduğu için yüzey alanı 2 · (30 + 24 + 20) = 148 cm²."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir dikdörtgenler prizmasının birbirinden farklı üç yüzünün alanları 12 cm², 15 cm² ve 20 cm²'dir. Bu prizmanın yüzey alanı kaç cm²'dir?", o:["47","60","94","188"], a:2,
     w:"Karşılıklı yüzler eş olduğu için her alandan ikişer tane vardır: 2 · (12 + 15 + 20) = 2 · 47 = 94 cm²."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Taban çevresi 24 cm, yüksekliği 10 cm olan bir kare prizmanın yüzey alanı kaç cm²'dir?", o:["240","276","360","312"], a:3,
     w:"Taban ayrıtı 24 ÷ 4 = 6 cm. Dört yan yüz 4 · 6 · 10 = 240 cm², iki taban 2 · 6 · 6 = 72 cm² eder, toplam 240 + 72 = 312 cm²."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İki kutu, aynı eş tahta bloklarla boşluk kalmadan dolduruluyor. Birinci kutuya her katta 6 blok olacak biçimde 7 kat, ikinci kutuya her katta 5 blok olacak biçimde 9 kat yerleştiriliyor.\n\nKutuların hacimleri için hangisi doğrudur?", o:["İkinci kutunun hacmi 3 blok daha büyüktür","Birinci kutunun hacmi 3 blok daha büyüktür","İki kutunun hacmi birbirine eşittir","İkinci kutunun hacmi 2 blok daha büyüktür"], a:0,
     w:"Birinci kutuya 6 · 7 = 42, ikinci kutuya 5 · 9 = 45 blok sığar. Aynı eş bloklarla ölçüldüğü için ikinci kutunun hacmi 45 − 42 = 3 blok fazladır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Taban alanı 36 cm², hacmi 288 cm³ olan bir dikdörtgenler prizmasının yüksekliği kaç cm'dir?", o:["6","8","12","252"], a:1,
     w:"Hacim = taban alanı × yükseklik olduğundan yükseklik 288 ÷ 36 = 8 cm'dir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"24 eş birim küpün tamamı kullanılarak kaç farklı dikdörtgenler prizması oluşturulabilir? (Döndürülünce aynı olan prizmalar bir kez sayılır.)", o:["4","5","6","8"], a:2,
     w:"Çarpımı 24 olan ayrıt üçlüleri 1 · 1 · 24, 1 · 2 · 12, 1 · 3 · 8, 1 · 4 · 6, 2 · 2 · 6 ve 2 · 3 · 4'tür. Şekilleri farklı olsa da hepsinin hacmi 24 br³'tür."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir balık tankının hacmi 0,045 m³'tür. Bu tank kaç litre su alır?", o:["4,5","450","4500","45"], a:3,
     w:"1 m³ = 1000 dm³ ve 1 dm³ = 1 L olduğundan 0,045 m³ = 45 dm³ = 45 L."},
    {u:"EK · 2. Yazılı Hazırlık", q:"2 L + 350 mL + 15 cL toplamı kaç mL'dir?", o:["2500","2365","2650","3850"], a:0,
     w:"Hepsi mililitreye çevrilir: 2 L = 2000 mL, 15 cL = 150 mL (1 cL = 10 mL). Toplam 2000 + 350 + 150 = 2500 mL."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Dereceli bir kapta 350 mL su vardır. Kaba bir taş bırakılınca su 520 mL çizgisine yükseliyor. Taşın hacmi kaç dm³'tür?", o:["0,017","0,17","1,7","170"], a:1,
     w:"Su seviyesindeki artış taşın hacmidir: 520 − 350 = 170 mL = 170 cm³. 1 dm³ = 1000 cm³ olduğundan 170 cm³ = 0,17 dm³."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Taban ayrıtları 50 cm ve 40 cm, yüksekliği 30 cm olan bir sandığın alt yüzü dışındaki bütün dış yüzeyi kumaşla kaplanacaktır. Kumaşın metrekaresi 200 TL olduğuna göre kaplama kaç TL tutar?", o:["108","188","148","1480"], a:2,
     w:"Yüzey alanı 2 · (50 · 40 + 50 · 30 + 40 · 30) = 9400 cm², alt yüz çıkarılınca 9400 − 2000 = 7400 cm² = 0,74 m² kalır. Kaplama 0,74 · 200 = 148 TL tutar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ayrıtları 2 m, 1,5 m ve 1 m olan dikdörtgenler prizması biçimindeki bir kasa, ayrıtları 50 cm, 25 cm ve 20 cm olan eş kolilerle boşluk kalmadan dolduruluyor. Kasaya kaç koli yerleştirilmiştir?", o:["12","60","1200","120"], a:3,
     w:"Kasanın ayrıtları 200 cm, 150 cm ve 100 cm'dir. Ayrıtlar boyunca 200 ÷ 50 = 4, 150 ÷ 25 = 6 ve 100 ÷ 20 = 5 koli sığar, toplam 4 · 6 · 5 = 120 koli."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Taban ayrıtları 1,2 m ve 0,8 m, yüksekliği 1 m olan dikdörtgenler prizması biçimindeki bir su deposunun 3/4'ü doludur. Depoda kaç litre su vardır?", o:["720","72","240","960"], a:0,
     w:"Deponun hacmi 1,2 · 0,8 · 1 = 0,96 m³ = 960 dm³ = 960 L. Dörtte üçü dolu olduğundan depoda 960 · 3/4 = 720 L su vardır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Taban ayrıtları 60 cm ve 40 cm, yüksekliği 50 cm olan bir akvaryumda 30 cm yüksekliğinde su vardır. Akvaryuma toplam hacmi 12 L olan süs taşları konuyor ve taşların hepsi suyun içinde kalıyor. Su seviyesi kaç cm olur?", o:["30,5","35","42","80"], a:1,
     w:"12 L = 12 000 cm³ ve taban alanı 60 · 40 = 2400 cm² olduğundan su 12 000 ÷ 2400 = 5 cm yükselir. Yeni seviye 30 + 5 = 35 cm olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Diş fırçalarken musluk açık kalırsa dakikada 6 L su boşa akıyor. Bir kişi dişlerini günde 2 kez, her seferinde 2 dakika boyunca musluğu açık bırakarak fırçalıyor. Bu kişi 30 günde kaç m³ su israf eder?", o:["0,072","7,2","0,72","72"], a:2,
     w:"Bir fırçalamada 6 · 2 = 12 L, bir günde 24 L, 30 günde 24 · 30 = 720 L su boşa akar. 1 m³ = 1000 L olduğundan 720 L = 0,72 m³."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ayrıtları 10 cm, 10 cm ve 20 cm olan kare prizma biçimindeki bir tahta blok tam ortadan kesilerek iki eş küp elde ediliyor. İki küpün yüzey alanları toplamı, bloğun yüzey alanından kaç cm² fazladır?", o:["0","100","400","200"], a:3,
     w:"Bloğun yüzey alanı 2 · 10 · 10 + 4 · 10 · 20 = 1000 cm², iki küpün yüzey alanları toplamı 2 · 6 · 10 · 10 = 1200 cm²'dir. Kesimde iki yeni yüz ortaya çıktığı için fark 1200 − 1000 = 200 cm² olur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"8 öğrencinin günlük kitap okuma süreleri (dakika) şöyledir:\n\n12 15 22 15 18 27 20 15\n\nBu veri seti için aşağıdakilerden hangisi YANLIŞTIR?", o:["Ortancası 18 dakikadır","Aritmetik ortalaması 18 dakikadır","Tepe değeri 15 dakikadır","Açıklığı 15 dakikadır"], a:0,
     w:"Sıralı veri: 12 15 15 15 18 20 22 27. Veri sayısı çift olduğu için ortanca ortadaki iki verinin ortalamasıdır: (15 + 18) ÷ 2 = 16,5 dakika. Ortalama 144 ÷ 8 = 18, tepe değer 15, açıklık 27 − 12 = 15'tir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir apartmandaki 6 dairenin aylık su tüketimleri (m³) şöyledir:\n\n8 9 10 9 11 41\n\nBu veri setini temsil etmek için hangi seçim ve gerekçe daha uygundur?", o:["Aritmetik ortalama, çünkü uç değerden hiç etkilenmez","Ortanca, çünkü uç değerden ortalama kadar etkilenmez","Açıklık, çünkü verilerin merkezini gösterir","En büyük değer, çünkü tüketimin üst sınırıdır"], a:1,
     w:"41 öteki verilerden çok büyük bir uç değerdir ve ortalamayı yaklaşık 14,7'ye çeker. Ortanca (9 + 10) ÷ 2 = 9,5 olur ve dairelerin çoğunun tüketimine yakındır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir fidanın boyu 5 hafta boyunca ölçülüp çizgi grafiğine aktarılıyor. Ölçümler şöyledir: 1. hafta 2,4 cm · 2. hafta 4,1 cm · 3. hafta 6,3 cm · 4. hafta 7,0 cm · 5. hafta 7,2 cm\n\nGrafiğe göre hangisi söylenebilir?", o:["Fidan her hafta aynı miktarda uzamıştır","Fidanın boyu 4. haftadan sonra kısalmıştır","Fidan en hızlı 2. ile 3. hafta arasında uzamıştır","Fidan en hızlı 4. ile 5. hafta arasında uzamıştır"], a:2,
     w:"Haftalık artışlar 1,7 cm, 2,2 cm, 0,7 cm ve 0,2 cm'dir. En büyük artış 2. ile 3. hafta arasındadır, çizgi de en dik orada yükselir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Doktor, Can'a her gün en az 1,5 L su içmesini öneriyor. Can'ın bir haftada içtiği su miktarları (L) şöyledir:\n\n1,2 1,6 1,4 1,8 1,3 1,7 1,5\n\nBu verilere göre Can için hangisi doğrudur?", o:["Her gün önerilen miktar kadar ya da daha fazla su içmiştir","Su tüketiminin açıklığı 0,3 L'dir","Su tüketiminin ortancası 1,8 L'dir","Ortalaması 1,5 L'dir ama 3 gün önerinin altında kalmıştır"], a:3,
     w:"Ortalama 10,5 ÷ 7 = 1,5 L, yani tam öneri sınırındadır. Ama 1,2 L, 1,3 L ve 1,4 L içtiği 3 gün önerinin altında kalmıştır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir öğrenci yalnız kendi sınıfındaki 30 öğrenciye en sevdiği sporu soruyor. En çok voleybol seçilince “Ülkemizdeki ortaokul öğrencilerinin en sevdiği spor voleyboldur.” sonucuna varıyor.\n\nBu sonuç için hangisi doğrudur?", o:["Örneklem evreni temsil etmediği için genelleme hatalıdır","30 kişiye sorulduğu için sonuç kesinlikle doğrudur","Veriler kategorik olduğu için hiçbir yorum yapılamaz","Sonuç ancak bir daire grafiği çizilirse doğru kabul edilir"], a:0,
     w:"Veriler yalnız bir sınıftan toplanmıştır. Bu küçük grup ülkedeki bütün ortaokul öğrencilerini temsil etmez, sonuç ancak o sınıf için söylenebilir."}
  ]);

  /* ---------- 7. sınıf · Sosyal Bilgiler ---------- */
  Q7.sos = (Q7.sos || []).concat([
    {u:"ALAN 3 · Ortak Mirasımız", q:"Osmanlı Devleti'nin Balkanlarda fethettiği yerlere Anadolu'dan Türk-Müslüman toplulukları yerleştirmesinin temel amacı nedir?", o:["Bölgede kalıcı hâkimiyet kurmak","Anadolu'daki vergileri azaltmak","Yerli halkı bölgeden çıkarmak","Avrupa ile ticareti durdurmak"], a:0,
     w:"Bu uygulama iskân politikasıdır. Yerleştirilen nüfus fethedilen yerin Türkleşmesini ve İslamlaşmasını sağlayarak Osmanlı'nın orada kalıcı olarak tutunmasına yardım etti."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Fatih Sultan Mehmed İstanbul'a girdiğinde Ayasofya'da toplanan halka canlarından ve özgürlüklerinden endişe etmemelerini söylemiş, askerlerine de halka zarar vermemelerini emretmiştir.\n\nBu davranış Osmanlı Devleti'nin hangi politikasını yansıtır?", o:["İskân politikasını","Batıya ilerleme politikasını","İstimalet politikasını","Anadolu Türk birliği politikasını"], a:2,
     w:"Fethedilen yerin halkına, özellikle gayrimüslimlere adaletli ve hoşgörülü davranıp gönüllerini kazanmaya istimalet denir. Fatih'in halka güvence vermesi bunun açık bir örneğidir."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Aşağıdakilerden hangisi İstanbul'un fethinin ekonomik nedenleri arasında yer alır?", o:["Doğu Roma'nın Anadolu beyliklerini kışkırtması","İpek Yolu gibi ticaret yolları üzerinde bulunması","Fethi müjdeleyen bir hadisin bulunması","Anadolu ile Balkanlar arasındaki bütünlüğü bozması"], a:1,
     w:"Önemli ticaret yollarının denetimi ekonomik bir nedendir. Beylikleri kışkırtması ve toprak bütünlüğüne engel olması siyasi, Peygamberimizin hadisi ise dinî nedendir."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Mısır Seferi (1516–1517) sonunda Mekke ve Medine'nin Osmanlı topraklarına katılması devlete ne kazandırmıştır?", o:["Avrupa'daki fetihlerini hızlandırmıştır","Doğu sınırını güvence altına almıştır","Rumeli'ye ilk kez geçmesini sağlamıştır","İslam dünyasında saygınlığını artırmıştır"], a:3,
     w:"Kutsal şehirleri yönetimine alan Osmanlı, İslam dünyasının önde gelen devleti oldu ve saygınlığı arttı. Doğu sınırını güçlendiren olay 1514'teki Çaldıran Savaşı'dır."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Preveze Deniz Muharebesi'nde (1538) Osmanlı donanmasının Haçlı donanmasını yenmesinde aşağıdakilerden hangisi etkili olmuştur?", o:["Gemilerin karadan yürütülerek indirilmesi","Haliç girişine demir zincir çekilmesi","Donanmanın hilal biçiminde düzenlenmesi","Boğaz kıyısına Rumeli Hisarı'nın yapılması"], a:2,
     w:"Barbaros Hayreddin Paşa donanmasını hilal biçiminde dizdi, hızlı kadırgalar ve uzun menzilli toplarla büyük Haçlı gemilerini etkisiz bıraktı. Gemilerin karadan yürütülmesi, Haliç zinciri ve Rumeli Hisarı ise İstanbul kuşatmasıyla ilgilidir."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Osmanlı liman şehirlerinin eski önemini yitirmesi ve devletin ticaretten elde ettiği gelirlerin azalması aşağıdaki gelişmelerden hangisinin sonucudur?", o:["Avrupalıların okyanus aşırı büyük deniz seyahatleri yapması","Reform hareketlerinin Avrupa'da mezhep savaşları çıkarması","Lale Devri'nde İstanbul'da imar faaliyetlerinin artması","Fransız İhtilali'nin milliyetçilik fikrini yayması"], a:0,
     w:"Avrupalılar okyanus yollarını kullanmaya başlayınca Akdeniz ve Karadeniz ticareti canlılığını yitirdi, Osmanlı liman şehirleri önemini kaybetti ve devletin gelirleri azaldı."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Lale Devri'nde İbrahim Müteferrika'nın ilk Türk matbaasını açmasının (1727) doğrudan sonucu hangisidir?", o:["Divan teşkilatının kaldırılıp nazırlıkların kurulması","Avrupa başkentlerinde ilk daimî elçiliklerin açılması","Yeniçeri Ocağı'nın kaldırılıp yerine yeni ordu kurulması","Kitap basımının hızlanıp bilgiye erişimin kolaylaşması"], a:3,
     w:"Matbaa sayesinde kitaplar daha hızlı ve daha çok basıldı, bilgiye erişim kolaylaştı. Nazırlıklar II. Mahmud, daimî elçilikler III. Selim Dönemi'ne aittir."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"II. Mahmud'un 1826'da Yeniçeri Ocağı'nı kaldırmasının (Vaka-i Hayriye) temel nedeni nedir?", o:["Avrupa'da Reform hareketlerinin hızla yayılması","Yeniçerilerin düzeni bozup sık sık isyan etmesi","Baharat Yolu'nun ticaretteki önemini kaybetmesi","Lale Devri'nde imar işlerinin giderek artması"], a:1,
     w:"II. Mahmud tahta geçtiğinde devlet düzeni bozulmuştu ve yeniçeriler sürekli ayaklanıyordu. Ocak kaldırılınca yerine Asâkir-i Mansûre-i Muhammediye adlı düzenli bir ordu kuruldu."}
  ]);
  H7.sos = (H7.sos || []).concat([
    {u:"ALAN 3 · Ortak Mirasımız", q:"Osmanlı Devleti'nde hükümdarın ülke yönetiminde geniş yetkiye sahip olması, görevlilerin ve kurumların alınan kararları ülkenin her yerinde uygulaması hangi kavramla açıklanır?", o:["İstimalet anlayışı","Merkezî otorite","İskân politikası","Feodal düzen"], a:1,
     w:"Gücün tek merkezde toplanıp ülkenin bu merkezden yönetilmesi merkezî otoritedir. Bu sayede Osmanlı kısa sürede büyüdü ve uzun süre ayakta kaldı."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"İstanbul kuşatmasında kullanılan büyük topların kalın surları yıkabildiğinin görülmesi Avrupa'da hangi sonucu doğurmuştur?", o:["Kilisenin etkisi artmıştır","Haçlı seferleri başlamıştır","Doğu Roma güçlenmiştir","Feodal sistem zayıflamıştır"], a:3,
     w:"Kitaba göre büyük topların surları yıkabilmesi Avrupa'daki feodal sistemi zayıflattı. Bu, fethin dünya tarihi açısından sonuçlarından biridir."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Yavuz Sultan Selim Dönemi'nde Turnadağ Savaşı'yla (1515) Osmanlı topraklarına katılan son Anadolu beyliği hangisidir?", o:["Dulkadiroğulları","Karesioğulları","Memlükler","Safeviler"], a:0,
     w:"Turnadağ Savaşı'yla Dulkadiroğulları Beyliği'ne son verildi ve bu beylik Osmanlı'ya katılan son Anadolu beyliği oldu. Karesioğulları ise Orhan Bey Dönemi'nde katılmıştı."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Reform hareketleri sonucunda Avrupa'da çıkan mezhep savaşları Osmanlı Devleti'ni nasıl etkilemiştir?", o:["Gayrimüslim halkın inanç özgürlüğünün kısıtlanmasına yol açmıştır","Osmanlı'nın İpek ve Baharat Yolları gelirlerini artırmıştır","Yeni bir Haçlı birliğinin kurulmasını bir süre engellemiştir","Osmanlı esnafının ucuz mallarla rekabet edememesine yol açmıştır"], a:2,
     w:"Mezhep savaşları Avrupa'nın siyasi birliğini zayıflattı. Bu durum Osmanlı'ya karşı yeni bir Haçlı birliği kurulmasını bir süre engelledi ve Avrupa'daki ilerleyişi kolaylaştırdı. Osmanlı'daki gayrimüslimler ise dinî baskı görmedi."},
    {u:"ALAN 3 · Ortak Mirasımız", q:"Tanzimat Fermanı'nı (1839) Osmanlı tarihinde önemli kılan özellik hangisidir?", o:["Halkın seçtiği temsilcilerden oluşan ilk meclisi açması","Padişahın kendi yetkilerini ilk kez kendi eliyle sınırlaması","Yeniçeri Ocağı'nın kaldırıldığını bütün ülkeye duyurması","Avrupa başkentlerinde ilk daimî elçiliklerin açılmasını sağlaması"], a:1,
     w:"Mustafa Reşid Paşa'nın hazırladığı ferman, yeni bir rejime geçmeden padişahın yetkilerini ilk kez kendi eliyle sınırladı ve herkese can ve mal güvencesi verdi. İlk meclis 1876'da açıldı."}
  ]);
  EKC7.sos = (EKC7.sos || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Can, arkadaşı Ali derdini anlatırken telefonunu kenara bırakıyor, göz teması kuruyor, sözünü kesmiyor ve ara ara “Seni anlıyorum.” diyor.\n\nCan'ın bu tutumu etkili iletişimin hangi ögesine örnektir?", o:["Sen dili","Ön yargı","Etkin dinleme","Yazılı iletişim"], a:2,
     w:"Konuşanı doğru anlamak için dikkatle ve sözünü kesmeden dinlemek, bunu göz temasıyla ve “Seni anlıyorum.” gibi sözlerle göstermek etkin dinlemedir. Bu tutum iletişimde güven ve saygı ortamı oluşturur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir okulda tekerlekli sandalye kullanan öğrenciler için rampa ve asansör yapılmış, görme yetersizliği olan öğrenciler için kabartma yazılı (Braille) kitaplar alınmıştır.\n\nBu düzenlemeler en çok neyi sağlamaya yöneliktir?", o:["Fırsat eşitliğini","Etkin dinlemeyi","Millî birlik ve beraberliği","Ben dilinin kullanımını"], a:0,
     w:"Herkesin sahip olduğu özellikler ne olursa olsun aynı haklardan yararlanabilmesi fırsat eşitliğidir. Okuldaki fiziksel düzenlemeler özel gereksinimli öğrencilerin eğitime eşit şartlarda katılmasını sağlar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Millî Mücadele yıllarında halk, Tekâlif-i Millîye Emirleri kapsamında elindeki yiyecek, giyecek ve araç gereci orduyla paylaşmıştır.\n\nBu durum Türk toplumunun en çok hangi özelliğini gösterir?", o:["Bilime ve sanata değer verme","Farklı kültürleri merak etme","Teknolojiyi hızla benimseme","Fedakârlık ve dayanışma"], a:3,
     w:"Halk imkânsızlıklar içinde bile kendi ihtiyacından vazgeçerek elindekini cepheye gönderdi. Bu davranış vatan sevgisinin ve büyük bir fedakârlık örneğinin göstergesidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"15 Temmuz 2016'da darbe girişimine karşı halkın sokaklara çıkıp demokrasiye ve millî iradeye sahip çıkması, Türk toplumunun millî meseleler karşısındaki hangi tutumunu yansıtır?", o:["Sorunların çözümünü devlete bırakmasını","Ortak bir amaç etrafında kenetlenmesini","Bireysel çıkarlarını öne çıkarmasını","Zor zamanlarda sessiz kalmayı seçmesini"], a:1,
     w:"Türk toplumu bağımsızlık, güvenlik ve demokrasi gibi milletin tamamını ilgilendiren konularda birlik ve beraberlik içinde hareket eder. 15 Temmuz'da halkın kararlılığı darbe girişimini kısa sürede başarısız kıldı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Elif, başka bir ülkedeki arkadaşıyla görüntülü konuşabiliyor, dünyanın öbür ucundaki bir olayın haberine saniyeler içinde ulaşabiliyor.\n\nBu örnekler küreselleşmenin en çok hangi alandaki etkisini gösterir?", o:["Sağlık","Çevre","İletişim","Ekonomi"], a:2,
     w:"Genel ağ ve mobil cihazlar bilgiye ulaşmayı kolaylaştırdı, uzaktaki kişilerle canlı görüşmeyi mümkün kıldı. Bunlar iletişim sistemlerindeki gelişmelerin örnekleridir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Konuşma dilimize başka dillerden çok sayıda sözcük girmesi ve popüler müziğin geleneksel müziğimizi geri plana itmesi küreselleşmenin hangi sonucuna örnektir?", o:["Yerel kültürlerin zayıflamasına","Salgınların hızla yayılmasına","Ticaret hacminin artmasına","Ulaşımın kolaylaşmasına"], a:0,
     w:"Kültürel etkileşimle bazı ögeler başka kültürlere yerleşir. Bu da dili ve yerel gelenekleri yok olma tehlikesiyle karşı karşıya bırakabilir. Bu yüzden millî kültüre sahip çıkmak önemlidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Çin'de ortaya çıkan COVID-19 salgınının kısa sürede bütün dünyaya yayılması küreselleşmeyle ilgili hangi yargıyı destekler?", o:["Sağlık alanındaki gelişmeler yalnız zengin ülkelere yarar sağlar.","Salgın hastalıklar ulaşım ve iletişimden hiç etkilenmez.","Küreselleşme ülkelerin sağlık sorunlarını tamamen ortadan kaldırır.","Ülkeler arası yoğun etkileşim hastalıkların yayılmasını da hızlandırır."], a:3,
     w:"Ülkeler arasında insan ve ürün hareketi arttıkça hastalıklar da kısa sürede her yere ulaşabilir. Öte yandan ülkeler araştırma sonuçlarını paylaşarak ortak çözüm de üretebilir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Rusya–Ukrayna Savaşı sırasında Türkiye'nin girişimiyle ve BM Genel Sekreteri'nin katılımıyla Karadeniz'de tahıl taşımacılığını düzenleyen anlaşma İstanbul'da imzalanmıştır.\n\nBu gelişme Türkiye'nin hangi rolünü öne çıkarır?", o:["Bölgesel sorunlarda bekle-gör tutumu izlemesini","Çatışan taraflar arasında ara buluculuk yapmasını","Sorunları askerî güçle çözmeyi öncelemesini","Uluslararası kuruluşlarla iş birliğinden kaçınmasını"], a:1,
     w:"Türkiye tarafsızlığını koruyarak savaşan iki ülkeyi aynı masada buluşturdu, anlaşmanın imzalanmasını ve İstanbul'da bir koordinasyon merkezi kurulmasını sağladı. Böylece küresel gıda krizinin önlenmesine katkıda bulundu."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir aile, ülkesinde çıkan savaş yüzünden evini bırakıp Türkiye'ye sığınmak zorunda kalmıştır.\n\nBu aile üyelerini tanımlayan kavram hangisidir?", o:["Turist","Diplomat","Mevsimlik işçi","Mülteci"], a:3,
     w:"Savaş, çatışma ya da baskı yüzünden ülkesini terk edip başka bir ülkeye sığınan kişilere mülteci denir. Türkiye, topraklarına sığınanlara eğitim, sağlık ve barınma desteği verir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi küresel iklim krizinin nedenlerinden biri DEĞİLDİR?", o:["Fosil yakıtların yoğun biçimde kullanılması","Ormanların hızla kesilmesi","Yenilenebilir enerji kullanımının artması","Sanayileşmenin giderek artması"], a:2,
     w:"Fosil yakıtların yoğun kullanılması, ormanların kesilmesi ve sanayileşme atmosfere fazla sera gazı salınmasına yol açarak iklim krizini doğurur. Yenilenebilir enerji ise bu nedenler arasında değil, çözüm yolları arasında yer alır (ek bilgi)."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Türkiye, beş kıtada yürüttüğü kalkınma çalışmaları ve bağışlarıyla millî gelirine oranla dünyanın en cömert ülkesi olarak anılmaktadır.\n\nBu durum Türk dış politikasının hangi özelliğini yansıtır?", o:["Zor durumdakilere yardım eden insani anlayışını","Yalnız kendi ekonomik çıkarını gözeten tutumunu","Uzak bölgelerdeki krizlere kayıtsız kalmasını","Askerî gücü her şeyin önünde tutan yaklaşımını"], a:0,
     w:"Türkiye girişimci ve insani bir dış politika izler. Gücünü tarihinden ve geleneklerinden alan değerlerle dünyanın farklı bölgelerinde zor durumda kalan insanlara destek olmayı sorumluluk sayar."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kuzey Makedonya'da Türkiye Maarif Vakfının açtığı Kalkandelen Maarif Okulu ve Kolombiya'da Türk yazarların İspanyolcaya çevrilen eserleriyle kurulan mobil kütüphane, Türkiye'nin hangi alandaki iş birliklerine örnektir?", o:["Sağlık ve tedavi","Eğitim ve kültür","Savunma ve güvenlik","Enerji ve ulaşım"], a:1,
     w:"Okul ve kütüphane çalışmaları eğitime ve kitaba erişimi kolaylaştırır. Bu tür projeler ülkeler arasında gönül köprüsü kurarak dostluğu güçlendirir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Göç İdaresi Başkanlığı, ülkemize göç eden Ahıska Türkleri için Bitlis'te konutlar yaptırmış, tarım, hayvancılık ve yeni iş alanlarını, eğitim ve sağlık hizmetlerine erişimi planlamıştır.\n\nBu çalışmaların temel amacı nedir?", o:["Göç edenlerin kısa sürede geri gönderilmesi","Bölgedeki tarım alanlarının daraltılması","Bitlis'in nüfusunun azaltılması","Göç edenlerin topluma tam uyum sağlaması"], a:3,
     w:"Türkiye göçü yalnız güvenlik açısından değil insan hakları, aile bütünlüğü ve toplumsal uyum çerçevesinde ele alır. Konut, iş, eğitim ve sağlık planlaması soydaşlarımızın yeni yaşamlarına alışmasını kolaylaştırır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Yurtta sulh, cihanda sulh.” ilkesini benimseyen bir ülkenin dünya barışına katkı sağlamak için öncelikle hangisini yapması beklenir?", o:["Güçlü ülkelerin kendi kurallarını dayatması","Ülkelerin birbirine sınırlarını kapatması","Sorunların uzlaşma yoluyla çözülmesi","Farklılıkların görmezden gelinmesi"], a:2,
     w:"Barış, toplumların saygı, güven ve anlayış içinde çatışmadan bir arada yaşamasıdır. Bunun için ülkeler dostça ilişkiler kurmalı, uluslararası hukuka uymalı ve anlaşmazlıkları masada çözmelidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İslamiyet'i kabul etmeden önceki Türk devletlerinin cihan hâkimiyeti anlayışındaki temel amaç nedir?", o:["Dünyada adalet ve düzeni sağlamak","İslamiyet'i bütün dünyaya yaymak","Yalnız ticaret yollarını ele geçirmek","Komşularıyla bütün bağları koparmak"], a:0,
     w:"Türk Cihan Hâkimiyeti Mefkûresi'ne göre amaç dünyada adalet ve düzeni sağlamaktı. İslam'ı yayma düşüncesi bu amaca İslamiyet'in kabulünden sonra eklendi, Osmanlı her ikisini sürdürdü."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Orhan Bey Dönemi'nde Karesioğulları Beyliği'nin Osmanlı'ya katılması hangi gelişmeye zemin hazırlamıştır?", o:["Edirne'nin fethedilip başkent yapılmasına","Denizciliğin başlayıp Rumeli'ye geçilmesine","Mısır'ın alınıp halifeliğin Osmanlı'ya geçmesine","İstanbul'un kuşatılıp fethedilmesine"], a:1,
     w:"Karesioğulları'nın katılmasıyla Osmanlı denizcilikle tanıştı ve Rumeli'ye geçerek Avrupa'daki ilk fetihlerini yaptı. Edirne I. Murad, İstanbul II. Mehmed, Mısır Yavuz Dönemi'nde alındı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"I. Murad Dönemi'nde bazı Türk beyliklerinden çeyiz ve satın alma yoluyla toprak kazanılması Osmanlı'nın hangi amacına hizmet etmiştir?", o:["Akdeniz'de kalıcı deniz üstünlüğü kurmaya","Avrupa'dan yeni teknikler almaya","Doğu Roma ile ittifak kurmaya","Anadolu'da siyasi birliği güçlendirmeye"], a:3,
     w:"Osmanlı fetihlerin yanı sıra Anadolu Türk siyasi birliğine de önem verdi ve bazı beyliklerin topraklarını savaşmadan, evlilik ve satın almayla kattı. Bu da devletin genişlemesine katkı sağladı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bursa'nın tesliminde rol oynayan tekfurun veziri Saroz, Orhan Gazi'ye kendi yönetimleri altında ağır vergiler ve adaletsizlikle ezildiklerini, Osmanlı'ya bağlanan köylerin ise rahata kavuştuğunu anlatmıştır.\n\nBu anlatıma göre aşağıdakilerden hangisi söylenebilir?", o:["Osmanlı fethettiği yerlerde halktan alınan vergileri sürekli artırmıştır.","Bursa yalnızca denizden kuşatılarak ve uzun bir savaşla alınabilmiştir.","Adaletli yönetim halkın Osmanlı'yı benimsemesini kolaylaştırmıştır.","Osmanlı'ya bağlanan köyler kısa süre sonra Doğu Roma'ya geri dönmüştür."], a:2,
     w:"Halk, ağır vergi ve adaletsizlik yerine Osmanlı'nın adaletli ve anlayışlı yönetimini tercih etti. Bu, yerli halkın gönlünü kazanmayı amaçlayan istimalet politikasının başarısını gösterir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi Osmanlı Devleti'nin iskân politikasıyla ulaşmak istediği amaçlardan biri DEĞİLDİR?", o:["Yerli halkı inancını değiştirmeye zorlamak","Fethedilen bölgelerde kalıcı hâkimiyet sağlamak","Konargöçer toplulukları yerleşik hayata geçirmek","Üretimi artırarak ekonomiyi canlandırmak"], a:0,
     w:"İskânın amaçları kalıcı hâkimiyet, konargöçerlerin yerleşik hayata geçmesi, bölgenin Türkleşmesi ve İslamlaşması, güvenlik ve üretimin artmasıdır. Osmanlı yerli halkın inancına karışmamıştır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"II. Mehmed'in İstanbul kuşatmasından önce Anadolu Hisarı'nın karşısına Rumeli Hisarı'nı yaptırmasının amacı nedir?", o:["Haliç'e gerilen zinciri top ateşiyle kırmak","Doğu Roma'ya denizden yardım ulaşmasını önlemek","Edirne'yi Haçlı saldırılarına karşı korumak","Anadolu beyliklerini Doğu Roma'dan ayırmak"], a:1,
     w:"Boğazın iki yakasındaki hisarlar sayesinde Doğu Roma'ya deniz yoluyla gelebilecek yardım engellendi. Haliç zinciri ise gemilerin karadan yürütülmesiyle etkisiz bırakıldı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi Mısır Seferi'nin (1516–1517) ekonomik sonuçlarındandır?", o:["Kutsal emanetlerin İstanbul'a getirilmesi","Halife unvanının Osmanlı padişahlarına geçmesi","Güney sınırlarının güvence altına alınması","Baharat Yolu'nun Osmanlı denetimine geçmesi"], a:3,
     w:"Baharat Yolu'nun denetimi, Doğu–Batı ticaretinde artan etki ve Mısır'ın vergileri ile verimli toprakları ekonomik sonuçlardır. Kutsal emanetler dinî, halifelik ve güney sınırının güvenliği siyasi sonuçlardır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Fransız İhtilali'nin (1789) yaydığı milliyetçilik akımı çok uluslu Osmanlı Devleti'ni en çok nasıl etkilemiştir?", o:["İpek Yolu gelirlerinin artmasını sağlamıştır","Yeni bir Haçlı birliğini bir süre engellemiştir","Balkanlardaki toplulukların isyanlarına yol açmıştır","Yerli esnafın atölyelerini kapatmasına neden olmuştur"], a:2,
     w:"“Her millete bir devlet” anlayışı Balkanlardaki gayrimüslim toplulukları etkiledi. Milliyetçi isyanlar devletin dağılma sürecini hızlandırdı, Osmanlı da devleti bir arada tutmak için yeni düzenlemeler yaptı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"XIX. yüzyılda bir Osmanlı dokumacısı, pazara gelen ucuz ve bol yabancı kumaşlarla rekabet edemediği için atölyesini kapatmak zorunda kalmıştır.\n\nBu durumun temel nedeni aşağıdakilerden hangisidir?", o:["Avrupa'da fabrikalarda seri ve ucuz üretim yapılması","Reform hareketleriyle kilisenin gücünün azalması","Lale Devri'nde lale yetiştiriciliğinin yaygınlaşması","Tanzimat Fermanı'yla can ve mal güvenliği verilmesi"], a:0,
     w:"Sanayi İnkılabı'yla Avrupa'da buhar gücüyle çalışan fabrikalar kuruldu. Seri ve ucuz üretilen mallar Osmanlı pazarına girince el tezgâhlarına dayalı yerli üretim geriledi, işsizlik arttı."},
    {u:"EK · 2. Yazılı Hazırlık", q:"III. Selim Dönemi'nde İrad-ı Cedid Hazinesi'nin kurulmasının nedeni nedir?", o:["Lale Devri'nde başlayan imar çalışmalarını sürdürmek","Yeni ordunun ve ıslahatların masraflarını karşılamak","Divan'ın yerine kurulan bakanlıkları yönetmek","Avrupa'ya gönderilen elçileri denetlemek"], a:1,
     w:"Nizam-ı Cedid yeniliklerinin giderlerini karşılamak için yeni vergilerle beslenen bir hazine kuruldu. Böylece Avrupa usulüyle eğitilen ordunun ve diğer ıslahatların masrafları ödendi."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Lale Devri'nde, 1720'de Tulumbacılar Ocağı'nın kurulmasının nedeni nedir?", o:["Yeniçerilerin disiplinini yitirip sık sık isyan etmesi","Avrupa'dan gelen ucuz mallarla rekabet edilememesi","Patrona Halil İsyanı'nda şehrin büyük ölçüde zarar görmesi","İstanbul'daki büyük yangınlara müdahalenin yetersiz kalması"], a:3,
     w:"İstanbul'da ahşap evler çok olduğundan büyük yangınlarda karakoldaki askerlerin ve halkın müdahalesi yetmiyordu. Bu yüzden yangınla mücadele için ayrı bir ocak kuruldu."},
    {u:"EK · 2. Yazılı Hazırlık", q:"II. Mahmud'un Divan teşkilatını kaldırıp yerine nazırlıklar (bakanlıklar) kurmasının sonucu nedir?", o:["Halk ilk kez seçtiği temsilcilerle yönetime katıldı.","Osmanlı'da ilk Türk matbaası kurulup kitap basıldı.","Devlet işleri bölümlere ayrılıp daha düzenli yürütüldü.","Yeniçeri Ocağı yeniden güçlenip orduya yön verdi."], a:2,
     w:"Nazırlıklarla devlet işleri konularına göre ayrıldı ve daha düzenli yürüdü. II. Mahmud böylece modern bir devlet teşkilatı oluşturmaya çalıştı. Halkın seçtiği meclis ise 1876'da açıldı."}
  ]);

  /* ---------- 7. sınıf · Türkçe ---------- */
  Q7.tur = (Q7.tur || []).concat([
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Zeynep, kardeşinin doğum günü için haftalarca harçlığını biriktirdi. Pastanın üstüne kardeşinin en sevdiği çizgi film kahramanını yaptırdı. Mumlar üflenirken herkes kardeşine bakıyordu ama Zeynep'in gözleri annesindeydi. Annesi ona göz kırpıp gülümseyince Zeynep derin bir nefes aldı.\n\nBu metinden Zeynep'le ilgili aşağıdaki çıkarımlardan hangisine ulaşılabilir?", o:["Kardeşini kıskandığı için mumlara hiç bakmamıştır.","Emeğinin beğenilip beğenilmediğini merak etmiştir.","Doğum günü kutlamalarından hiç hoşlanmamaktadır.","Pastayı kendisi yapamadığı için üzülmüştür."], a:1,
     w:"Birden çok ipucu birleşiyor: Zeynep haftalarca harçlık biriktirmiş, kutlamada gözü annesinde, annesi göz kırpınca rahatlayıp derin bir nefes alıyor. Demek ki emeğinin beğenilip beğenilmediğini merak etmiş. Kardeşi için bu kadar emek vermesi kıskançlıkla bağdaşmaz."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"(I) Elif yeni taşındığı mahallede kimseyi tanımıyordu. (II) Bir gün komşunun kedisi ağaca çıkıp inemeyince Elif bir merdiven buldu ve kediyi kurtardı. (III) Bu olaydan sonra mahalledeki çocuklar Elif'i oyunlarına çağırmaya başladı. (IV) Elif artık yeni mahallesini çok seviyor.\n\nBu metinde olayın başladığı, yani gelişme bölümünü başlatan cümle hangisidir?", o:["I","II","III","IV"], a:1,
     w:"I. cümle kişiyi ve durumu tanıtır (giriş). Olay II. cümlede başlar: Kedi ağaçta kalır, Elif onu kurtarır (gelişme). III ve IV. cümleler olayın sonucunu anlatır."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Aşağıdaki cümlelerin hangisinde konuşturma sanatı vardır?", o:["Gözlerin iki deniz gibi derin ve maviydi.","Öyle bağırdı ki sesi ta öbür köyden duyuldu.","Rüzgâr pencereme eğilip “Uyan artık!” dedi.","Dallar rüzgârın ezgisiyle dans ediyordu."], a:2,
     w:"Konuşturma, insan dışı bir varlığı konuşur gibi anlatmaktır: Rüzgâr “Uyan artık!” diyor, konuşan rüzgâr aynı zamanda kişileştirilmiştir. Dalların dans etmesi yalnız kişileştirme, deniz gibi gözler benzetme, sesin öbür köyden duyulması abartmadır."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Güzel sözün insanlar arasındaki kırgınlıkları giderdiği çok eskiden beri bilinir. Yunus Emre de bu gerçeği “Söz ola kese savaşı” diyerek dile getirmiştir.\n\nBu paragrafta düşünceyi geliştirmek için hangi yoldan yararlanılmıştır?", o:["Tanık gösterme","Tanımlama","Karşılaştırma","Sayısal verilerden yararlanma"], a:0,
     w:"Yazar düşüncesini güçlendirmek için tanınmış bir şairin, Yunus Emre'nin sözünü aktarıyor. Bir başkasının sözünü dayanak olarak kullanmak tanık göstermedir."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Aşağıdaki cümlelerin hangisinde pekiştirmeli sözcük doğru yazılmıştır?", o:["Gökyüzü bu sabah mas mavi görünüyordu.","Bahar gelince çimenler yem yeşil oldu.","Ustalar duvarları bem beyaz boyamış.","Kardeşimin odası tertemiz kalmıştı."], a:3,
     w:"Pekiştirmeli sözcükler bitişik yazılır: tertemiz, masmavi, yemyeşil, bembeyaz. Bunları ikilemelerle karıştırma, ikilemeler (mavi mavi, yeşil yeşil) ayrı yazılır."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"“Ankara ( ) Kayseri treni her sabah dokuzda kalkıyor.” cümlesinde ayraçla gösterilen yere hangi işaret getirilmelidir?", o:["Kısa çizgi (-)","Eğik çizgi (/)","Virgül (,)","Noktalı virgül (;)"], a:0,
     w:"Kısa çizgi “ara, ile, -den -e” anlamı vermek için yer adları ya da sayılar arasına konur. Ankara-Kayseri treni, Ankara ile Kayseri arasında çalışan trendir."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Aşağıdaki cümlelerin hangisindeki yargı süreklilik bildirmektedir?", o:["Şu anda kütüphanede ders çalışıyorum.","Mektubu dün akşam postaya verdim.","Gelecek ay dedemlere gideceğiz.","Annem hiçbir zaman sözünden dönmez."], a:3,
     w:"“Hiçbir zaman” sözü yargının her zaman geçerli olduğunu gösterir: Annem sözünden dönmeyen biridir. Diğer cümleler şimdiki anı (şu anda), geçmişi (dün) ve geleceği (gelecek ay) anlatıyor."}
  ]);
  H7.tur = (H7.tur || []).concat([
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Güzel söz açar gönül,\nTatlı dille güler yüz.\nSevgiyle söylenen söz\nKışın bile açar gül.\n\nBu dörtlüğün uyak düzeni aşağıdakilerden hangisidir?", o:["Çapraz uyak (abab)","Sarma uyak (abba)","Mani tipi uyak (aaxa)","Koşma tipi uyak (xaxa)"], a:1,
     w:"1. dize (gönül) ile 4. dize (gül), 2. dize (yüz) ile 3. dize (söz) uyaklıdır. Dıştaki dizeler kendi arasında, içteki dizeler kendi arasında uyaklı olduğu için sarma uyaktır."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"“Lale Sokak No: 12 ( ) 4” adresinde apartman numarası ile daire numarasını ayırmak için ayraçla gösterilen yere hangi işaret getirilmelidir?", o:["Kısa çizgi (-)","Nokta (.)","Eğik çizgi (/)","İki nokta (:)"], a:2,
     w:"Adres yazarken apartman numarası ile daire numarası eğik çizgiyle ayrılır: No: 12/4. Kısa çizgi ise “ile, arası” anlamı verir."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"“Ödevini ne de erken (!) bitirmişsin, teslime beş dakika kalmış.” cümlesinde ayraç içindeki ünlem işareti hangi anlamı katmak için kullanılmıştır?", o:["Alay ve kinaye","Sevinç ve coşku","Şüphe ve belirsizlik","Rica ve istek"], a:0,
     w:"Ayraç içindeki ünlem söylenenin tersinin kastedildiğini gösterir: Ödev teslimden beş dakika önce bitmiş, yani hiç de erken değil. Şüpheli bir bilgiden sonra ise ayraç içinde soru işareti kullanılır."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Bir metnin özeti yazılırken aşağıdakilerden hangisine yer VERİLMEZ?", o:["Metnin ana düşüncesine","Önemli olaylara ve bilgilere","Olayın geçtiği yere ve zamana","Kendi yorumlarımıza"], a:3,
     w:"Özet, metnin ana düşüncesini, önemli olaylarını, kişilerini, yerini ve zamanını kısaca ve kendi cümlelerimizle aktarır. Kişisel yorum özete katılmaz."},
    {u:"TEMA 3 · İletişim ve Sosyal İlişkiler", q:"Sınıfta izlenen kısa bir filmle ilgili aşağıdaki görüşlerden hangisi gerekçeli bir eleştiridir?", o:["Bence film çok sıkıcıydı, bir daha asla böyle bir film izlemem.","Konu ilgi çekiciydi ama sesler kısık olduğu için bazı sözler duyulmadı.","Bu film hem çok güzel hem çok önemli, herkes mutlaka izlemeli.","Film yirmi dakika sürdü ve okulun konferans salonunda izlendi."], a:1,
     w:"Eleştiri, bir eserin güçlü ve zayıf yönlerini gerekçeleriyle ortaya koyar: Konunun ilgi çekici olduğu söyleniyor, seslerin kısık olması da gerekçesiyle eleştiriliyor. Gerekçesiz beğeni ya da beğenmeme eleştiri olmaz, süreyi bildirmek ise yalnızca bilgi vermektir."}
  ]);
  EKC7.tur = (EKC7.tur || []).concat([
    {u:"EK · 2. Yazılı Hazırlık", q:"Ulusal bilgi yarışmasında birinci olan Can, ödül töreninde başarısını takım arkadaşlarına ve öğretmenine borçlu olduğunu söyledi. Kendisini öven gazetecilere de “Ben yalnızca üzerime düşeni yaptım.” diye cevap verdi. Herkes onun bu mütevazı tavrını takdir etti.\n\nMetinde geçen “mütevazı” sözcüğünün anlamı aşağıdakilerden hangisidir?", o:["Kendine aşırı güvenen","Utangaç ve sessiz","Hırslı ve rekabetçi","Alçak gönüllü"], a:3,
     w:"İpuçları metinde: Can başarısını başkalarına borçlu olduğunu söylüyor, övülünce “Yalnızca üzerime düşeni yaptım.” diyor. Başarısıyla övünmeyen bu tavır alçak gönüllülüktür. Gazetecilerle rahatça konuştuğu için utangaç da denemez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Okulumuzun “Kitap Takası” etkinliği bu yıl üçüncü kez yapıldı. Öğrenciler evlerinde okudukları kitapları getirip başka kitaplarla değiştirdi. Etkinlikte iki yüz on kitap el değiştirdi. Kalan kitaplar köy okullarına gönderildi.\n\nMetne göre etkinlikte el değiştirmeyen kitaplara ne yapılmıştır?", o:["Okul kütüphanesine konulmuştur.","Köylerdeki okullara yollanmıştır.","Sahiplerine geri verilmiştir.","Gelecek yılki etkinliğe saklanmıştır."], a:1,
     w:"Cevap metinde açıkça yazıyor: “Kalan kitaplar köy okullarına gönderildi.” Yüzey anlam sorusunda cevabı ilgili cümlede ara, yorum katma."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Takım arkadaşları onu yalnız bırakınca Kerem'in hevesi kursağında kaldı.” cümlesindeki deyimin anlamı aşağıdakilerden hangisidir?", o:["İstediği bir şeye kavuşamamak","Bir işi büyük bir istekle sürdürmek","Bir konuda çok çabuk karar vermek","Bir sonuca bakıp çok sevinmek"], a:0,
     w:"Hevesi kursağında kalmak, istediği bir şeyi gerçekleştiremeden ondan yoksun kalmaktır. Arkadaşları onu yalnız bırakınca Kerem yapmak istediği şeyi yapamamış."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sözcük havuzu: vefa · özveri · merhamet · cömertlik\n\n“Dedem, yıllar önce kendisine yardım eden öğretmenini hiç unutmadı. Her bayram onu arayıp elini öpmeye gitti. Bu davranış, dedemin ……… duygusunun bir göstergesiydi.”\n\nBoşluğa havuzdaki sözcüklerden hangisi getirilmelidir?", o:["özveri","merhamet","vefa","cömertlik"], a:2,
     w:"Yıllar önceki bir iyiliği unutmamak ve ilişkiyi sürdürmek vefadır. Özveri başkası için kendi isteğinden vazgeçmek, merhamet acıma duygusu, cömertlik eli açıklıktır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki cümlelerin hangisinde bir yazım yanlışı yapılmıştır?", o:["Misafirler kapıda tek tek karşılandı.","Bahçedeki çimenler yemyeşil olmuş.","Gökyüzü kap kara bulutlarla kaplandı.","Kardeşimle evde baş başa kaldık."], a:2,
     w:"Pekiştirmeli sözcükler bitişik yazılır: kapkara, yemyeşil. İkilemeler ise ayrı yazılır: tek tek, baş başa."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki cümlelerin hangisinde virgüllerden biri yerine noktalı virgül (;) kullanılmalıdır?", o:["Sabah erkenden kalktık, kahvaltımızı yaptık, yola çıktık.","Defterini, kalemini, silgisini çantasına koydu.","Annem çay, peynir, zeytin, babam meyve suyu, simit aldı.","Kardeşim çok sevindi, hemen bana sarıldı."], a:2,
     w:"Virgüllerle ayrılmış iki takım var: annenin aldıkları ve babanın aldıkları. Bu takımları noktalı virgül ayırır: “…zeytin; babam meyve suyu…”. Diğer cümlelerde tek bir dizi ya da kısa sıralı cümleler var, virgül yeterli."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Okul panosundaki bir afişte devrilmiş bir su bardağı ve çatlamış bir toprak görülüyor. Toprağın üzerindeki küçük bir fidan boynunu bükmüş. Afişin altında “Bugün boşa akıttığın su, yarın içeceğin sudur.” yazıyor.\n\nBu afişle verilmek istenen mesaj aşağıdakilerden hangisidir?", o:["Su bilinçsizce harcanırsa gelecekte sıkıntı yaşanır.","Fidanlar her gün düzenli olarak ve bolca sulanmalıdır.","Kuraklık yalnızca tarım yapılan alanları etkileyen bir sorundur.","Bardaklar suyu dökmeyecek biçimde dikkatle taşınmalıdır."], a:0,
     w:"Görseldeki ayrıntılar birleşince mesaj ortaya çıkıyor: Devrilen bardak suyun israfını, çatlamış toprak ve boynu bükük fidan kuraklığı, alttaki yazı da bugünkü davranışın yarına etkisini anlatıyor. Afiş suyu bilinçli kullanmaya çağırıyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir sütun grafiğinde bir sınıfın aylara göre okul kütüphanesinden ödünç aldığı kitap sayıları gösteriliyor:\nEylül: 12 · Ekim: 18 · Kasım: 25 · Aralık: 31\n\nGrafiğe göre aşağıdakilerden hangisi söylenebilir?", o:["En çok kitabın alındığı ay ekim ayı olmuştur.","Alınan kitap sayısı her ay bir önceki aydan fazladır.","Aralıkta alınan kitap sayısı eylüldekinin üç katıdır.","Kasımda alınan kitap sayısı ekimdekinin iki katıdır."], a:1,
     w:"Sayılar 12, 18, 25, 31 diye her ay artıyor. En çok kitap aralıkta alınmış. 12'nin üç katı 36, 18'in iki katı da 36 eder, grafikteki sayılar bunları tutmuyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kapı çalınınca Ali yerinden fırladı. Koşarak kapıyı açtı ama karşısında kargo görevlisi yerine komşu teyzeyi görünce omuzları düştü.\n\nAli'nin bu davranışından aşağıdakilerden hangisi çıkarılabilir?", o:["Komşu teyzenin evine gelmesinden hiç hoşlanmamaktadır.","Kapıyı açmaktan ve yabancılarla konuşmaktan çekinmektedir.","Kargo görevlilerinin sık sık kapıyı çalmasından bıkmıştır.","Beklediği paket gelmeyince hayal kırıklığı yaşamıştır."], a:3,
     w:"İpuçları yakın ve açık: Kapı çalınınca yerinden fırlaması bir beklentiyi, kargo görevlisi yerine başkasını görünce omuzlarının düşmesi hayal kırıklığını gösteriyor. Bu, tek bir durumdan çıkarılan basit bir çıkarımdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Mahallemizin en yaşlısı olan Hasan Amca her sabah parktaki çeşmeye gelir, çeşmeyi bezle siler. Çocuklar bir gün ona neden bu kadar uğraştığını sordu. Hasan Amca gülümsedi: “Bu çeşmeyi babam yaptırdı. Su içen herkes onu hayırla anar.” dedi. O günden sonra çocuklar da parka gelince çöpleri toplamaya başladı.\n\nBu metinden aşağıdaki sonuçlardan hangisine ulaşılabilir?", o:["Yaşlıların sözleri çocuklar tarafından çoğu zaman önemsenmez.","İyi örnek olan davranışlar çevredekileri de harekete geçirir.","Bir işi başkasına bırakmak sorumluluktan kaçmanın en kolay yoludur.","Eski eserler yenileriyle değiştirildiğinde mahalleler güzelleşir."], a:1,
     w:"Birden çok ipucu birleşiyor: Hasan Amca'nın her gün çeşmeyi temizlemesi, bunun nedenini anlatması ve çocukların o günden sonra çöp toplamaya başlaması. Bu sonuç tek bir cümleden değil, metnin bütününden çıkarılır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Son yıllarda bazı bölgelerde arı sayısı hızla azaldı. Bunun en önemli nedenlerinden biri tarım ilaçlarının bilinçsizce kullanılmasıdır. Arıların azalması çiçekli bitkilerin tozlaşmasını da zorlaştırır. Bu yüzden meyve ve sebze üretimi düşer.\n\nBu paragraf hangi metin yapısıyla düzenlenmiştir?", o:["Sıralama (zaman sırası)","Karşılaştırma","Sebep-sonuç","Tanımlama"], a:2,
     w:"Paragraf bir olayın (arıların azalması) nedenini ve doğurduğu sonuçları anlatıyor. “Nedenlerinden biri”, “bu yüzden” gibi ifadeler bu yapının ipuçlarıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Lületaşı, Eskişehir yöresinde çıkarılan, beyaz renkli, hafif ve kolay işlenen bir taştır. Ustalar bu taşı oyarak süs eşyaları ve hediyelik ürünler yapar. Lületaşı işlemeciliği, Eskişehir'e özgü geleneksel bir el sanatıdır.\n\nBu paragrafın anahtar kelimeleri aşağıdakilerin hangisinde birlikte verilmiştir?", o:["lületaşı, beyaz renk, hafiflik","lületaşı, Eskişehir, el sanatı","Eskişehir, usta, hediyelik ürün","yöre, taş, süs eşyası"], a:1,
     w:"Anahtar kelimeler metnin konusunu taşır, metin onların çevresinde gelişir. Paragraf Eskişehir'e özgü bir el sanatı olan lületaşı işlemeciliğini anlatıyor. Renk, hafiflik, usta, hediyelik ürün gibi kelimeler ayrıntıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Okul kantininde şekerli içecekler yerine ayran ve su satılmalı. Okulumuzda yapılan ankete katılan 300 öğrencinin 240'ı bu öneriyi desteklediğini söyledi. Ayrıca kantinin geçen ay sattığı içeceklerin yarısından fazlası şekerli içeceklerdi.\n\nYazar okuru ikna etmek için en çok hangi teknikten yararlanmıştır?", o:["Duygulara seslenme","Uzman görüşüne başvurma","Okura soru yöneltme","Sayısal veri kullanma"], a:3,
     w:"Yazar görüşünü sayılarla destekliyor: 300 öğrencinin 240'ı, satılan içeceklerin yarısından fazlası. Metinde bir uzmanın sözü, okura yöneltilen bir soru ya da duygusal bir çağrı yok."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir video sitesinde şöyle bir başlık var: “İNANAMAYACAKSINIZ! Bu taşı cebinde taşıyan herkes sınavlarda tam puan alıyor!” Videoyu yükleyen hesabın adı “Mucize Taşlar Mağazası”. Video bir günde yüz bin kez izlenmiş.\n\nBu içeriği değerlendiren bilinçli bir izleyici hangi yargıya varır?", o:["İçerik kanıt sunmadığı ve satış amacı taşıdığı için güvenilmezdir.","Çok izlenen bir video olduğu için içerikteki bilgi doğrudur.","Taşın gerçekten işe yarayıp yaramadığı bir tane alınarak denenmelidir.","Başlık büyük harfle yazıldığına göre önemli bir haber verilmektedir."], a:0,
     w:"Medya içeriğini değerlendirirken kimin hazırladığına ve amacına bakılır. Hesap bir mağazaya ait, yani amaç satış. Başlık abartılı ve hiçbir kanıt yok. İzlenme sayısı ya da büyük harf bir bilginin doğru olduğunu göstermez."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir diş macunu reklamında ünlü bir futbolcu gülümseyerek “Ben de her sabah bunu kullanıyorum.” diyor. Reklamda ürünün içeriğiyle ilgili hiçbir bilgi verilmiyor.\n\nBu reklamda izleyiciyi ikna etmek için hangi teknik kullanılmıştır?", o:["Ürünle ilgili sayısal veriler sunma","Ürünü rakipleriyle karşılaştırma","Bir diş hekiminin uzman görüşünü aktarma","Sevilen bir sporcunun etkisini kullanma"], a:3,
     w:"Futbolcunun diş sağlığı konusunda uzmanlığı yoktur. Reklam, izleyicinin bu tanınmış kişiye duyduğu sevgi ve hayranlığı ürüne aktarmaya çalışıyor. Bilinçli izleyici ürünü içeriğine göre değerlendirir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir öğrenci, Çanakkale konulu bir metinden aldığı sözcükleri iki gruba ayırdı:\n1. grup: cesaret, sabır, özveri\n2. grup: siper, top, tüfek\n\nBu sınıflandırmada kullanılan ölçüt aşağıdakilerden hangisidir?", o:["Tek ya da çok heceli olmaları","Eş ya da zıt anlamlı olmaları","Soyut ya da somut olmaları","Türkçe ya da yabancı kökenli olmaları"], a:2,
     w:"Cesaret, sabır ve özveri duyularla algılanamayan soyut kavramlardır. Siper, top ve tüfek ise görülüp dokunulabilen somut varlıklardır. Sınıflandırmada her grubun tek ve açık bir ölçütü olmalıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"(I) Selin ile Deniz sıra arkadaşı ve çok yakın iki dosttu. (II) Bir gün Deniz, Selin'in defterini izinsiz alıp sınıfa gösterince araları bozuldu. (III) Günlerce konuşmadılar, teneffüslerde ayrı köşelerde durdular. (IV) Sonunda Deniz özür diledi ve iki arkadaş barıştı.\n\nBu metnin giriş bölümünde aşağıdakilerden hangisi yapılmıştır?", o:["Kişiler ve aralarındaki bağ tanıtılmıştır.","Arkadaşların neden küstüğü anlatılmıştır.","Sorun çözüme kavuşturulmuştur.","Küslüğün ne kadar sürdüğü belirtilmiştir."], a:0,
     w:"Giriş bölümü I. cümledir: Selin ile Deniz ve aralarındaki yakın dostluk tanıtılıyor. Küslüğün nedeni ve süresi gelişmede (II ve III), barışma sonuçta (IV) anlatılıyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Güler yüzle bir selam\nIsıtır her yüreği.\nBir teşekkür, bir kelam\nAçar dostluk çiçeği.\n\nBu dörtlükle ilgili aşağıdakilerden hangisi doğrudur?", o:["Dizeleri arasında hiç uyak yoktur.","Dizeleri yedişer heceden oluşur.","Serbest ölçüyle yazılmıştır.","Beş dizeden oluşan bir benttir."], a:1,
     w:"Her dize yedi hecedir: Gü-ler-yüz-le-bir-se-lam. Dörtlük hece ölçüsüyle yazılmıştır. Yalnızca 1. ile 3. dize (selam – kelam), 2. ile 4. dize (yüreği – çiçeği) uyaklıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Kardeşimin sesi, sabah kuşları gibi neşeliydi.” cümlesinde benzetme yönü aşağıdakilerden hangisidir?", o:["kardeşimin sesi","sabah kuşları","gibi","neşeli"], a:3,
     w:"Benzeyen “kardeşimin sesi”, kendisine benzetilen “sabah kuşları”, benzetme edatı “gibi”dir. İki varlık arasındaki ortak özellik, yani benzetme yönü “neşeli” olmaktır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Annem kapıdan girince evdeki bütün eşyalar sevinçle gülümsedi. Dedemin kahkahası ise yedi mahalleden duyuldu.\n\nBu metinde hangi iki söz sanatı birlikte kullanılmıştır?", o:["Kişileştirme ve abartma","Benzetme ve konuşturma","Konuşturma ve abartma","Benzetme ve kişileştirme"], a:0,
     w:"Eşyalara insana özgü “gülümsemek” eylemi verilmiş: kişileştirme. Bir kahkahanın yedi mahalleden duyulması olağandan çok büyütülmüş bir anlatımdır: abartma. Metinde “gibi” ile kurulan bir benzetme ya da konuşan bir varlık yok."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Günlük konuşmamızda nezaket bildiren pek çok kalıp söz vardır. Örneğin yemekten sonra “Elinize sağlık.”, yola çıkan birine “Güle güle.”, hastalanan birine “Geçmiş olsun.” deriz.\n\nBu paragrafta düşünce hangi yolla geliştirilmiştir?", o:["Tanık gösterme","Karşılaştırma","Örneklendirme","Sayısal verilerden yararlanma"], a:2,
     w:"Yazar “nezaket bildiren kalıp sözler” düşüncesini somut örneklerle açıklıyor: Elinize sağlık, Güle güle, Geçmiş olsun. Bir düşünceyi örneklerle açıklamak örneklendirmedir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Okulumuzda “Nezaket Haftası” düzenlendi. Hafta boyunca her sabah bir öğrenci okul radyosundan bir nezaket sözcüğünün önemini anlattı. Sınıflara “Lütfen, teşekkür ederim, özür dilerim” yazan kartlar asıldı. Hafta sonunda yapılan ankette öğrencilerin çoğu, arkadaşlarıyla daha az tartıştıklarını söyledi.\n\nBu metnin en uygun özeti aşağıdakilerden hangisidir?", o:["Nezaket Haftası boyunca okul radyosunda konuşmalar yapıldı, kartlar asıldı.","Nezaket sözcükleri insanlar arasındaki bütün sorunları kolayca çözer.","Ankete katılan öğrencilerin çoğu nezaket sözcüklerini önceden bilmiyordu.","Nezaket Haftası etkinlikleri öğrenciler arasındaki tartışmaları azalttı."], a:3,
     w:"Özet metnin bütününü kısaca kapsar: Ne yapıldı (Nezaket Haftası etkinlikleri) ve sonuç ne oldu (tartışmalar azaldı). Yalnız ayrıntıları sıralayan, metinde olmayan bilgi veren ya da genelleme katan cümle özet olamaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Can, “kitap okumak ile film izlemek” konulu bir karşılaştırma yazısı yazıyor.\n\nCan aşağıdaki cümlelerden hangisini yazısına eklerse bir karşılaştırma yapmış olur?", o:["Geçen hafta sonu ailemle birlikte sinemada çok güzel bir film izledik.","Kitap okumak, insanın kelime hazinesini geliştiren güzel bir alışkanlıktır.","Sinemaya gitmek isteyenlerin önceden bilet alması gerekir.","Kitapta olayları biz canlandırırız, filmde ise görüntüler hazır gelir."], a:3,
     w:"Karşılaştırmada iki şey aynı yönüyle (burada olayları algılama biçimiyle) yan yana konur, benzerlik ya da farklılık gösterilir. “ise” bağlacı farkı ortaya koyuyor. Diğer cümleler yalnızca birinden söz ediyor."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki cümlelerin hangisinde anlamca çelişen sözcükler bir arada kullanılmıştır?", o:["Galiba bu akşam yine yağmur yağacak.","Kesinlikle yarın belki size uğrarız.","Mutlaka bu kitabı okumalısın.","Herhalde otobüs yine yolda kaldı."], a:1,
     w:"“Kesinlikle” bir işin kesin olduğunu, “belki” ise yalnızca olası olduğunu bildirir. İkisi aynı cümlede çelişir. Diğer cümlelerdeki “galiba, mutlaka, herhalde” tek başına kullanıldığı için anlam tutarlıdır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki cümlelerin hangisinde ayraç içindeki ünlem işareti (!) yerinde kullanılmıştır?", o:["Eyvah (!) Trene yine geç kaldık.","Bu köprü 1650 (!) yılında yapılmış olabilir.","Çok erken (!) geldin, film çoktan bitmiş.","Yarın akşam bize gelir misin (!)"], a:2,
     w:"Ayraç içindeki ünlem, alay, kinaye ya da küçümseme anlamı katılmak istenen sözden hemen sonra gelir: Film bitmişken “çok erken” denmesi alaydır. “Eyvah” gibi ünlemlerden sonra işaret ayraçsız konur (Eyvah!), şüpheli bir tarihten sonra (?) gelir, soru cümlesi soru işaretiyle biter."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdaki cümlelerin hangisinde eğik çizgi (/) yerinde kullanılmıştır?", o:["Mektubu Lale Sok. No: 7/3 adresine gönderdim.","Ankara/İzmir otobüsü her sabah sekizde kalkıyor.","Toplantıya 9/12 kişinin katılması bekleniyor.","Müzede 1960/1970 yıllarına ait fotoğraflar var."], a:0,
     w:"Eğik çizgi adreste apartman numarası ile daire numarasını ayırır: No: 7/3. “Ankara ile İzmir arası, 9 ile 12 arası, 1960 ile 1970 arası” anlamları için kısa çizgi kullanılır: Ankara-İzmir, 9-12, 1960-1970."}
  ]);

  /* Soruları ünite numarasına göre yeniden grupla (08b ile aynı kural) */
  [Q6, Q7].forEach(function(Q){
    Object.keys(Q).forEach(function(k){
      Q[k].sort(function(a, b){
        var x = String(a.u).match(/(\d+)/), y = String(b.u).match(/(\d+)/);
        return (x ? parseInt(x[1], 10) : 99) - (y ? parseInt(y[1], 10) : 99);
      });
    });
  });
